	["1. Llega al nivel 40. La montura y la equitación se compran a la vez: junta el oro mientras subes."] = "1. Atteignez le niveau 40. La monture et la compétence de monte s'achètent en même temps : économisez de l'or en montant de niveau.",
	["2. Ve con el instructor de equitación de tu raza y aprende la de aprendiz."] = "2. Allez voir le maître de monte de votre race et apprenez la monte d'apprenti.",
	["3 de XP, 3 de oro, 3 de XP, 20 de tu profesión y 3 de clase para un objeto único."] = "3 quêtes d'XP, 3 d'or, 3 d'XP, 20 de votre métier et 3 de classe pour un objet unique.",
	["3. Compra la montura con el vendedor de tu raza (al lado del instructor) y úsala para aprenderla."] = "3. Achetez la monture chez le vendeur de votre race (à côté du maître) et utilisez-la pour l'apprendre.",
	["4. A nivel 60, el mismo instructor enseña la de oficial y el vendedor tiene las rápidas."] = "4. Au niveau 60, le même maître enseigne la monte de compagnon et le vendeur propose les montures rapides.",
	["A %s"] = "À %s",
	["A %s le queda poco"] = "%s expire bientôt",
	["A Entrañas se baja por elevadores desde las ruinas de la capital de Lordaeron."] = "On descend à Fossoyeuse par des ascenseurs depuis les ruines de la capitale de Lordaeron.",
	["A Mis planes"] = "Vers Mes plans",
	["A Ragnaros no le gusta que lo despierten antes de tiempo, y su mayordomo Executus lo paga caro."] = "Ragnaros n'aime pas qu'on le réveille trop tôt, et son chambellan Executus le paie cher.",
	["A Silithus se entra desde el Cráter de Un'Goro."] = "On entre en Silithus par le cratère d'Un'Goro.",
	["A distancia"] = "À distance",
	["A entregar tus misiones"] = "Allez rendre vos quêtes",
	["A la entrada de Ventormenta, estatuas de los grandes héroes de la Segunda Guerra reciben a los visitantes."] = "À l'entrée de Hurlevent, des statues des grands héros de la Deuxième Guerre accueillent les visiteurs.",
	["A la vista: %d de la manada · %d de tu grupo"] = "En vue : %d de la meute · %d de votre groupe",
	["A las demás les dice qué les falta: tu nivel o una misión antes."] = "Pour les autres, il indique ce qui manque : votre niveau ou une quête préalable.",
	["A los lados del modelo, un botón por ranura: un clic oculta esa pieza y otro la vuelve a poner."] = "De chaque côté du modèle, un bouton par emplacement : un clic masque cette pièce, un autre la remet.",
	["A mitad de la pelea aparecen espectros de hielo: mátenlos rápido o usen ataques en área."] = "À mi-combat, des spectres de givre apparaissent : tuez-les vite ou utilisez des attaques de zone.",
	["A mitad de la pelea se protege con un escudo y prepara una gran explosión: cuando lo veas brillar, ¡aléjate de él!"] = "À mi-combat, il se protège d'un bouclier et prépare une grosse explosion : quand vous le voyez briller, éloignez-vous de lui !",
	["A nivel 10 haces las misiones para domar a tu primera mascota."] = "Au niveau 10, tu fais les quêtes pour apprivoiser ton premier familier.",
	["A nivel 20 aprendes Lobo fantasmal: ¡te vuelves un lobo como yo! Corre, que te echo una carrera."] = "Au niveau 20, tu apprends Loup fantôme : tu deviens un loup comme moi ! Allez, on fait la course.",
	["A nivel 60 sigue la rápida: equitación de oficial y una montura épica."] = "Au niveau 60 vient la rapide : monte de compagnon et une monture épique.",
	["A probar"] = "À tester",
	["A quién ir"] = "Qui aller voir",
	["A su entrenador"] = "Chez son maître",
	["A tu gusto"] = "À votre goût",
	["A tu lado"] = "À vos côtés",
	["A tu medida"] = "À ta façon",
	["A tu nivel los enemigos caen rápido: remata con 3 puntos de combo."] = "À votre niveau, les ennemis tombent vite : achevez avec 3 points de combo.",
	["A un clic"] = "En un clic",
	["A veces"] = "Parfois",
	["A veces el golpe ni te toca."] = "Parfois, le coup ne vous touche même pas.",
	["A veces el juego tarda o no deja mover a nadie más a esa capa. Puedes salir del grupo y probar con otra."] = "Parfois le jeu met du temps ou ne laisse plus personne passer sur cette couche. Tu peux quitter le groupe et en essayer une autre.",
	["A veces pescas cajas y botellas con mensajes que empiezan una misión."] = "Parfois, tu pêches des caisses et des bouteilles avec des messages qui commencent une quête.",
	["A veces salen gemas al minar: guárdalas, porque varias profesiones las usan en sus recetas."] = "Parfois, des gemmes sortent en minant : garde-les, plusieurs métiers les utilisent dans leurs recettes.",
	["Abajo"] = "Le bas",
	["Abajo del modelo, elige lo que hace tu personaje (caminar, bailar, saludar...) y páusalo."] = "Sous le modèle, choisissez ce que fait votre personnage (marcher, danser, saluer...) et mettez-le en pause.",
	["Abalorio"] = "Bijou",
	["Abalorios"] = "Bijoux",
	["Abandonar"] = "Abandonner",
	["Abandonar marcadas (%d)"] = "Abandonner les cochées (%d)",
	["Abandonaste %d misiones"] = "Vous avez abandonné %d quêtes",
	["Abierta"] = "Ouverte",
	["Abierta: si alguien de la manada pide entrar, Alfa lo invita a tu grupo (fuera de combate)."] = "Ouverte : si quelqu’un de la meute demande à entrer, Alfa l’invite dans ton groupe (hors combat).",
	["Abiertas"] = "Ouverts",
	["Abrazo vampírico: tu daño de sombras te cura."] = "Étreinte vampirique : vos dégâts d'Ombre vous soignent.",
	["Abre Heridas profundas."] = "Ouvre Blessures profondes.",
	["Abre Hoy: ahí te digo lo más útil para este momento en grande, y tu camino a un par de clics."] = "Ouvre Aujourd’hui : je t’y montre en grand ce qui est le plus utile maintenant, et ton chemin à deux clics.",
	["Abre Paisaje y gráficos"] = "Ouvre Paysage et graphismes",
	["Abre Recolección. Con «ruta», crea y sigue una ruta de farmeo en tu zona."] = "Ouvre Récolte. Avec « ruta », crée et suit un itinéraire de farm dans votre zone.",
	["Abre desde el sigilo para empezar con ventaja."] = "Ouvrez depuis le camouflage pour commencer avec un avantage.",
	["Abre el mapa del juego en esta misma zona. En combate el mapa del juego no se abre desde Alfa."] = "Ouvre la carte du jeu sur cette même zone. En combat, la carte du jeu ne s'ouvre pas depuis Alfa.",
	["Abre el mapa y haz clic derecho (o Mayús+clic) donde quieras uno: le pones nombre, ícono y color, y la flecha te lleva cuando quieras. En el mapa del juego, Mayús+clic derecho."] = "Ouvrez la carte et faites un clic droit (ou Maj+clic) là où vous en voulez un : donnez-lui un nom, une icône et une couleur, et la flèche vous y mène quand vous voulez. Sur la carte du jeu, Maj+clic droit.",
	["Abre el modo pesca (aquí, con /alfa pesca o al ponerte la caña) y pulsa %s: tu tecla te pone el equipo, el cebo, lanza y recoge cuando salpica."] = "Ouvrez le mode pêche (ici, avec /alfa pesca ou en équipant votre canne) et appuyez sur %s : votre touche met votre équipement, applique l'appât, lance et remonte au plouf.",
	["Abre el modo pesca y elige tu tecla: te pone el equipo, el cebo, lanza y recoge cuando salpica."] = "Ouvrez le mode pêche et choisissez votre touche : elle met votre équipement, applique l'appât, lance et remonte au plouf.",
	["Abre el modo pesca y pulsa tu tecla: lo que saques aparece aquí."] = "Ouvrez le mode pêche et appuyez sur votre touche : ce que vous attrapez apparaît ici.",
	["Abre la Cocina del juego (el botón lo hace) y vuelve a pulsar."] = "Ouvrez la fenêtre Cuisine du jeu (le bouton le fait) et appuyez à nouveau.",
	["Abre la Enciclopedia y en la ficha del objeto toca «Agregar a mi ruta»."] = "Ouvrez l'Encyclopédie et, sur la fiche de l'objet, touchez « Ajouter à mon itinéraire ».",
	["Abre la casa de subastas para escanear."] = "Ouvrez l'hôtel des ventes pour scanner.",
	["Abre la casa de subastas y pulsa «Escanear con Alfa» para saber cuánto valen tus objetos."] = "Ouvrez l'hôtel des ventes et appuyez sur « Scanner avec Alfa » pour savoir combien valent vos objets.",
	["Abre la guía de Alfa que te lleva a conseguir este objeto."] = "Ouvre le guide d'Alfa qui vous mène à cet objet.",
	["Abre la pelea a distancia antes de que llegue."] = "Engagez le combat à distance avant qu'il ne vous atteigne.",
	["Abre la pelea: te acerca al enemigo y te da ira."] = "Ouvre le combat : vous rapproche de l'ennemi et vous donne de la rage.",
	["Abre la siguiente fila."] = "Ouvre la rangée suivante.",
	["Abre la ventana Historias."] = "Ouvre la fenêtre Histoires.",
	["Abre la ventana de clic para lanzar de Blizzard para que armes ahí los mismos clics y cures igual en sus marcos de grupo (el juego no deja que un addon los copie)."] = "Ouvre la fenêtre de lancement par clic de Blizzard pour y configurer les mêmes clics et soigner de la même façon sur ses cadres de groupe (le jeu ne laisse pas un addon les copier).",
	["Abre la ventana de talentos del juego una vez o espera unos segundos: en cuanto Alfa la lea, te dice qué poner. Mientras, abajo ves tu build."] = "Ouvrez une fois la fenêtre des talents du jeu ou attendez quelques secondes : dès qu'Alfa l'aura lue, il vous dira quoi prendre. En attendant, votre build est plus bas.",
	["Abre la ventana de tu profesión una vez y Alfa leerá tus recetas para decirte cuáles te dejan ganancia."] = "Ouvrez une fois la fenêtre de votre métier et Alfa lira vos recettes pour vous dire lesquelles sont rentables.",
	["Abre la ventana principal de Alfa."] = "Ouvre la fenêtre principale d'Alfa.",
	["Abre o cierra el mapa de Alfa"] = "Ouvre ou ferme la carte d'Alfa",
	["Abre siempre con Cargar y pon Desgarrar al empezar la pelea."] = "Ouvrez toujours avec Charge et posez Pourfendre au début du combat.",
	["Abre siempre desde el sigilo con tu ataque más fuerte."] = "Ouvrez toujours depuis le camouflage avec votre attaque la plus forte.",
	["Abre su ficha en Mazmorras y toca «Guíame»: la flecha te lleva hasta la puerta, aunque esté escondida en una cueva."] = "Ouvre sa fiche dans Donjons et touche « Guide-moi » : la flèche t’emmène jusqu’à la porte, même cachée dans une grotte.",
	["Abre su ficha."] = "Ouvre sa fiche.",
