	["Donde antes estaba el Pozo de la Eternidad hoy gira el Maelstrom, un remolino eterno en medio del Gran Mar."] = "Là où se trouvait le Puits d'éternité tourne aujourd'hui le Maelström, un tourbillon éternel au milieu de la Grande mer.",
	["Donde lo sacas: %s."] = "Où vous l'attrapez : %s.",
	["Donde puedes seguir en varias zonas, toma la recomendada sin preguntar."] = "Là où vous pourriez continuer dans plusieurs zones, prend celle recommandée sans demander.",
	["Dormir"] = "Dormir",
	["Dos armas"] = "Deux armes",
	["Dos armas y mucha ira. Furia pega más que Armas cuando tiene buen equipo, y Sed de sangre llega al nivel 40. Necesitas dos armas de una mano desde el nivel 20."] = "Deux armes et beaucoup de rage. Fureur frappe plus fort qu'Armes quand il est bien équipé, et Sanguinaire arrive au niveau 40. Il vous faut deux armes à une main dès le niveau 20.",
	["Dos clics y Alfa te lleva"] = "Deux clics et Alfa vous y mène",
	["Dos manos"] = "Deux mains",
	["Dos monstruos a la vez dejan de ser un problema."] = "Deux monstres à la fois ne sont plus un problème.",
	["Dos profesiones de recolección: oro constante sin perder tiempo, justo cuando más lo necesitas."] = "Deux métiers de récolte : de l'or régulier sans perdre de temps, juste quand vous en avez le plus besoin.",
	["Drek'Thar, el viejo chamán ciego del clan Lobo Gélido, le enseñó a Thrall a hablar con los espíritus. ¡Un sabio de los lobos!"] = "Drek'Thar, le vieux chaman aveugle du clan Loup-de-givre, a appris à Thrall à parler aux esprits. Un sage des loups !",
	["Drenar alma al rematar te da uno."] = "Siphon d'âme pour achever une cible vous en donne un.",
	["Druida"] = "Druide",
	["Druidas, guerreros y pícaros: si tu barra de forma o de actitud está vacía, Alfa te avisa y la llena con un clic."] = "Druides, guerriers et voleurs : si votre barre de forme ou de posture est vide, Alfa vous prévient et la remplit en un clic.",
	["Duelos"] = "Duels",
	["Duerme a un jugador y lanza sombras: interrúmpelo."] = "Il endort un joueur et lance des sorts d'ombre : interrompez-le.",
	["Dun Algaz es el túnel enano que une Los Humedales con Loch Modan."] = "Dun Algaz est le tunnel nain qui relie les Paluns au Loch Modan.",
	["Duplicar"] = "Dupliquer",
	["Durabilidad"] = "Durabilité",
	["Duración"] = "Durée",
	["Durante la pelea despierta a guardianes de piedra: alguien debe tanquearlos o mátenlos rápido."] = "Pendant le combat, il réveille des gardiens de pierre : quelqu'un doit les tanker, ou tuez-les vite.",
	["Durante siglos los druidas durmieron en el Sueño Esmeralda mientras las Centinelas cuidaban el bosque."] = "Pendant des siècles, les druides ont dormi dans le Rêve d'émeraude pendant que les Sentinelles gardaient la forêt.",
	["Durotan y su clan Lobo Gélido se negaron a beber la sangre de Mannoroth. Gul'dan nunca se lo perdonó."] = "Durotan et son clan Loup-de-givre ont refusé de boire le sang de Mannoroth. Gul'dan ne le lui a jamais pardonné.",
	["Durotar lleva el nombre de Durotan, el padre de Thrall y jefe del clan Lobo Gélido. Thrall honró su memoria al nombrar así la tierra de los orcos."] = "Durotar porte le nom de Durotan, le père de Thrall et chef du clan Loup-de-givre. Thrall a honoré sa mémoire en donnant son nom à la terre des orcs.",
	["Dónde"] = "Où",
	["Dónde aprender Pesca y sus rangos. Se llenan al abrir la guía de pesca."] = "Où apprendre la Pêche et ses rangs. Remplis quand vous ouvrez le guide de pêche.",
	["Dónde empieza el paisaje lejano simplificado."] = "Où commence le paysage lointain simplifié.",
	["Dónde entregar"] = "Où rendre",
	["Dónde está"] = "Où c'est",
	["Dónde está cada uno, lo que vende, lo que suelta y sus misiones."] = "Où se trouve chacun, ce qu'il vend, ce qu'il laisse tomber et ses quêtes.",
	["Dónde mandarlo"] = "Où l'envoyer",
	["Dónde sale"] = "D'où il vient",
	["Dónde se entrega"] = "Où la rendre",
	["Dónde se ven"] = "Où ils s'affichent",
	["Editar"] = "Modifier",
	["Edwin VanCleef, el jefe Defias, era maestro cantero. Cuando la nobleza no pagó la reconstrucción de Ventormenta, juró venganza."] = "Edwin VanCleef, le chef des Défias, était maître tailleur de pierre. Quand la noblesse n'a pas payé la reconstruction de Hurlevent, il a juré vengeance.",
	["Efecto activo"] = "Effet actif",
	["Efecto del vacío"] = "Effet du Néant",
	["Efectos"] = "Effets",
	["Efectos de pantalla del juego"] = "Effets d'écran du jeu",
	["Ej.: Comprar bolsas de 10 casillas"] = "Ex. : Acheter des sacs de 10 emplacements",
	["Ejecutar cuesta menos ira: rematas antes."] = "Exécution coûte moins de rage : vous achevez plus tôt.",
	["Ejecutar más barato para rematar jefes."] = "Exécution moins chère pour achever les boss.",
	["El Alba Argenta pelea contra la Plaga sin el fanatismo de los Escarlatas, y recibe por igual a la Alianza y a la Horda."] = "L'Aube d'argent combat le Fléau sans le fanatisme des Écarlates, et accueille l'Alliance comme la Horde.",
	["El Bastión Plumaluna, en una isla frente a la costa, es el puesto de las centinelas élficas."] = "Le bastion de Plumelune, sur une île au large, est l'avant-poste des sentinelles elfes.",
	["El Bosque del Ocaso y las Montañas Crestagrana también son tierras del reino, y piden ayuda porque los soldados no alcanzan."] = "Le bois de la Pénombre et les Carmines font aussi partie du royaume, et ils demandent de l'aide parce que les soldats ne suffisent pas.",
	["El Campamento Mojache es el hogar de la Horda en Feralas."] = "Le camp Mojache est le foyer de la Horde à Féralas.",
	["El Castillo de Colmillo Oscuro fue de Arugal, un mago de Dalaran que convocó a los worgen para pelear contra la Plaga y terminó perdiendo la razón."] = "Le donjon d'Ombrecroc appartenait à Arugal, un mage de Dalaran qui invoqua les worgens pour combattre le Fléau et finit par perdre la raison.",
	["El Claro de la Luna es un santuario de druidas; ahí se reúne el Círculo Cenarion."] = "Reflet-de-Lune est un sanctuaire druidique ; le Cercle cénarien s'y réunit.",
	["El Codex no sabe de dónde sale; si ya la tienes, la ves en tu diario de monturas."] = "Le Codex ne sait pas d'où elle vient ; si vous l'avez déjà, vous la voyez dans votre collection de montures.",
	["El Cruce es un puesto de la Horda justo en medio de Los Baldíos, donde se juntan los caminos principales. De ahí su nombre."] = "La Croisée est un avant-poste de la Horde en plein milieu des Tarides, là où se rejoignent les routes principales. D'où son nom.",
	["El Culto de los Malditos lo fundó Kel'Thuzad: les prometía a los campesinos de Lordaeron una vida eterna y más justa."] = "Kel'Thuzad a fondé le Culte des damnés : il promettait aux paysans de Lordaeron une vie éternelle et plus juste.",
	["El Discord de La Jauría"] = "Le Discord de La Jauría",
	["El Fuerte Cenarion es la base del Círculo Cenarion en Silithus, frente a los qiraji."] = "Fort Cénarien est la base du Cercle cénarien en Silithus, face aux Qiraji.",
	["El Gran Manitas Gelbin Mekkatorque es el líder de los gnomos."] = "Le Grand Artisan Gelbin Mekkanivelle est le chef des gnomes.",
	["El Guardián Remulos, hijo de Cenarius, cuida el Claro de la Luna desde su santuario."] = "Le gardien Remulos, fils de Cénarius, veille sur Reflet-de-Lune depuis son sanctuaire.",
	["El Horado Rajacieno y la Zahúrda Rajacieno son guaridas de los jabaespines, entre Los Baldíos y Las Mil Agujas."] = "Le kraal de Tranchebauge et les souilles de Tranchebauge sont des repaires de huran, entre les Tarides et Mille pointes.",
	["El Legado se abre con tu primer punto (casi siempre, al llegar a nivel 25), con la tecla Y o con su botón del menú."] = "L'Héritage se débloque avec votre premier point (presque toujours en atteignant le niveau 25), avec la touche Y ou son bouton du menu.",
	["El Loto negro crece solo en zonas de nivel muy alto, y es tan raro que vale una fortuna."] = "Le Lotus noir ne pousse que dans des zones de très haut niveau, et il est si rare qu'il vaut une fortune.",
	["El Loto negro es rarísimo: crece en Cuna del Invierno, las Estepas Ardientes, las Tierras de la Peste del Este y Silithus."] = "Le Lotus noir est rarissime : il pousse au Berceau-de-l'Hiver, dans les Steppes ardentes, les Maleterres de l'Est et en Silithus.",
	["El Martillo Crepuscular tiene campamentos en Silithus, donde intenta invocar a los señores elementales."] = "Le Marteau du crépuscule a des camps en Silithus, où il tente d'invoquer les seigneurs élémentaires.",
	["El Núcleo de Magma, en el fondo de la Montaña Roca Negra, es el hogar de Ragnaros, el Señor del Fuego."] = "Le Cœur du Magma, au fond du mont Rochenoire, est le foyer de Ragnaros, le seigneur du Feu.",
	["El Paso de la Muerte no tiene ni un pueblo: solo ogros, bestias y la sombra de Karazhan."] = "Le défilé de Deuillevent n'a pas un seul village : rien que des ogres, des bêtes et l'ombre de Karazhan.",
	["El Paso de la Muerte une el Bosque del Ocaso con el Pantano de las Penas."] = "Le défilé de Deuillevent relie le bois de la Pénombre au marais des Chagrins.",
	["El Portal Oscuro está apagado en el Clásico. En Burning Crusade vuelve a abrirse rumbo a Terrallende."] = "La Porte des Ténèbres est éteinte en Classic. Dans Burning Crusade, elle se rouvre vers l'Outreterre.",
	["El Portal Oscuro lo abrieron Medivh y Gul'dan juntos, cada uno desde su lado."] = "La Porte des Ténèbres a été ouverte par Medivh et Gul'dan ensemble, chacun de son côté.",
	["El Puente Thandol, al norte, une Khaz Modan con Arathi; los Hierro Negro lo dejaron medio destruido."] = "Le viaduc de Thandol, au nord, relie Khaz Modan à Arathi ; les Sombrefer l'ont laissé à moitié détruit.",
	["El Puerto de Menethil lleva el apellido de la familia real de Lordaeron. De ahí salen barcos a Theramore y a Auberdine."] = "Le port de Menethil porte le nom de la famille royale de Lordaeron. Des bateaux en partent pour Theramore et Auberdine.",
	["El Puesto Hachazo es el campamento de la Horda que tala Vallefresno."] = "Le poste de Bois-Brisé est le campement de la Horde qui abat la forêt d'Orneval.",
	["El Refugio Roca del Sol es el hogar de los tauren en estas montañas."] = "La retraite du Roc-Soleil est le foyer des Taurens dans ces montagnes.",
	["El Refugio de la Zaga es el campamento de la Alianza en Arathi, entre ruinas, trols y ogros."] = "Le Refuge de l'Ornière est le campement de l'Alliance en Arathi, entre ruines, trolls et ogres.",
	["El Refugio del Mariscal es el único campamento del cráter, y lo comparten todos."] = "Le refuge de Marshal est le seul campement du cratère, et tout le monde le partage.",
	["El SI:7 de Ventormenta y Ravenholdt son nombres que todo pícaro conoce."] = "Le SI:7 de Hurlevent et Ravenholdt sont des noms que tout voleur connaît.",
	["El Sepulcro es el puesto de los Renegados en el bosque; desde ahí vigilan a los worgen y a los magos de Dalaran."] = "Le Sépulcre est l'avant-poste des Réprouvés dans la forêt ; de là, ils surveillent les worgens et les mages de Dalaran.",
	["El Sindicato, los nobles caídos de Alterac, también asalta caminos y granjas por estas tierras."] = "Le Syndicat, les nobles déchus d'Alterac, attaque aussi les routes et les fermes de la région.",
	["El Sueño Esmeralda se está volviendo pesadilla: algo corrompe a los dragones verdes que lo cuidan."] = "Le Rêve d'émeraude devient cauchemar : quelque chose corrompt les dragons verts qui le gardent.",
	["El Tranvía Subterráneo une Forjaz con Ventormenta por debajo de la tierra. Lo construyeron los gnomos."] = "Le tram des profondeurs relie Forgefer et Hurlevent sous terre. Ce sont les gnomes qui l'ont construit.",
	["El Trono Helado es la armadura de hielo donde quedó atrapado Ner'zhul, en lo alto de la Corona de Hielo."] = "Le Trône de glace est l'armure de glace où Ner'zhul a été emprisonné, au sommet de la Couronne de glace.",
	["El Valle Calcinado, al sur de la sierra, quedó quemado y lleno de elementales de fuego."] = "Le Val calciné, au sud de la chaîne, a brûlé et grouille d'élémentaires de feu.",
	["El Vigía de Morgan es el puesto de la Alianza en las estepas, desde donde vigilan la Montaña Roca Negra."] = "La Veille de Morgan est l'avant-poste de l'Alliance dans les steppes, d'où l'on surveille le mont Rochenoire.",
	["El aguante es tu mejor amigo: más vida para más Transfusión de vida."] = "L'endurance est votre meilleure amie : plus de vie pour plus de Connexion.",
	["El alfa de La Jauría anda cerca"] = "L’alpha de La Jauría est dans le coin",
	["El almirante Daelin Valiente, padre de Jaina, cayó en Theramore tras atacar a la Horda. Su hija eligió la paz."] = "L'amiral Daelin Portvaillant, père de Jaina, est tombé à Theramore après avoir attaqué la Horde. Sa fille a choisi la paix.",
	["El archidruida Fandral Corzocelada enseña en el Enclave Cenarion de Darnassus."] = "L'archidruide Fandral Forteramure enseigne dans l'enclave cénarienne de Darnassus.",
	["El archidruida Fandral Corzocelada plantó Teldrassil con la esperanza de recuperar la inmortalidad que los elfos perdieron en el Monte Hyjal."] = "L'archidruide Fandral Forteramure a planté Teldrassil dans l'espoir de retrouver l'immortalité que les elfes ont perdue au mont Hyjal.",
	["El archidruida Hamuul Tótem de Runa enseña a los druidas tauren, y fue de los primeros tauren aceptados en el Círculo Cenarion."] = "L'archidruide Hamuul Totem-runique enseigne aux druides taurens, et fut l'un des premiers Taurens acceptés dans le Cercle cénarien.",
	["El arma principal debe ser la más lenta y fuerte; la secundaria, la más rápida."] = "L'arme en main droite doit être la plus lente et la plus forte ; celle en main gauche, la plus rapide.",
	["El aro y la cabecera del minimapa con tu estilo."] = "L'anneau et l'en-tête de la minicarte à votre style.",
	["El banco está lleno: compra otra casilla o pon una bolsa más grande en el banco."] = "La banque est pleine : achetez un autre emplacement ou mettez un sac plus grand dans la banque.",
	["El barco a %s ya viene"] = "Le bateau pour %s arrive",
	["El barco goblin une Bahía del Botín con Trinquete, y lo pueden usar los dos bandos."] = "Le bateau gobelin relie Baie-du-Butin à Cabestan, et les deux factions peuvent l'utiliser.",
	["El barón Osahendido manda en Stratholme como caballero de la muerte de la Plaga."] = "Le baron Vaillefendre règne sur Stratholme en tant que chevalier de la mort du Fléau.",
	["El blanco de la interfaz y del cielo de día."] = "Le blanc de l'interface et du ciel de jour.",
	["El bonus de tu arma al máximo."] = "Le bonus de votre arme au maximum.",
	["El borde del minimapa, redondo o cuadrado («Minimapa cuadrado», arriba), y la barra con la zona y la hora toman el estilo que elijas, como la ventana del mapa. Al apagarlo vuelve el de siempre."] = "La bordure de la minicarte, ronde ou carrée (« Minicarte carrée », au-dessus), et la barre avec la zone et l'heure prennent le style choisi, comme la fenêtre de la carte. Désactivé, l'habituel revient.",
	["El borde toma el color del perjuicio (magia, maldición, enfermedad o veneno) cuando tú lo puedes quitar."] = "La bordure prend la couleur de l'effet néfaste (magie, malédiction, maladie ou poison) quand vous pouvez le dissiper.",
	["El botón «Escanear con Alfa» bajo la ventana de la subasta."] = "Le bouton « Scanner avec Alfa » sous la fenêtre de l'hôtel des ventes.",
	["El brillo más alto que da tu monitor; viene en su caja o su ficha."] = "La luminosité la plus haute de votre moniteur ; elle figure sur sa boîte ou sa fiche technique.",
	["El brillo suave de luces y cielo en toda la pantalla."] = "La douce lueur des lumières et du ciel sur tout l'écran.",
	["El brujo Zalazane les robó las Islas del Eco a los Lanza Negra con su vudú."] = "Le féticheur Zalazane a volé les îles de l'Écho aux Sombrelances avec son vaudou.",
	["El buscador de Ajustes ya encuentra todo: también Pesca, Comercio, Ruta, Bolsas, Combate, Curación, Lya y Estilo y sonido."] = "La recherche des réglages trouve désormais tout : aussi Pêche, Commerce, Itinéraire, Sacs, Combat, Soins, Lya et Style et son.",
	["El buscador del motor está apagado (Ajustes > Descubrir): enciéndelo para que Alfa arme guías."] = "La Recherche du moteur est désactivée (Réglages > Découverte) : activez-la pour qu'Alfa puisse créer des guides.",
	["El buscador no está disponible."] = "La recherche n'est pas disponible.",
	["El camino a Entrañas pasa por las ruinas de la Ciudad Capital de Lordaeron, donde Arthas mató a su padre."] = "Le chemin vers Fossoyeuse passe par les ruines de la Capitale de Lordaeron, où Arthas a tué son père.",
	["El camino a la meta en el mapa del mundo y el minimapa: una línea o puntos donde caminas, líneas donde vuelas, navegas o montas, y los tramos que siguen más tenues."] = "Le chemin vers l'objectif sur la carte du monde et la minicarte : une ligne ou des points là où vous marchez, des lignes là où vous volez, naviguez ou chevauchez, et les tronçons suivants plus pâles.",
	["El camino en el mapa y el minimapa"] = "Le chemin sur la carte et la minicarte",
	["El camino hasta el destino dibujado en el mapa."] = "Le chemin jusqu'à la destination, tracé sur la carte.",
	["El camino más sencillo para subir: un arma grande, golpes que hacen sangrar y Golpe mortal al nivel 40. Aguantas bien y matas rápido."] = "La façon la plus simple de monter : une grande arme, des coups qui font saigner et Frappe mortelle au niveau 40. Vous encaissez bien et tuez vite.",
	["El camino que baja de la sierra hacia Los Baldíos está lleno de arañas. ¡Brrr!"] = "La route qui descend de la chaîne vers les Tarides est pleine d'araignées. Brrr !",
	["El chat"] = "La discussion",
	["El chat usa la letra de Alfa (la de Ajustes > Apariencia). El tamaño se sigue cambiando en el menú de la pestaña."] = "La discussion utilise la police d'Alfa (celle de Réglages > Apparence). La taille se change toujours dans le menu de l'onglet.",
	["El clan"] = "Le clan",
	["El clan Lobo Gélido monta lobos de verdad. Por eso es mi clan favorito, no lo voy a negar."] = "Le clan Loup-de-givre monte de vrais loups. C'est pour ça que c'est mon clan préféré, je ne vais pas le nier.",
	["El clan Lobo Gélido vive exiliado en el valle de Alterac. Thrall, hijo de su antiguo jefe, los encontró ahí después de escapar de Durnholde."] = "Le clan Loup-de-givre vit en exil dans la vallée d'Alterac. Thrall, fils de leur ancien chef, les y a trouvés après s'être échappé de Fort-de-Durn.",
	["El clic derecho solo sigue alejando el mapa del juego, como siempre."] = "Un simple clic droit continue de dézoomer la carte du jeu, comme toujours.",
	["El clic izquierdo solo selecciona"] = "Le clic gauche ne fait que cibler",
	["El clásico para pelear contra jugadores: Golpe mortal corta las curas del rival, Seccionar mejorado lo deja quieto y Cargar mejorado te da ira para empezar."] = "Le classique pour combattre les joueurs : Frappe mortelle réduit les soins de l'adversaire, Brise-genou amélioré l'immobilise et Charge améliorée vous donne de la rage pour commencer.",
	["El color de mi clase"] = "La couleur de ma classe",
	["El comerciante no lo compra"] = "Le marchand ne l'achète pas",
	["El contenido va en una columna centrada y se acomoda solo si cambias la resolución o la escala."] = "Le contenu tient dans une colonne centrée et s'ajuste tout seul si vous changez la résolution ou l'échelle.",
	["El corcho quedó lejos · relanza con %s"] = "Le flotteur est tombé loin · relancez avec %s",
	["El corcho quedó lejos · vuelve a lanzar"] = "Le flotteur est tombé loin · relancez",
	["El cuadro del jugador al pasar el ratón. En combate no sale, para no estorbar."] = "L'infobulle du joueur au survol. Elle ne s'affiche pas en combat, pour ne pas gêner.",
	["El cártel Bonvapor controla Bahía del Botín, Trinquete, Gadgetzan y Vista Eterna. Por eso esos puertos reciben a todos."] = "Le cartel Gentepression contrôle Baie-du-Butin, Cabestan, Gadgetzan et Long-guet. C'est pour ça que ces ports accueillent tout le monde.",
	["El daño por segundo de tu arma a distancia."] = "Les dégâts par seconde de votre arme à distance.",
	["El daño por segundo del arma: para el guerrero, lo que más cuenta al subir."] = "Les dégâts par seconde de l'arme : pour le guerrier, ce qui compte le plus en montant de niveau.",
	["El de tu juego"] = "Celle de votre jeu",
	["El demosaurio es el gran depredador del cráter: si oyes pasos que retumban, escóndete."] = "Le diablosaure est le grand prédateur du cratère : si tu entends des pas qui résonnent, cache-toi.",
	["El destino de la flecha y sus zonas en el minimapa."] = "La destination de la flèche et ses zones sur la minicarte.",
	["El destino de la flecha, su camino y las otras metas del paso, en el mapa."] = "La destination de la flèche, son chemin et les autres objectifs de l'étape, sur la carte.",
	["El diario de mazmorras del motor está apagado (Ajustes > Descubrir > Mazmorras)."] = "Le journal des donjons du moteur est désactivé (Réglages > Découverte > Donjons).",
	["El diario de mazmorras está apagado"] = "Le journal des donjons est désactivé",
	["El dragón azul Azuregos ronda Azshara, cuidando la magia antigua que quedó en sus ruinas."] = "Le dragon bleu Azuregos rôde en Azshara, gardant la magie ancienne restée dans ses ruines.",
	["El druida hace de todo: puedes tanquear, curar o pegar según lo que pida el grupo."] = "Le druide fait de tout : tu peux tanker, soigner ou frapper selon les besoins du groupe.",
	["El emperador Dagran Thaurissan gobierna la Ciudad de Hierro Negro, en las Profundidades de Roca Negra."] = "L'empereur Dagran Thaurissan règne sur la cité des Sombrefer, dans les profondeurs de Rochenoire.",
	["El enemigo esquivó: Abrumar no se puede esquivar y pega fuerte."] = "L'ennemi a esquivé : Fulgurance ne peut pas être esquivée et frappe fort.",
	["El enemigo esquivó: este golpe cuerpo a cuerpo está listo."] = "L'ennemi a esquivé : cette frappe au corps à corps est prête.",
	["El enemigo esquivó: este golpe está listo."] = "L'ennemi a esquivé : ce coup est prêt.",
	["El enemigo está encima: golpéalo cuerpo a cuerpo."] = "L'ennemi est sur vous : frappez-le au corps à corps.",
	["El enemigo está lanzando un hechizo: Choque de tierra lo corta."] = "L'ennemi incante un sort : Horion de terre l'interrompt.",
	["El enemigo está lanzando un hechizo: aturdirlo lo corta."] = "L'ennemi incante un sort : l'étourdir l'interrompt.",
	["El enemigo está lanzando un hechizo: córtalo con tu escudo."] = "L'ennemi incante un sort : interrompez-le avec votre bouclier.",
	["El enemigo está lanzando un hechizo: córtalo."] = "L'ennemi incante un sort : interrompez-le.",
	["El enemigo está lanzando un hechizo: el golpe lo corta."] = "L'ennemi incante un sort : le coup l'interrompt.",
	["El enemigo está por caer: drénale el alma y gana un fragmento."] = "L'ennemi va tomber : siphonnez son âme et gagnez un fragment.",
	["El enlace del Discord ya está elegido: cópialo con Ctrl+C y pégalo en tu navegador."] = "Le lien Discord est sélectionné : copie-le avec Ctrl+C et colle-le dans ton navigateur.",
	["El entrenador de oficio más cercano"] = "Le maître de métier le plus proche",
	["El espíritu te devuelve maná rápido: descansas muy poco."] = "L'esprit vous rend vite du mana : vous vous reposez très peu.",
	["El estilo del mapa (terreno como el minimapa, o el arte clásico) y las opciones de Mundo."] = "Le style de la carte (terrain comme la minicarte, ou l'art classique) et les options de Monde.",
	["El estilo que elegiste también puede vestir el chat, el minimapa, las barras de abajo y el mapa. Se apaga cuando quieras y todo vuelve a como estaba."] = "Le style choisi peut aussi habiller la discussion, la minicarte, les barres du bas et la carte. Désactivez-le quand vous voulez et tout redevient comme avant.",
	["El final"] = "La fin",
	["El final de cada misión"] = "La fin de chaque quête",
	["El final lo verás al entregarla."] = "Vous verrez la fin en la rendant.",
	["El fondo se ve deformado a través del agua."] = "Le fond paraît déformé à travers l'eau.",
	["El fuego pega a todos los de cerca: mantén la vida alta de quienes pelean cuerpo a cuerpo."] = "Le feu touche tous ceux qui sont proches : gardez haute la vie de ceux qui combattent au corps à corps.",
	["El general Drakkisath guarda la entrada a la Guarida Alanegra, en lo alto de la Cumbre de Roca Negra."] = "Le général Drakkisath garde l'entrée du repaire de l'Aile noire, en haut du pic Rochenoire.",
	["El gran cruzado de la Cruzada Escarlata, Saidan Dathrohan, es en realidad el demonio Balnazzar. Lo encuentras en Stratholme."] = "Le grand croisé de la Croisade écarlate, Saidan Dathrohan, est en réalité le démon Balnazzar. Tu le trouveras à Stratholme.",
	["El guerrero que más daño hace en mazmorras. Con un tanque delante, tus dos armas no paran, y Ejecutar mejorado remata a los jefes."] = "Le guerrier qui fait le plus de dégâts en donjon. Avec un tank devant, vos deux armes ne s'arrêtent jamais, et Exécution améliorée achève les boss.",
	["El hacha de Grom Grito Infernal tiene nombre propio, y dicen que aúlla cuando corta el aire. ¡Aullar es cosa seria!"] = "La hache de Grom Hurlenfer a son propre nom, et on dit qu'elle hurle quand elle fend l'air. Hurler, c'est sérieux !",
	["El hierro negro solo se funde en la Forja Negra de las Profundidades de Roca Negra."] = "Le fer noir ne se fond qu'à la Forge noire des profondeurs de Rochenoire.",
	["El hijo de Cairne, Baine, cuida el poblado Pezuña de Sangre en Mulgore."] = "Le fils de Cairne, Baine, veille sur le village de Sabot-de-Sang en Mulgore.",
	["El idioma, el estilo, lo que Alfa hace sola por ti y La Jauría, con «Cambiar» en cada cosa. También con /alfa bienvenida."] = "La langue, le style, ce qu'Alfa fait seul pour vous et La Jauría, avec « Changer » sur chaque point. Aussi avec /alfa bienvenida.",
	["El izquierdo selecciona y el derecho abre el menú."] = "Le gauche cible et le droit ouvre le menu.",
	["El izquierdo selecciona y el derecho abre el menú. Tus buffs para otros se suman aquí al aprenderlos."] = "Le gauche cible et le droit ouvre le menu. Vos buffs pour les autres s'ajoutent ici quand vous les apprenez.",
	["El izquierdo selecciona y el derecho abre el menú. Tú eliges el resto."] = "Le gauche cible et le droit ouvre le menu. Vous choisissez le reste.",
	["El izquierdo selecciona y el derecho abre el menú: lo básico, porque tu clase no lanza hechizos sobre sus compañeros."] = "Le gauche cible et le droit ouvre le menu : l'essentiel, car votre classe ne lance pas de sorts sur ses alliés.",
	["El juego elige entre estas según la situación; el ícono te muestra cuál conviene ahora."] = "Le jeu choisit parmi celles-ci selon la situation ; l'icône vous montre la plus utile maintenant.",
	["El juego la hizo brillar: es buen momento para usarla."] = "Le jeu l'a fait briller : c'est le bon moment pour l'utiliser.",
	["El juego manda la imagen en HDR."] = "Le jeu envoie l'image en HDR.",
	["El juego no aceptó el lote."] = "Le jeu n'a pas accepté la fournée.",
	["El juego no aceptó esa tecla."] = "Le jeu a refusé cette touche.",
	["El juego no aceptó la prueba."] = "Le jeu n'a pas accepté le test.",
	["El juego no da tu posición aquí (en una instancia, por ejemplo)."] = "Le jeu ne donne pas votre position ici (dans une instance, par exemple).",
	["El juego no deja cambiar talentos ahora mismo"] = "Le jeu ne permet pas de changer de talents pour l'instant",
	["El juego no deja cocinar desde aquí."] = "Le jeu ne permet pas de cuisiner d'ici.",
	["El juego no deja enviar mensajes en este momento (un encuentro o una partida). Tu rastro vuelve a salir solo cuando termine."] = "Le jeu ne permet pas d'envoyer de messages en ce moment (une rencontre ou une partie). Votre piste repart toute seule à la fin.",
	["El juego no deja que las cuentas de prueba envíen mensajes de addon ni usen canales propios. Tu grupo sí se ve."] = "Le jeu ne permet pas aux comptes d'essai d'envoyer des messages d'addon ni d'utiliser des canaux personnalisés. Votre groupe reste visible.",
	["El juego no dejó cambiar las demás."] = "Le jeu n'a pas permis de modifier les autres.",
	["El juego no dejó compartir el marcador ahora. Prueba en un momento."] = "Le jeu n'a pas permis de partager le marqueur pour l'instant. Réessayez dans un moment.",
	["El juego no dejó comprar ese rango."] = "Le jeu n'a pas permis d'acheter ce rang.",
	["El juego no dejó entrar al canal oculto de Alfa y, sin hermandad, no hay otro camino para compartir. Alfa lo vuelve a intentar sola en unos minutos. Tu grupo sí se ve."] = "Le jeu n'a pas laissé entrer dans le canal caché d'Alfa et, sans guilde, il n'y a pas d'autre moyen de partager. Alfa réessaie tout seul dans quelques minutes. Votre groupe reste visible.",
	["El juego no dice si la tienes"] = "Le jeu ne dit pas si vous l'avez",
	["El juego no dio tus puntos todavía: se ven desde que ganas el primero."] = "Le jeu n'a pas encore donné vos points : ils s'affichent dès que vous gagnez le premier.",
	["El juego no la ofrece ahora mismo."] = "Le jeu ne la propose pas en ce moment.",
	["El juego no lo dice ahora."] = "Le jeu ne l'indique pas pour l'instant.",
	["El juego no permite usar el medidor ahora."] = "Le jeu ne permet pas d'utiliser le compteur pour l'instant.",
	["El juego no trae la ayuda de Blizzard, así que Alfa sugiere con su prioridad para %s, leyendo solo tu personaje: tu recurso, tus efectos y lo que el juego te deja usar. Con 3 o más enemigos cambia a las de área. Tú decides qué presionar."] = "Le jeu n'inclut pas l'assistant de combat de Blizzard : Alfa suggère donc avec sa propre priorité pour %s, en lisant seulement votre personnage : votre ressource, vos effets et ce que le jeu vous laisse utiliser. Avec 3 ennemis ou plus, il passe aux techniques de zone. C'est vous qui décidez sur quoi appuyer.",
	["El juego oculta los números exactos mientras peleas: la barra y la cifra se ven, el detalle al salir de combate."] = "Le jeu masque les chiffres exacts pendant le combat : la barre et le chiffre restent visibles, le détail à la sortie du combat.",
	["El juego rechazó confirmar los cambios. Se deshicieron para que tu árbol quede como estaba."] = "Le jeu a refusé de confirmer les changements. Ils ont été annulés pour que votre arbre reste comme avant.",
	["El juego solo deja cambiarla fuera de combate."] = "Le jeu ne permet de la changer qu'hors combat.",
	["El juego te pasó a la %s. Otra gente, otros raros, otros minerales."] = "Le jeu t’a fait passer dans la %s. D’autres gens, d’autres rares, d’autres minerais.",
	["El juego todavía no carga tu árbol"] = "Le jeu n'a pas encore chargé votre arbre",
	["El juego todavía no carga tu árbol."] = "Le jeu n'a pas encore chargé votre arbre.",
	["El juego todavía no cargó tus talentos. Espera unos segundos o abre la ventana de talentos (tecla N) una vez."] = "Le jeu n'a pas encore chargé vos talents. Attendez quelques secondes ou ouvrez une fois la fenêtre des talents (touche N).",
	["El juego todavía no dio la lista de retos: ábrelo con la tecla Y."] = "Le jeu n'a pas encore donné la liste des défis : ouvrez-le avec la touche Y.",
	["El juego todavía no la abre: se abre con tu primer punto del Legado (casi siempre, al llegar a nivel 25)."] = "Le jeu ne l'ouvre pas encore : elle s'ouvre avec votre premier point d'Héritage (presque toujours en atteignant le niveau 25).",
	["El juego todavía no tiene los datos de algunos objetos. En un momento aparecen."] = "Le jeu n'a pas encore les données de certains objets. Elles arrivent dans un instant.",
	["El juego todavía oculta los números o los nombres (pasa en combate y dentro de mazmorras). Inténtalo al salir."] = "Le jeu masque encore les chiffres ou les noms (c'est le cas en combat et dans les donjons). Réessayez une fois sorti.",
	["El lago Lordamere separa el Bosque de Argénteos de las Laderas de Trabalomas y de las Montañas de Alterac."] = "Le lac Lordamere sépare la forêt des Pins-Argentés des contreforts de Hautebrande et des montagnes d'Alterac.",
	["El lago de Loch Modan existe gracias a una enorme presa enana. Si se rompiera, el agua arrasaría las tierras de abajo."] = "Le lac du Loch Modan existe grâce à un énorme barrage nain. S'il cédait, l'eau balaierait les terres en contrebas.",
	["El lago del Claro de la Luna se llama Elune'ara, en honor a la diosa de la luna."] = "Le lac de Reflet-de-Lune s'appelle Elune'ara, en l'honneur de la déesse de la lune.",
	["El lago helado de Kel'Theril guarda ruinas de los Altonato."] = "Le lac gelé de Kel'Theril abrite des ruines des Bien-nés.",
	["El lobo de la intro aúlla de pie sobre la peña, con un aullido largo que otro lobo contesta; y al entrar, Lya llega corriendo a decirte que te extrañó."] = "Le loup de l'intro hurle debout sur le rocher, un long hurlement auquel répond un autre loup ; et quand tu te connectes, Lya arrive en courant pour te dire que tu lui as manqué.",
	["El lobo te recibe al entrar"] = "Le loup vous accueille à la connexion",
	["El lobo te recibe cada vez que entras al juego, redibujado: cabeza, orejas y hocico de lobo de verdad."] = "Le loup vous accueille à chaque connexion, redessiné : la tête, les oreilles et le museau d'un vrai loup.",
	["El maestro de vuelo, la posada, reparar, el banco y más, con la flecha."] = "Le maître de vol, l'auberge, la réparation, la banque et plus, avec la flèche.",
	["El maestro de vuelo, la posada, reparar, el banco y más: el más cercano, con la flecha y la ruta."] = "Le maître de vol, l'auberge, la réparation, la banque et plus : le plus proche, avec la flèche et l'itinéraire.",
	["El maestro de vuelo, la posada, reparar, el banco... el más cercano (/alfa cerca ayuda)."] = "Le maître de vol, l'auberge, la réparation, la banque... le plus proche (/alfa cerca ayuda).",
	["El mago Rhonin y el dragón Korialstrasz ayudaron a liberar a Alexstrasza en Grim Batol, y ahí quedó destruida el Alma de Demonio."] = "Le mage Rhonin et le dragon Korialstrasz ont aidé à libérer Alexstrasza à Grim Batol, et l'Âme des démons y a été détruite.",
	["El mago que más daño hace: hechizos de fuego y críticos que queman."] = "Le mage qui fait le plus de dégâts : sorts de feu et critiques qui brûlent.",
	["El mapa a tu gusto"] = "La carte à votre goût",
	["El mapa abre sin errores con M y se arrastra suave, aunque empieces encima de un ícono."] = "La carte s'ouvre avec M sans erreur et se fait glisser en douceur, même si vous commencez sur une icône.",
	["El mapa de Alfa"] = "La carte d'Alfa",
	["El mapa de Alfa muestra el terreno real, con puntos de vuelo, mazmorras, barcos, zepelines y portales."] = "La carte d'Alfa montre le vrai terrain, avec points de vol, donjons, bateaux, zeppelins et portails.",
	["El mapa de Alfa, el del juego y el minimapa. Si algo te estorba, apágalo aquí; los otros módulos de Alfa agregan sus capas a esta misma lista."] = "La carte d'Alfa, celle du jeu et la minicarte. Si quelque chose vous gêne, désactivez-le ici ; les autres modules d'Alfa ajoutent leurs calques à cette même liste.",
	["El mapa del mundo entero con zoom, tus marcadores y un solo control para todo lo que se pinta."] = "La carte du monde entier avec zoom, vos marqueurs et un seul réglage pour tout ce qui y est dessiné.",
	["El mapa no se abre en combate."] = "La carte ne s'ouvre pas en combat.",
	["El mapa se ve más limpio: sin líneas finas entre sus pedazos ni halos oscuros en las orillas de las zonas."] = "La carte est plus nette : plus de fines lignes entre ses morceaux ni de halos sombres au bord des zones.",
	["El mar paga"] = "La mer paie",
	["El marco de las barras de experiencia y reputación; el relleno conserva sus colores."] = "Le cadre des barres d'expérience et de réputation ; le remplissage garde ses couleurs.",
	["El marco del menú del juego y de las bolsas, abajo a la derecha."] = "Le cadre du menu du jeu et des sacs, en bas à droite.",
	["El mariscal Dughan cuida Villadorada y siempre anda buscando quien le eche la mano con los problemas de Elwynn."] = "Le maréchal Dughan veille sur Comté-de-l'Or et cherche toujours quelqu'un pour l'aider avec les problèmes d'Elwynn.",
	["El medallón bajo cada marca del mapa y del minimapa: el de Alfa o solo el símbolo, sin medallón."] = "Le médaillon sous chaque marque de la carte et de la minicarte : celui d'Alfa ou le symbole seul, sans médaillon.",
	["El medidor de daño aguanta en combate y la ayuda de rotación ya no te pide interrumpir lo que no se puede."] = "Le compteur de dégâts tient en combat, et l'aide à la rotation ne vous demande plus d'interrompre ce qui ne peut pas l'être.",
	["El medidor no está disponible"] = "Le compteur n'est pas disponible",
	["El mejor que tengas"] = "Le meilleur que vous ayez",
	["El mekigeniero Termochufe, el traidor de Gnomeregan, sigue escondido dentro de la ciudad: es su último jefe."] = "Le mekgénieur Thermojoncteur, le traître de Gnomeregan, se cache toujours dans la ville : c'est son dernier boss.",
	["El menú de la lupa del mapa del juego tiene también todas las capas de Alfa."] = "Le menu de la loupe de la carte du jeu contient aussi tous les calques d'Alfa.",
	["El mineral se funde en barras en cualquier forja."] = "Le minerai se fond en barres à n'importe quelle forge.",
	["El minimapa"] = "La minicarte",
	["El minimapa de Recolección descansa cuando no tiene nada que mostrar."] = "La minicarte de Récolte se repose quand elle n'a rien à montrer.",
	["El minimapa pasa de redondo a cuadrado, con un borde fino. No se recomienda junto con girar el minimapa."] = "La minicarte passe de ronde à carrée, avec une bordure fine. Déconseillé avec la rotation de la minicarte.",
	["El mismo arreglo llegó a los asistentes de Ruta y de Curación."] = "La même correction est arrivée aux assistants d'Itinéraire et de Soins.",
	["El mitril abunda en las Tierras Inhóspitas, las Tierras del Interior y Tanaris."] = "Le mithril abonde dans les Terres ingrates, les Hinterlands et Tanaris.",
	["El modelo no lleva nada aquí."] = "Le modèle ne porte rien ici.",
	["El modo pesca se abre al salir de combate."] = "Le mode pêche s'ouvrira à la sortie du combat.",
	["El modo prueba se usa fuera de combate."] = "Le mode test s'utilise hors combat.",
	["El motor no aceptó la guía."] = "Le moteur n'a pas accepté le guide.",
	["El motor no puede armar guías ahora."] = "Le moteur ne peut pas créer de guides pour l'instant.",
	["El mundo entero en un mapa"] = "Le monde entier sur une carte",
	["El mundo pierde el color mientras eres espíritu."] = "Le monde perd ses couleurs tant que vous êtes un fantôme.",
	["El más cercano cuando le toque, por tiempo de camino."] = "Le plus proche le moment venu, selon le temps de trajet.",
	["El más cercano, por tiempo de camino"] = "Le plus proche, selon le temps de trajet",
	["El más cercano: %s"] = "Le plus proche : %s",
	["El módulo Curación no está cargado."] = "Le module Soins n'est pas chargé.",
	["El nombre de cada zona sobre el mapa de Alfa."] = "Le nom de chaque zone sur la carte d'Alfa.",
	["El número abajo a la izquierda de cada pieza de equipo."] = "Le nombre en bas à gauche de chaque pièce d'équipement.",
	["El número es el orden en que se toma. Pasa el ratón por un talento para ver qué hace."] = "Le numéro indique l'ordre dans lequel on le prend. Survolez un talent pour voir ce qu'il fait.",
	["El número que cuenta hacia atrás. Apagado, solo la barra."] = "Le compte à rebours chiffré. Désactivé, seulement la barre.",
	["El objeto"] = "L'objet",
	["El objeto que usa el paso actual, o el objeto de misión que junta, brilla en tus bolsas. Un objeto que necesita un paso más adelante lleva un candado, para que no lo vendas."] = "L'objet qu'utilise l'étape en cours, ou l'objet de quête qu'elle fait ramasser, brille dans vos sacs. Un objet requis par une étape ultérieure reçoit un cadenas, pour que vous ne le vendiez pas.",
	["El orden importa más que los números: busca piezas con las primeras de la lista."] = "L'ordre compte plus que les chiffres : cherchez des pièces avec les premières de la liste.",
	["El paisaje lejano deja de perderse en la niebla espesa."] = "Le paysage lointain ne se perd plus dans le brouillard épais.",
	["El paisaje lejano deja de perderse en la niebla espesa. A veces se nota dónde termina lo que está cargado."] = "Le paysage lointain ne se perd plus dans le brouillard épais. On voit parfois où s'arrête la zone chargée.",
	["El paquete de datos de Alfa (Alfa_Codex) está desactivado: actívalo en la lista de addons y recarga."] = "Le pack de données d'Alfa (Alfa_Codex) est désactivé : activez-le dans la liste des addons et rechargez.",
	["El paso de ahora de tu guía te lleva a entrenar."] = "L'étape actuelle de votre guide vous emmène vous entraîner.",
	["El pequeño rey Anduin Wrynn lleva su nombre en honor a Anduin Lothar, el héroe que salvó a su pueblo."] = "Le jeune roi Anduin Wrynn porte son nom en l'honneur d'Anduin Lothar, le héros qui a sauvé son peuple.",
	["El primer clic abre la Cocina del juego; el siguiente cocina el lote. Tienes que estar junto a un fuego."] = "Le premier clic ouvre la fenêtre Cuisine du jeu ; le suivant cuisine la fournée. Vous devez être près d'un feu.",
	["El primer jefe de guerra de la Horda fue Mano Negra. Su hijo Rend Mano Negra hoy sirve a Nefarian en la Cumbre de Roca Negra."] = "Le premier chef de guerre de la Horde fut Main-noire. Son fils Rend Main-noire sert aujourd'hui Nefarian au pic Rochenoire.",
	["El primer punto del Legado suele llegar al nivel 25, y con él se abre el Legado."] = "Le premier point d'Héritage arrive en général au niveau 25, et il débloque l'Héritage.",
	["El próximo: %s"] = "Le prochain : %s",
	["El pícaro más fácil para subir: pega de frente, esquiva mucho y aguanta mejor que los demás."] = "Le voleur le plus facile pour monter : il frappe de face, esquive beaucoup et encaisse mieux que les autres.",
	["El rango Experto viene en un libro que vende el pescador de Bahía del Botín, en Tuercespina."] = "Le rang Expert s'obtient avec un livre vendu par le pêcheur de Baie-du-Butin, à Strangleronce.",
	["El rango de niveles de cada zona, con color según tu nivel."] = "La tranche de niveaux de chaque zone, colorée selon votre niveau.",
	["El rastreador te avisa si tu plan se quedó sin paso y lo rearma con un clic."] = "Le suivi te prévient si ton plan n’a plus d’étape et le refait en un clic.",
	["El rastreador te dice el siguiente paso y la flecha te lleva."] = "Le suivi vous indique la prochaine étape et la flèche vous y mène.",
	["El registro de daño del juego está apagado"] = "Le suivi des dégâts du jeu est désactivé",
	["El registro de daño del juego está apagado: enciéndelo para ver el top de tu grupo."] = "Le suivi des dégâts du jeu est désactivé : activez-le pour voir le top de votre groupe.",
	["El registro del Legado"] = "La piste de récompenses de l'Héritage",
	["El reino humano de Alterac traicionó a la Alianza en la Segunda Guerra: su rey, Aiden Perenolde, se alió con la Horda. Por eso el reino desapareció."] = "Le royaume humain d'Alterac a trahi l'Alliance pendant la Deuxième Guerre : son roi, Aiden Perenolde, s'est allié à la Horde. C'est pourquoi le royaume a disparu.",
	["El reino limita los mensajes de addon salientes: %s"] = "Le royaume limite les messages d'addon sortants : %s",
	["El rey Llane Wrynn murió en la Primera Guerra a manos de Garona, la espía de la Horda."] = "Le roi Llane Wrynn est mort pendant la Première Guerre de la main de Garona, l'espionne de la Horde.",
	["El rey Magni Barbabronce gobierna Forjaz; sus hermanos son Muradin y Brann, el explorador."] = "Le roi Magni Barbe-de-bronze gouverne Forgefer ; ses frères sont Muradin et Brann, l'explorateur.",
	["El rey Thoradin unió a las tribus humanas en Arathor, y los altos elfos les enseñaron magia para vencer juntos a los trols Amani."] = "Le roi Thoradin a uni les tribus humaines en Arathor, et les hauts-elfes leur ont enseigné la magie pour vaincre ensemble les trolls Amani.",
	["El rey Varian Wrynn es hijo de Llane, el rey que murió en la Primera Guerra."] = "Le roi Varian Wrynn est le fils de Llane, le roi mort pendant la Première Guerre.",
	["El rey Varian desapareció camino a una reunión de paz. Mientras tanto reina su hijo Anduin, todavía niño, con el alto señor Bolvar Fordragón como regente."] = "Le roi Varian a disparu en se rendant à un sommet pour la paix. En attendant, son jeune fils Anduin règne, avec le généralissime Bolvar Fordragon comme régent.",
	["El sanador de los chamanes: curas en cadena y tótems que ayudan a todo el grupo."] = "Le soigneur des chamans : soins en chaîne et totems qui aident tout le groupe.",
	["El sanador de los druidas: curas a cualquier grupo y sobrevives bien, aunque en solitario matas lento."] = "Le soigneur des druides : vous soignez n'importe quel groupe et survivez bien, même si en solo vous tuez lentement.",
	["El sanador de los paladines: curas fuertes y mucha armadura, ideal para grupos."] = "Le soigneur des paladins : soins puissants et beaucoup d'armure, idéal en groupe.",
	["El sanador puro: curas grandes y curas para todo el grupo."] = "Le soigneur pur : gros soins et soins pour tout le groupe.",
	["El servicio"] = "Le service",
	["El sistema de equipo de Alfa no está disponible."] = "Le système d'équipement d'Alfa n'est pas disponible.",
	["El sol aquí no perdona: las Tierras Inhóspitas son tierra de coyotes, buitres y basiliscos."] = "Ici, le soleil ne pardonne pas : les Terres ingrates sont le pays des coyotes, des busards et des basilics.",
	["El suelo y los muros se ven nítidos aunque estén lejos o de lado."] = "Le sol et les murs restent nets même de loin ou de biais.",
	["El talento que toca"] = "Votre prochain talent",
	["El tanque clásico: bloqueas mucho, generas amenaza con Revancha y Embate con escudo, y tienes Último recurso para cuando todo sale mal."] = "Le tank classique : vous bloquez beaucoup, générez de la menace avec Vengeance et Heurt de bouclier, et avez Dernier rempart quand tout tourne mal.",
	["El tanque más difícil de matar: todos los talentos de defensa, Muro de escudo mejorado y Último recurso pronto. Perfecto para empezar a tanquear."] = "Le tank le plus dur à tuer : tous les talents de défense, Mur protecteur amélioré et Dernier rempart tôt. Parfait pour débuter comme tank.",
	["El terreno real en el mapa"] = "Le vrai terrain sur la carte",
	["El texto es demasiado largo."] = "Le texte est trop long.",
	["El texto llegó cortado o cambiado: cópialo otra vez."] = "Le texte est arrivé coupé ou modifié : copiez-le à nouveau.",
	["El tipo de nodos que une la ruta."] = "Le type de nœuds que relie l'itinéraire.",
	["El tono de los fondos: Grafito es el de Alfa, Noche el más oscuro y Pizarra un gris neutro."] = "La teinte des fonds : Graphite est celle d'Alfa, Nuit la plus sombre et Ardoise un gris neutre.",
	["El top de DPS de tu grupo o banda en una ventana pequeña, con la pelea actual y la anterior."] = "Le top DPS de votre groupe ou raid dans une petite fenêtre, avec le combat actuel et le précédent.",
	["El torio abunda en el Cráter de Un'Goro y en Cuna del Invierno."] = "Le thorium abonde dans le cratère d'Un'Goro et au Berceau-de-l'Hiver.",
	["El tranvía a %s ya viene"] = "Le tram pour %s arrive",
	["El velo de pantalla de algunas zonas y hechizos de las sombras."] = "Le voile d'écran de certaines zones et de certains sorts d'Ombre.",
	["El vendedor más cercano"] = "Le vendeur le plus proche",
	["El verdadero nombre de Thrall es Go'el, el que le dieron sus padres."] = "Le vrai nom de Thrall est Go'el, celui que lui ont donné ses parents.",
	["El viejo ermitaño Abercrombie parece amable... hasta que descubres a quién intenta revivir."] = "Le vieil ermite Abercrombie a l'air gentil... jusqu'à ce que tu découvres qui il essaie de ramener.",
	["El zepelín a %s ya viene"] = "Le zeppelin pour %s arrive",
	["El «zug zug» de los peones quiere decir algo así como «de acuerdo». ¡Zug zug, jefe!"] = "Le « zug zug » des péons veut dire quelque chose comme « d'accord ». Zug zug, chef !",
	["El árbol de ruta de Alfa, misiones que se liberan y un catálogo de objetos."] = "L'arbre d'itinéraire d'Alfa, les quêtes à mesure qu'elles se débloquent et un catalogue d'objets.",
	["El ícono grande es lo que conviene presionar ahora y los pequeños, lo que sigue. Si late, el juego activó esa habilidad; el barrido oscuro es su recarga. Tú decides: Alfa nunca aprieta nada."] = "La grande icône est ce qu'il vaut mieux appuyer maintenant et les petites, ce qui suit. Si elle pulse, le jeu a mis cette technique en surbrillance ; le balayage sombre est sa recharge. C'est vous qui décidez : Alfa n'appuie jamais sur rien.",
	["El último punto: paras un poco más."] = "Le dernier point : vous parez un peu plus.",
	["Elegida por ti en los ajustes."] = "Choisie par vous dans les réglages.",
	["Elegida por tus talentos."] = "Choisie par vos talents.",
	["Elegido"] = "Choisi",
	["Elegido por ti"] = "Choisi par vous",
	["Elegir capas"] = "Choisir les calques",
	["Elegir la siguiente guía"] = "Choisir le guide suivant",
	["Elegir lo que pide tu paso"] = "Choisir ce que demande votre étape",
	["Elegir mi camino"] = "Choisir mon chemin",
	["Elegir mi primera guía"] = "Choisir mon premier guide",
	["Elegir mi tecla"] = "Choisir ma touche",
	["Elegir otra guía"] = "Choisir un autre guide",
	["Elegir para copiar"] = "Sélectionner pour copier",
	["Elegir qué sigue"] = "Choisir la suite",
	["Elegir todo"] = "Tout sélectionner",
	["Elegir una guía"] = "Choisir un guide",
	["Elegir una guía por ti"] = "Choisir un guide pour vous",
	["Elegiste: %s"] = "Choisi : %s",
	["Elemental"] = "Élémentaire",
	["Elemental para subir"] = "Élémentaire pour monter",
	["Elfos de la noche"] = "Elfes de la nuit",
	["Elige abajo qué cocinar y cuánto: la cola espera tu clic para cada lote."] = "Choisissez ci-dessous quoi cuisiner et combien : la file attend votre clic pour chaque fournée.",
	["Elige algo de la lista"] = "Choisissez quelque chose dans la liste",
	["Elige el objeto"] = "Choisissez l'objet",
	["Elige el objeto en la Enciclopedia."] = "Choisissez l'objet dans l'Encyclopédie.",
	["Elige la opción que nombra tu guía, o abre la tienda o el entrenamiento que necesitas."] = "Choisit l'option que nomme votre guide, ou ouvre la boutique ou l'entraînement dont vous avez besoin.",
	["Elige qué guardar: lo que ya tienes en el banco, los materiales, una categoría o todo lo que no sea equipo. Se mueve de una vez, fuera de combate."] = "Choisissez quoi ranger : ce que vous avez déjà à la banque, les matériaux, une catégorie ou tout ce qui n'est pas de l'équipement. Tout part d'un coup, hors combat.",
	["Elige qué quieres hacer y Alfa te lleva paso a paso."] = "Choisissez ce que vous voulez faire et Alfa vous guide pas à pas.",
	["Elige qué se ve en el mapa: guía, misiones, raros, viajes, zonas y lo que agregan otros módulos."] = "Choisissez ce qu'affiche la carte : guide, quêtes, rares, voyages, zones et ce qu'ajoutent les autres modules.",
	["Elige sola la única opción de los PNJ sin misiones."] = "Choisit tout seul l'unique option des PNJ sans quêtes.",
	["Elige solo misiones que ya puedes tomar."] = "Il ne choisit que des quêtes que vous pouvez déjà prendre.",
	["Elige tu camino. Si no sabes, empieza por subir de nivel: Alfa te dice qué conviene."] = "Choisissez votre chemin. Si vous hésitez, commencez par monter de niveau : Alfa vous dit ce qui est rentable.",
	["Elige tu estilo"] = "Choisissez votre style",
	["Elige tu tecla para pescar"] = "Choisissez votre touche de pêche",
	["Elige tus clics"] = "Choisissez vos clics",
	["Elige tus clics, acomoda tus marcos y pruébalos. Te toma un minuto."] = "Choisissez vos clics, placez vos cadres et testez-les. Cela prend une minute.",
	["Elige tus extras"] = "Choisis tes extras",
	["Elige tú la zona."] = "Vous choisissez la zone.",
	["Elige un camino: Alfa arma tu plan y te guía paso a paso."] = "Choisissez un chemin : Alfa prépare votre plan et vous guide pas à pas.",
	["Elige un marcador."] = "Choisissez un marqueur.",
	["Elige un servicio."] = "Choisissez un service.",
	["Elige una captura"] = "Choisissez une prise",
	["Elige una guía para empezar"] = "Choisissez un guide pour commencer",
	["Elige una mazmorra."] = "Choisissez un donjon.",
	["Elige una misión"] = "Choisissez une quête",
	["Elige una profesión"] = "Choisissez un métier",
	["Elige una profesión."] = "Choisissez un métier.",
	["Elige una y listo: Alfa ajusta tus misiones, tu guía, los comerciantes y los viajes. Mantén presionado Mayús en el juego para decidir tú en el momento."] = "Choisis-en un et c’est réglé : Alfa ajuste tes quêtes, ton guide, les marchands et les voyages. Maintiens Maj en jeu pour décider toi-même sur le moment.",
	["Elige uno y lo ves al instante en esta ventana y en todas las de Alfa, también la flecha."] = "Choisissez-en un et voyez-le aussitôt dans cette fenêtre et dans toutes celles d'Alfa, la flèche aussi.",
	["Eliges una"] = "Une au choix",
	["Ella duerme a todo el grupo y luego resucita a Mograine: es normal, no se asusten."] = "Elle endort tout le groupe puis ressuscite Mograine : c'est normal, pas de panique.",
	["Elune, la diosa de la luna, es la fe de los elfos de la noche. Sus sacerdotisas son las Hermanas de Elune, y Tyrande es su suma sacerdotisa."] = "Élune, la déesse de la lune, est la foi des elfes de la nuit. Ses prêtresses sont les Sœurs d'Élune, et Tyrande est leur grande prêtresse.",
	["Embate con escudo: mucho daño y amenaza."] = "Heurt de bouclier : beaucoup de dégâts et de menace.",
	["Embate deja de reiniciar tu ataque: un golpe extra entre golpe y golpe."] = "Heurtoir ne réinitialise plus votre attaque : un coup en plus entre deux coups.",
	["Embate sin perder tu ataque automático."] = "Heurtoir sans perdre votre attaque automatique.",
	["Embate sin perder tu ataque."] = "Heurtoir sans perdre votre attaque.",
	["Embate sin perder tu golpe automático."] = "Heurtoir sans perdre votre coup automatique.",
	["Embate sin reiniciar tu ataque: un golpe extra."] = "Heurtoir sans réinitialiser votre attaque : un coup en plus.",
	["Embate: un golpe fuerte entre golpe y golpe."] = "Heurtoir : un coup puissant entre deux attaques.",
	["Empezar"] = "Commencer",
	["Empezar de cero"] = "Repartir de zéro",
	["Empezar de nuevo"] = "Recommencer",
	["Empezar otra"] = "En commencer une autre",
	["Empezar otra sesión"] = "Commencer une autre session",
	["Empezó %s"] = "Commencée %s",
	["Empezó %s."] = "Commencée %s.",
	["Empieza al usar este objeto"] = "Commence quand vous utilisez cet objet",
	["Empieza aquí"] = "Commencez ici",
	["Empieza con %s, que se consigue en la mazmorra."] = "Elle commence avec %s, qui s'obtient dans le donjon.",
	["Empieza con %s, que suelta %s."] = "Elle commence avec %s, laissé par %s.",
	["Empieza con tu hechizo más lento desde lejos y termina con los instantáneos."] = "Commencez de loin avec votre sort le plus lent et finissez avec les instantanés.",
	["Empieza dentro"] = "Commence à l'intérieur",
	["Empieza una misión"] = "Commence une quête",
	["Empiezas: nivel %d"] = "Vous commencez : niveau %d",
	["En %s"] = "À %s",
	["En 9 idiomas"] = "En 9 langues",
	["En Burning Crusade, Karazhan abre sus puertas como banda."] = "Dans Burning Crusade, Karazhan ouvre ses portes en tant que raid.",
	["En Burning Crusade, el Vuelo Bronce pide ayuda en las Cavernas del Tiempo contra dragones que quieren cambiar la historia."] = "Dans Burning Crusade, le vol draconique bronze demande de l'aide dans les grottes du Temps contre des dragons qui veulent changer l'histoire.",
	["En Burning Crusade, las Cavernas del Tiempo te regresan a estas laderas para ver la huida de Thrall de Durnholde."] = "Dans Burning Crusade, les grottes du Temps te ramènent sur ces contreforts pour assister à l'évasion de Thrall de Fort-de-Durn.",
	["En Caer Darrow, junto al lago, todavía rondan los fantasmas de sus antiguos vecinos."] = "À Caer Darrow, près du lac, les fantômes de ses anciens habitants errent encore.",
	["En Ciudad Manitas, dentro de Forjaz, viven los gnomos que escaparon de Gnomeregan."] = "À Brikabrok, dans Forgefer, vivent les gnomes qui ont fui Gnomeregan.",
	["En Combate tienes el medidor de daño del grupo y la ayuda de rotación para tu clase."] = "Dans Combat, tu as le compteur de dégâts du groupe et l’aide à la rotation de ta classe.",
	["En Comercio ves precios de la subasta y qué te conviene vender. Yo vendo lo gris por ti con el comerciante."] = "Dans Commerce, tu vois les prix de l’hôtel des ventes et ce qu’il vaut mieux vendre. Je vends le gris pour toi chez le marchand.",
	["En Costa Oscura la Liga de Expedicionarios desentierra fósiles gigantes."] = "À Sombrivage, la Ligue des explorateurs déterre des fossiles géants.",
	["En Costa Oscura viven lechúcicos, criaturas mitad búho y mitad oso que veneran la luna."] = "À Sombrivage vivent des séléniens, mi-hiboux mi-ours, qui vénèrent la lune.",
	["En Desolace está el cementerio de los kodos, donde los viejos kodos van a morir."] = "En Désolace se trouve le cimetière des Kodos, où les vieux kodos vont mourir.",
	["En Durotar ya te topas con el Filo Ardiente, un culto de brujos orcos que sigue adorando a los demonios."] = "Dès Durotar, tu croises la Lame ardente, un culte de démonistes orcs qui adorent encore les démons.",
	["En Elwynn, una señora vende gatitos de compañía. ¡Yo me llevo bien con los gatos... casi siempre!"] = "En Elwynn, une dame vend des chatons de compagnie. Je m'entends bien avec les chats... presque toujours !",
	["En Entrañas venden cucarachas de mascota. Cada quien sus gustos."] = "À Fossoyeuse, on vend des cafards comme mascottes. Chacun ses goûts.",
	["En Feralas está uno de los grandes árboles por los que los dragones verdes entran al Sueño Esmeralda."] = "Féralas abrite l'un des grands arbres par lesquels les dragons verts entrent dans le Rêve d'émeraude.",
	["En Forever, Onyxia, la Cumbre Hyjal y Barrow Deeps dan retos del Legado al vencerlas."] = "Dans Forever, Onyxia, le Sommet d'Hyjal et Barrow Deeps donnent des défis de l'Héritage quand tu les vaincs.",
	["En Forever, el banco vende casillas de bolsa una tras otra: más espacio para tus tesoros."] = "Dans Forever, la banque vend des emplacements de sac l'un après l'autre : plus de place pour tes trésors.",
	["En Forever, los rangos de honor y la reputación de los campos de batalla también dan retos del Legado."] = "Dans Forever, les rangs d'honneur et la réputation des champs de bataille donnent aussi des défis de l'Héritage.",
	["En Forever, los retos del Legado dan puntos a toda tu cuenta, y cada personaje los gasta en sus árboles. Ábrelo con la tecla Y."] = "Dans Forever, les défis de l'Héritage donnent des points à tout ton compte, et chaque personnage les dépense dans ses arbres. Ouvre-le avec la touche Y.",
	["En Forjaz, la sala de la Liga de Expedicionarios tiene un museo con fósiles enormes. Brann Barbabronce es su explorador más famoso."] = "À Forgefer, la salle de la Ligue des explorateurs abrite un musée aux fossiles énormes. Brann Barbe-de-bronze est son explorateur le plus célèbre.",
	["En Gadgetzan, el cocinero Dirge enseña una de las mejores recetas del Clásico, con carne de quimerok."] = "À Gadgetzan, le cuisinier Dirge enseigne l'une des meilleures recettes de Classic, à base de viande de chimérok.",
	["En Jaedenar se esconde el Consejo de la Sombra, brujos que sirven a la Legión Ardiente."] = "Le Conseil des ombres, des démonistes au service de la Légion ardente, se cache à Jaedenar.",
	["En Jardín Noble se esconden huevos de colores por los pueblos iniciales; dentro hay dulces y a veces ropa de primavera."] = "Pendant le Jardin des nobles, des œufs colorés sont cachés dans les villages de départ ; ils contiennent des friandises et parfois des tenues de printemps.",
	["En Kharanos, la posada y la destilería Cebatruenos son la parada obligada para calentarse... por dentro y por fuera."] = "À Kharanos, l'auberge et la distillerie Tonnebière sont l'arrêt obligé pour se réchauffer... dedans comme dehors.",
	["En La Jauría > Guaridas te digo en cuál estás y en cuáles anda la manada. Con «Pedir entrar» te pasas a la de un lobo con la puerta abierta."] = "Dans La Jauría > Tanières, je te dis dans laquelle tu es et où est la meute. Avec « Demander à entrer », tu passes chez un loup à la porte ouverte.",
	["En La Jauría > Guaridas toca «Llamar a la manada» (o escribe /alfa manada llamar): los lobos de tu zona reciben tu lugar y te aviso quién viene."] = "Dans La Jauría > Tanières, touche « Appeler la meute » (ou /alfa manada llamar) : les loups de ta zone reçoivent ta position et je te dis qui vient.",
	["En La Jauría ves a tu grupo y a los lobos que se dejan ver en el mapa. Puedes seguirlos con la flecha o invitarlos."] = "Dans La Jauría, tu vois ton groupe et les loups qui se montrent sur la carte. Tu peux les suivre avec la flèche ou les inviter.",
	["En Mazmorras ves cuáles van con tu nivel, sus jefes, su botín, sus misiones y cómo llegar a la entrada."] = "Dans Donjons, tu vois ceux de ton niveau, leurs boss, leur butin, leurs quêtes et comment rejoindre l’entrée.",
	["En Molino Ámbar se refugian magos de Dalaran, y no les gustan nada las visitas de los Renegados."] = "Des mages de Dalaran se réfugient au Moulin-de-l'Ambre, et ils n'aiment pas du tout les visites des Réprouvés.",
	["En Mundo pones tus marcadores, los compartes con tu grupo y la flecha te lleva a ellos."] = "Dans Monde, tu poses tes marqueurs, tu les partages avec ton groupe et la flèche t’y emmène.",
	["En Naxxramas, el gran Alexandros Mograine reaparece como uno de los Cuatro Jinetes de la Plaga. Qué triste destino para un héroe."] = "À Naxxramas, le grand Alexandros Mograine revient comme l'un des Quatre cavaliers du Fléau. Quel triste destin pour un héros.",
	["En Nethergarde, unos magos de sangre te cambian partes de las bestias de aquí por elixires que te potencian un buen rato."] = "À Rempart-du-Néant, des mages de sang t'échangent des morceaux des bêtes du coin contre des élixirs qui te renforcent un bon moment.",
	["En Orgrimmar, el Valle de la Sabiduría guarda la fortaleza de Thrall, y el Valle del Honor reúne a guerreros y cazadores."] = "À Orgrimmar, la vallée de la Sagesse abrite la forteresse de Thrall, et la vallée de l'Honneur rassemble guerriers et chasseurs.",
	["En Paisaje y gráficos hay un paisaje más bonito con un clic, y cada ajuste gráfico explicado."] = "Dans Paysage et graphismes, un plus beau paysage en un clic, et chaque réglage graphique expliqué.",
	["En Pesca tienes una sola tecla para equiparte, lanzar y recoger, un diario de lo que sacas y una guía de 1 a 300."] = "Dans Pêche, une seule touche pour t’équiper, lancer et ramasser, un journal de tes prises et un guide de 1 à 300.",
	["En Pico Nidal manda el thane Falstad Martillo Salvaje, señor de los jinetes de grifo."] = "Au Nid-de-l'Aigle règne le thane Falstad Marteau-hardi, seigneur des chevaucheurs de griffon.",
	["En Pico Nidal viven los enanos Martillo Salvaje, famosos por volar sobre grifos."] = "Les nains Marteau-hardi vivent au Nid-de-l'Aigle, célèbres pour voler à dos de griffon.",
	["En Recolección eliges qué buscar y te marco en el mapa los puntos de tus profesiones, con los que ya encontraste."] = "Dans Récolte, tu choisis quoi chercher et je marque sur la carte les points de tes métiers, avec ceux que tu as déjà trouvés.",
	["En Ruta eliges a dónde ir y yo te armo el camino. La flecha te lleva paso a paso y el rastrador te dice qué toca."] = "Dans Route, tu choisis où aller et je te trace le chemin. La flèche te guide pas à pas et le suivi te dit la suite.",
	["En Seradane hay uno de los grandes árboles que llevan al Sueño Esmeralda, y los dragones verdes lo custodian."] = "Seradane abrite l'un des grands arbres qui mènent au Rêve d'émeraude, et les dragons verts le gardent.",
	["En Talentos te digo qué punto poner y por qué, según tu clase y cómo juegas."] = "Dans Talents, je te dis quel point mettre et pourquoi, selon ta classe et ta façon de jouer.",
	["En Tanaris están las Cavernas del Tiempo, donde el Vuelo Bronce de Nozdormu vigila la historia."] = "Tanaris abrite les grottes du Temps, où le vol draconique bronze de Nozdormu veille sur l'histoire.",
	["En Tirisfal está la entrada al Monasterio Escarlata, uno de los lugares más visitados por los aventureros de nivel medio."] = "Tirisfal abrite l'entrée du monastère Écarlate, l'un des lieux les plus visités par les aventuriers de niveau moyen.",
	["En Uldaman están los Discos de Norgannon, registros de los titanes que cuentan cómo crearon a los terráneos, los antepasados de piedra de los enanos."] = "À Uldaman se trouvent les Disques de Norgannon, des archives des titans qui racontent comment ils ont créé les terrestres, les ancêtres de pierre des nains.",
	["En Vallefresno, Grom Grito Infernal mató al semidiós Cenarius cuando la Horda empezó a talar el bosque."] = "En Orneval, Grom Hurlenfer a tué le demi-dieu Cénarius quand la Horde a commencé à abattre la forêt.",
	["En Vallefresno, Grom volvió a beber sangre demoníaca; Thrall lo rescató y Grom pudo redimirse antes de morir."] = "En Orneval, Grom a de nouveau bu du sang démoniaque ; Thrall l'a sauvé et Grom a pu se racheter avant de mourir.",
	["En Ventormenta hay un barrio de enanos, uno de magos y un parque donde se reúnen los elfos de la noche."] = "Hurlevent a un quartier des nains, un quartier des mages et un parc où se retrouvent les elfes de la nuit.",
	["En Warcraft III, si le das muchos clics a una unidad empieza a decir cosas chistosas. Yo, en cambio, te doy consejos."] = "Dans Warcraft III, si tu cliques souvent sur une unité, elle se met à dire des choses drôles. Moi, je te donne des conseils.",
	["En arco"] = "En arc",
	["En bancos de peces de: %s."] = "Dans les bancs de poissons de : %s.",
	["En camino"] = "En route",
	["En cero los números suben derechos; más alto, salen disparados hacia los lados."] = "À zéro, les chiffres montent tout droit ; plus haut, ils partent sur les côtés.",
	["En combate"] = "En combat",
	["En combate el juego oculta los números exactos: las barras y las cifras se ven igual, el detalle y el anuncio, al salir."] = "En combat, le jeu masque les chiffres exacts : les barres et les chiffres restent visibles ; le détail et l'annonce, à la sortie du combat.",
	["En combate el mapa del juego no se abre desde Alfa: usa el de Alfa."] = "En combat, la carte du jeu ne s'ouvre pas depuis Alfa : utilisez celle d'Alfa.",
	["En combate no aparece el cuadro de los personajes y criaturas del mundo (el de los marcos sí)."] = "En combat, l'infobulle des personnages et des créatures du monde n'apparaît pas (celle des cadres reste affichée).",
	["En combate no hay prueba: sal de la pelea y vuelve a este paso."] = "Pas de test en combat : quittez le combat et revenez à cette étape.",
	["En combate no puedo buscar: inténtalo al terminar la pelea."] = "Je ne peux pas chercher en combat : réessayez après le combat.",
	["En combate no se puede: espera a terminar."] = "Impossible en combat : attendez la fin.",
	["En combate · la pesca espera"] = "En combat · la pêche attend",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard y las %d que siguen. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "En combat, l'icône montre la technique suggérée par l'assistant de combat de Blizzard et les %d suivantes. C'est vous qui décidez sur quoi appuyer : Alfa n'appuie jamais à votre place.",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "En combat, l'icône montre la technique suggérée par l'assistant de combat de Blizzard. C'est vous qui décidez sur quoi appuyer : Alfa n'appuie jamais à votre place.",
	["En combate: espera a terminar"] = "En combat : attendez la fin",
	["En curso"] = "En cours",
	["En el Casco Antiguo está el SI:7, los espías y pícaros al servicio del reino."] = "La Vieille ville abrite le SI:7, les espions et voleurs au service du royaume.",
	["En el Clásico mandan Thrall en Orgrimmar, Cairne en Cima del Trueno, Sylvanas en Entrañas y Vol'jin con los Lanza Negra."] = "En Classic, Thrall règne à Orgrimmar, Cairne aux Pitons-du-Tonnerre, Sylvanas à Fossoyeuse et Vol'jin guide les Sombrelances.",
	["En el Clásico nadie sabe dónde anda Alamuerte; los que dan la cara son sus hijos, Onyxia y Nefarian."] = "En Classic, personne ne sait où se trouve Aile-de-mort ; ceux qui se montrent sont ses enfants, Onyxia et Nefarian.",
	["En el Clásico necesitas flechas o balas: lleva siempre de más en tu carcaj o tu bolsa de munición."] = "En Classic, il te faut des flèches ou des balles : gardes-en toujours en réserve dans ton carquois ou ta giberne.",
	["En el Clásico necesitas un cuchillo de desollar en tus bolsas."] = "En Classic, il te faut un couteau à dépecer dans tes sacs.",
	["En el Clásico solo puedes tener dos profesiones principales, pero Cocina, Pesca y Primeros auxilios se aprenden aparte."] = "En Classic, tu ne peux avoir que deux métiers principaux, mais la Cuisine, la Pêche et le Secourisme s'apprennent en plus.",
	["En el Clásico, Costasur contra Molino Tarren era la pelea entre bandos más famosa del mundo."] = "En Classic, Austrivage contre Moulin-de-Tarren était le combat entre factions le plus célèbre du monde.",
	["En el Clásico, a nivel 20 aprendes a teletransportarte a las capitales, y a 40 a abrir portales para los demás."] = "En Classic, au niveau 20 tu apprends à te téléporter dans les capitales, et au 40 à ouvrir des portails pour les autres.",
	["En el Clásico, a nivel 20 haces la misión de los venenos; después los mejoras con tu entrenador."] = "En Classic, au niveau 20 tu fais la quête des poisons ; ensuite, tu les améliores chez ton maître.",
	["En el Clásico, a nivel 40 haces la misión de tu caballo de guerra, y a 60 la cadena épica del destrero."] = "En Classic, au niveau 40 tu fais la quête de ton cheval de guerre, et au 60 la chaîne épique du destrier.",
	["En el Clásico, a nivel 40 recibes un corcel vil, y a 60 una cadena épica en La Masacre te da uno aún más temible."] = "En Classic, au niveau 40 tu reçois un palefroi corrompu, et au 60 une chaîne épique à Hache-tripes t'en donne un encore plus redoutable.",
	["En el Clásico, abrir las puertas de Ahn'Qiraj pidió un esfuerzo de guerra de todo el servidor: montañas de materiales y una cadena larguísima."] = "En Classic, ouvrir les portes d'Ahn'Qiraj a demandé un effort de guerre de tout le serveur : des montagnes de matériaux et une chaîne interminable.",
	["En el Clásico, algunos peces solo pican de noche o de día."] = "En Classic, certains poissons ne mordent que la nuit ou que le jour.",
	["En el Clásico, cada raza de sacerdote tiene un hechizo propio. Pregúntale a tu entrenador cuál te toca."] = "En Classic, chaque race de prêtre a un sort qui lui est propre. Demande à ton maître lequel est le tien.",
	["En el Clásico, después de vendarte queda un rato en que no puedes usar otra venda."] = "En Classic, après un bandage, il faut attendre un moment avant d'en utiliser un autre.",
	["En el Clásico, el Cetro de las Arenas Movedizas abrió las puertas de Ahn'Qiraj tras una larguísima cadena de misiones."] = "En Classic, le Sceptre des Sables changeants a ouvert les portes d'Ahn'Qiraj après une chaîne de quêtes interminable.",
	["En el Clásico, el arco épico de los cazadores sale de una cadena contra demonios que empieza en el Claro de la Luna."] = "En Classic, l'arc épique des chasseurs vient d'une chaîne contre des démons qui commence à Reflet-de-Lune.",
	["En el Clásico, el chat de Los Baldíos era famoso por sus pláticas eternas... y por preguntar dónde estaba la esposa de Mankrik."] = "En Classic, le canal des Tarides était célèbre pour ses discussions sans fin... et pour demander où était la femme de Mankrik.",
	["En el Clásico, el nivel máximo es 60 y llegar lleva su tiempo. Por eso cada nivel se festeja."] = "En Classic, le niveau maximum est 60 et y arriver prend du temps. C'est pour ça que chaque niveau se fête.",
	["En el Clásico, el rango de honor 14 es Gran Mariscal para la Alianza y Gran Señor de la Guerra para la Horda."] = "En Classic, le rang d'honneur 14 est Grand maréchal pour l'Alliance et Grand seigneur de guerre pour la Horde.",
	["En el Clásico, la Feria de la Luna Negra a veces se instala en Mulgore, cerca del poblado Pezuña de Sangre."] = "En Classic, la Foire de Sombrelune s'installe parfois en Mulgore, près du village de Sabot-de-Sang.",
	["En el Clásico, la Feria de la Luna Negra a veces se instala junto a Villadorada."] = "En Classic, la Foire de Sombrelune s'installe parfois près de Comté-de-l'Or.",
	["En el Clásico, la Horda la forman orcos, trols Lanza Negra, tauren y Renegados; la Alianza, humanos, enanos, gnomos y elfos de la noche."] = "En Classic, la Horde réunit orcs, trolls Sombrelance, Taurens et Réprouvés ; l'Alliance, humains, nains, gnomes et elfes de la nuit.",
	["En el Clásico, la Plaga invadió el mundo con necrópolis flotantes antes de que se abriera Naxxramas."] = "En Classic, le Fléau a envahi le monde avec des nécropoles volantes avant l'ouverture de Naxxramas.",
	["En el Clásico, la actitud defensiva se gana con una misión al nivel 10, y la rabiosa con otra al nivel 30."] = "En Classic, la Posture défensive s'obtient avec une quête au niveau 10, et la Posture berserker avec une autre au niveau 30.",
	["En el Clásico, la casa de subastas de Forjaz es la más movida de toda la Alianza."] = "En Classic, l'hôtel des ventes de Forgefer est le plus animé de toute l'Alliance.",
	["En el Clásico, la forma de oso se gana con una misión a nivel 10 y la acuática con otra a nivel 16; luego vienen la felina y la de viaje."] = "En Classic, la forme d'ours s'obtient avec une quête au niveau 10 et la forme aquatique avec une autre au niveau 16 ; viennent ensuite la forme de félin et celle de voyage.",
	["En el Clásico, la montura de nivel 40 es mucho más rápida que correr, y la épica de nivel 60 todavía más."] = "En Classic, la monture du niveau 40 est bien plus rapide que la course, et l'épique du niveau 60 encore plus.",
	["En el Clásico, la tela se puede donar en tu capital a cambio de reputación."] = "En Classic, tu peux donner du tissu dans ta capitale en échange de réputation.",
	["En el Clásico, las bandas grandes son de 40 jugadores, y Zul'Gurub y las Ruinas de Ahn'Qiraj, de 20."] = "En Classic, les grands raids sont à 40 joueurs, et Zul'Gurub et les ruines d'Ahn'Qiraj à 20.",
	["En el Clásico, los Renegados se quitan el miedo, el encanto y el sueño con su voluntad."] = "En Classic, les Réprouvés se débarrassent de la peur, du charme et du sommeil par leur volonté.",
	["En el Clásico, los domingos por la tarde Bahía del Botín organizaba un concurso de pesca: ganaba quien entregara primero cuarenta peces de una especie especial."] = "En Classic, le dimanche après-midi, Baie-du-Butin organisait un concours de pêche : gagnait le premier à rendre quarante poissons d'une espèce spéciale.",
	["En el Clásico, los enanos pueden buscar tesoros con un rastreo propio. ¡Ideal para encontrar cofres!"] = "En Classic, les nains peuvent repérer les trésors grâce à une découverte qui leur est propre. Idéal pour trouver des coffres !",
	["En el Clásico, los enanos se convierten en piedra para quitarse venenos y sangrados, y son buenos con las armas de fuego."] = "En Classic, les nains se changent en pierre pour se débarrasser des poisons et saignements, et ils sont doués avec les armes à feu.",
	["En el Clásico, los gnomos pueden ser guerreros, pícaros, magos o brujos."] = "En Classic, les gnomes peuvent être guerriers, voleurs, mages ou démonistes.",
	["En el Clásico, los gnomos son más listos que el resto, tienen talento para la ingeniería y se zafan de lo que los inmoviliza."] = "En Classic, les gnomes sont plus malins que les autres, ont un don pour l'ingénierie et se libèrent de ce qui les immobilise.",
	["En el Clásico, los humanos ganan reputación más rápido gracias a su diplomacia, y tienen buen ojo para ver a los sigilosos."] = "En Classic, les humains gagnent de la réputation plus vite grâce à leur diplomatie, et ont l'œil pour repérer les furtifs.",
	["En el Clásico, los maestros de armas de las capitales te enseñan a usar armas nuevas."] = "En Classic, les maîtres d'armes des capitales t'apprennent à manier de nouvelles armes.",
	["En el Clásico, los orcos resisten mejor los aturdimientos y sus mascotas pegan más fuerte."] = "En Classic, les orcs résistent mieux aux étourdissements et leurs familiers frappent plus fort.",
	["En el Clásico, los tauren tienen más vida, un pisotón que aturde a los enemigos cercanos y mano verde con las hierbas."] = "En Classic, les Taurens ont plus de points de vie, un piétinement qui étourdit les ennemis proches et la main verte avec les herbes.",
	["En el Clásico, los trols se regeneran rápido, entran en frenesí, pegan más fuerte a las bestias y son buenos con arcos y armas arrojadizas."] = "En Classic, les trolls se régénèrent vite, entrent en berserker, frappent plus fort les bêtes et sont doués avec les arcs et les armes de jet.",
	["En el Clásico, muchas comidas te dejan bien alimentado y te suben estadísticas un buen rato."] = "En Classic, beaucoup de plats te laissent bien nourri et augmentent tes caractéristiques un bon moment.",
	["En el Clásico, para pasar de 225 hay una misión de triaje en Theramore o en Sentencia."] = "En Classic, pour dépasser 225, il y a une quête de triage à Theramore ou à Trépas-d'Orgrim.",
	["En el Clásico, quienes terminaron la cadena del cetro y tocaron el gong de Ahn'Qiraj ganaron un título y una montura únicos."] = "En Classic, ceux qui ont terminé la chaîne du sceptre et sonné le gong d'Ahn'Qiraj ont gagné un titre et une monture uniques.",
	["En el Clásico, solo elfos de la noche y tauren pueden ser druidas."] = "En Classic, seuls les elfes de la nuit et les Taurens peuvent être druides.",
	["En el Clásico, solo humanos y enanos pueden ser paladines."] = "En Classic, seuls les humains et les nains peuvent être paladins.",
	["En el Clásico, solo orcos, trols y tauren pueden ser chamanes."] = "En Classic, seuls les orcs, les trolls et les Taurens peuvent être chamans.",
	["En el Clásico, tu Reencarnación te revive a ti mismo, pero necesita un ankh en tus bolsas."] = "En Classic, ta Réincarnation te ramène toi-même à la vie, mais il faut un ankh dans tes sacs.",
	["En el Enclave Cenarion los druidas enseñan a los suyos el camino de la naturaleza."] = "Dans l'enclave cénarienne, les druides enseignent aux leurs la voie de la nature.",
	["En el Festival Lunar, la gente viene al Claro de la Luna a honrar a sus ancestros."] = "Pendant la fête lunaire, les gens viennent à Reflet-de-Lune honorer leurs ancêtres.",
	["En el Festival Lunar, un emisario en las capitales te puede llevar al Claro de la Luna para celebrar con los druidas."] = "Pendant la fête lunaire, un émissaire dans les capitales peut t'emmener à Reflet-de-Lune pour fêter avec les druides.",
	["En el Festival de Fuego del Solsticio de Verano hay hogueras en muchos pueblos: honrar las de tu bando da premios, y apagar las del otro también."] = "Pendant la fête du Feu du solstice d'été, des feux brûlent dans beaucoup de villages : honorer ceux de ta faction rapporte des récompenses, éteindre ceux de l'autre aussi.",
	["En el Festival de Invierno venden bolas de nieve. ¡Lánzaselas a tus amigos, que yo las atrapo!"] = "Pendant le Voile d'hiver, on vend des boules de neige. Lance-les sur tes amis, je les attrape !",
	["En el Festival de Invierno, el Gran Padre Invierno reparte regalos en Forjaz y Orgrimmar, y bajo el árbol aparecen paquetes el día 25."] = "Pendant le Voile d'hiver, Grand-père Hiver distribue des cadeaux à Forgefer et Orgrimmar, et des paquets apparaissent sous l'arbre le 25.",
	["En el Festival de la Cosecha, la Horda honra a Grom Grito Infernal y la Alianza a Uther, en sus monumentos."] = "Pendant la fête des Moissons, la Horde honore Grom Hurlenfer et l'Alliance honore Uther, à leurs monuments.",
	["En el Núcleo de Magma se desuellan perros del núcleo para un cuero muy especial."] = "Dans le Cœur du Magma, on dépèce les chiens du Magma pour un cuir très spécial.",
	["En el Santuario Esmeralda, los druidas intentan sanar el bosque enfermo."] = "Au sanctuaire d'Émeraude, les druides tentent de soigner la forêt malade.",
	["En el Valle de Alterac pelean la Guardia Pico Tormenta de los enanos y el clan Lobo Gélido. Yo ya sé a quién le voy."] = "Dans la vallée d'Alterac, la garde Foudrepique des nains affronte le clan Loup-de-givre. Je sais déjà pour qui je suis.",
	["En el Valle de la Fuerza están el banco y la casa de subastas: el corazón del comercio de la Horda."] = "La vallée de la Force abrite la banque et l'hôtel des ventes : le cœur du commerce de la Horde.",
	["En el camino"] = "Sur le chemin",
	["En el centro de aquel Kalimdor estaba el Pozo de la Eternidad, un lago de pura magia. Unos trols que vivían a su orilla cambiaron con los siglos y se volvieron los elfos de la noche."] = "Au centre de ce Kalimdor-là se trouvait le Puits d'éternité, un lac de magie pure. Des trolls qui vivaient sur ses rives ont changé au fil des siècles et sont devenus les elfes de la nuit.",
	["En el centro de la garganta hay un enorme pozo de lava, la Caldera, donde trabajan esclavos de los Hierro Negro."] = "Au centre de la gorge se trouve une immense fosse de lave, le Chaudron, où triment des esclaves des Sombrefer.",
	["En el centro del cráter humea un volcán donde viven elementales de fuego."] = "Au centre du cratère fume un volcan où vivent des élémentaires de feu.",
	["En el chat"] = "Dans la discussion",
	["En el corazón del Templo de la Luna hay un pozo lunar, donde las sacerdotisas rezan a Elune."] = "Au cœur du temple de la Lune se trouve un puits de lune, où les prêtresses prient Élune.",
	["En el cráter, un tal Linken perdió la memoria y busca su espada y su escudo: un guiño a cierto héroe de orejas puntiagudas."] = "Dans le cratère, un certain Linken a perdu la mémoire et cherche son épée et son bouclier : un clin d'œil à un certain héros aux oreilles pointues.",
	["En el este de las Tierras Inhóspitas viven dragones negros y sus siervos. Pasa lejitos si no llevas compañía."] = "À l'est des Terres ingrates vivent des dragons noirs et leurs serviteurs. Passe au large si tu es seul.",
	["En el este del lago viven ogros que les hacen la vida difícil a los enanos de Thelsamar."] = "À l'est du lac vivent des ogres qui mènent la vie dure aux nains de Thelsamar.",
	["En el gran salar del este, goblins y gnomos organizan carreras; la rivalidad es feroz."] = "Sur le grand désert de sel à l'est, gobelins et gnomes organisent des courses ; la rivalité est féroce.",
	["En el juego"] = "Dans le jeu",
	["En el lago de Villa del Lago hay múrlocs, ¡como en casi todo lago de Azeroth!"] = "Il y a des murlocs dans le lac de Comté-du-Lac, comme dans presque tous les lacs d'Azeroth !",
	["En el mapa"] = "Sur la carte",
	["En el mapa de Alfa, clic: seguirla con la flecha o guardarla como marcador."] = "Sur la carte d'Alfa, clic : la suivre avec la flèche ou l'enregistrer comme marqueur.",
	["En el mapa del mundo"] = "Sur la carte du monde",
	["En el marco del objetivo"] = "Sur le cadre de la cible",
	["En el minimapa"] = "Sur la minicarte",
	["En el mundo"] = "Dans le monde",
	["En el nivel 10 domas tu bestia."] = "Au niveau 10, vous apprivoisez votre bête.",
	["En el nivel 20 aprendes venenos."] = "Au niveau 20, vous apprenez les poisons.",
	["En el norte de estas tierras, la Cruzada Escarlata domina un pueblo amurallado y lo defiende con fanatismo."] = "Au nord de ces terres, la Croisade écarlate tient un village fortifié et le défend avec fanatisme.",
	["En el oeste de Las Mil Agujas anidan dracoleones salvajes."] = "Des wyvernes sauvages nichent à l'ouest de Mille pointes.",
	["En el pueblo de los druidas del Claro de la Luna conviven Alianza y Horda: el Círculo Cenarion recibe a todos."] = "Dans le village druidique de Reflet-de-Lune, Alliance et Horde cohabitent : le Cercle cénarien accueille tout le monde.",
	["En el sur de Desolace, demonios y sátiros se reúnen en un aquelarre."] = "Dans le sud de Désolace, démons et satyres se réunissent en sabbat.",
	["En el sur de Tanaris hay colmenas de silítidos, primos de los de Silithus."] = "Au sud de Tanaris, il y a des ruches de silithides, cousins de ceux de Silithus.",
	["En el sureste, la Mano de Tyr es la ciudad más fuerte que le queda a la Cruzada Escarlata."] = "Au sud-est, la Main de Tyr est la ville la plus forte qui reste à la Croisade écarlate.",
	["En espera"] = "En attente",
	["En esta zona"] = "Dans cette zone",
	["En estas laderas está Durnholde, donde Aedelas Blackmoore crió a Thrall como gladiador."] = "Sur ces collines se dresse Fort-de-Durn, où Aedelas Blackmoore a élevé Thrall comme gladiateur.",
	["En estas tierras cayó Anduin Lothar, el León de Azeroth, durante la Segunda Guerra."] = "C'est sur ces terres qu'est tombé Anduin Lothar, le Lion d'Azeroth, pendant la Deuxième Guerre.",
	["En estas tierras estuvo Strom, la capital de Arathor, el primer gran reino humano."] = "Sur ces terres se dressait Strom, la capitale d'Arathor, le premier grand royaume humain.",
	["En este pantano se hundió el Templo de Atal'Hakkar: los dragones verdes lo hundieron para frenar a los sacerdotes de Hakkar."] = "Le temple d'Atal'Hakkar a sombré dans ce marais : les dragons verts l'ont englouti pour arrêter les prêtres d'Hakkar.",
	["En grifo, la línea de tu vuelo en el mapa: por dónde vas, dónde aterrizas y el tiempo que falta."] = "En griffon, la ligne de ton vol sur la carte : où tu en es, où tu atterris et le temps qu'il reste.",
	["En grupo"] = "En groupe",
	["En grupo casi siempre hay varios enemigos: pegas a dos a la vez."] = "En groupe, il y a presque toujours plusieurs ennemis : vous en frappez deux à la fois.",
	["En grupo y aguantando: Furia justa te da más amenaza."] = "En groupe et en tankant : Fureur vertueuse vous donne plus de menace.",
	["En grupo, cura al tanque antes que a nadie."] = "En groupe, soignez le tank avant tout le monde.",
	["En grupo, cura al tanque primero y no saques monstruos tú."] = "En groupe, soignez d'abord le tank et n'attirez pas de monstres vous-même.",
	["En grupo, cura antes de que la vida baje mucho: es más barato."] = "En groupe, soignez avant que la vie ne baisse trop : ça coûte moins cher.",
	["En grupo, deja tus tótems de maná y de curas cerca del grupo."] = "En groupe, posez vos totems de mana et de soins près du groupe.",
	["En la %s"] = "Dans la %s",
	["En la Arena Gurubashi aparece de vez en cuando un cofre que todos se pelean. ¡Sálvese quien pueda!"] = "De temps en temps, un coffre apparaît dans l'arène des Gurubashi et tout le monde se le dispute. Sauve qui peut !",
	["En la Enciclopedia"] = "Dans l'Encyclopédie",
	["En la Feria canjeas vales por premios; los vales se ganan entregando cosas que hiciste con tu profesión o que juntaste cazando."] = "À la Foire, tu échanges des tickets contre des prix ; les tickets se gagnent en rendant des choses fabriquées avec ton métier ou récoltées en chassant.",
	["En la Feria de la Luna Negra, la adivina Sayge te hace unas preguntas y te da una fortuna que sube tus estadísticas un buen rato."] = "À la Foire de Sombrelune, la diseuse de bonne aventure Sayge te pose quelques questions et te donne une fortune qui augmente tes caractéristiques un bon moment.",
	["En la Fortaleza de Grommash, Thrall recibe a quien venga; muy cerca está Eitrigg, el viejo orco amigo de Tirion."] = "Au fort Grommash, Thrall reçoit tous ceux qui viennent ; tout près se tient Eitrigg, le vieil orc ami de Tirion.",
	["En la Guerra de las Arenas Movedizas, el archidruida Fandral perdió a su hijo Valstann a manos de los qiraji."] = "Pendant la guerre des Sables changeants, l'archidruide Fandral a perdu son fils Valstann face aux Qiraji.",
	["En la Segunda Guerra, la Horda sumó a los trols Amani, a los ogros y a dragones rojos esclavizados."] = "Pendant la Deuxième Guerre, la Horde a été rejointe par les trolls Amani, les ogres et des dragons rouges asservis.",
	["En la Semana de los Niños, los huérfanos de Ventormenta y Orgrimmar te piden que los lleves de paseo; al final te dan una mascota."] = "Pendant la Semaine des enfants, les orphelins de Hurlevent et d'Orgrimmar te demandent de les emmener en promenade ; à la fin, ils t'offrent une mascotte.",
	["En la Tercera Guerra, orcos, humanos y elfos se unieron aquí contra Archimonde, y Nordrassil sacrificó su energía para destruirlo."] = "Pendant la Troisième Guerre, orcs, humains et elfes se sont unis ici contre Archimonde, et Nordrassil a sacrifié son énergie pour le détruire.",
	["En la Terraza de los Artesanos de Darnassus están los maestros de profesiones."] = "La terrasse des Artisans de Darnassus abrite les maîtres de métier.",
	["En la Vega se encuentran páginas sueltas de un libro de Nesingwary; junta un capítulo completo y llévaselo."] = "Dans la vallée de Strangleronce, on trouve des pages éparses d'un livre de Nesingwary ; réunis un chapitre complet et apporte-le-lui.",
	["En la batalla de Hyjal, Malfurion hizo sonar el Cuerno de Cenarius y miles de fuegos fatuos rodearon a Archimonde hasta destruirlo."] = "Lors de la bataille d'Hyjal, Malfurion a sonné le Cor de Cénarius et des milliers de feux follets ont encerclé Archimonde jusqu'à le détruire.",
	["En la casa de subastas, mira los precios unos días antes de vender: cambian según la hora y quién esté jugando."] = "À l'hôtel des ventes, observe les prix quelques jours avant de vendre : ils changent selon l'heure et qui joue.",
	["En la cima del Monte Hyjal crece Nordrassil, el Árbol del Mundo, que los dragones bendijeron."] = "Au sommet du mont Hyjal pousse Nordrassil, l'Arbre-Monde béni par les dragons.",
	["En la costa de Durotar, soldados de Kul Tiras ocupan el Fuerte Tiragarde: una espina clavada en la tierra de la Horda."] = "Sur la côte de Durotar, des soldats de Kul Tiras occupent le donjon de Tiragarde : une épine plantée dans la terre de la Horde.",
	["En la costa de Tanaris se esconden piratas de los Mares del Sur."] = "Des pirates de la Mer du Sud se cachent sur la côte de Tanaris.",
	["En la costa del pantano hay naga, y no reciben bien a los curiosos."] = "Il y a des nagas sur la côte du marais, et ils n'accueillent pas bien les curieux.",
	["En la costa este vive una tribu trol amiga de la Horda, enemiga de los trols de Jintha'Alor."] = "Sur la côte est vit une tribu troll amie de la Horde et ennemie des trolls de Jintha'Alor.",
	["En la costa oeste de Vallefresno, las Cavernas de Brazanegra fueron un templo de Elune; hoy están hundidas y llenas de naga."] = "Sur la côte ouest d'Orneval, les profondeurs de Brassenoire étaient un temple d'Élune ; aujourd'hui, elles sont englouties et pleines de nagas.",
	["En la costa se ven ruinas de antiguos palacios élficos, medio hundidos en el mar."] = "Sur la côte, on voit les ruines d'anciens palais elfiques, à moitié englouties par la mer.",
	["En la cueva del barco hay muchos piratas: no bajen todos de golpe al muelle."] = "Dans la grotte du navire, il y a beaucoup de pirates : ne descendez pas tous d'un coup sur le quai.",
	["En la excavación de Ironband, los troggs salieron de la tierra y se quedaron con todo."] = "Au site d'excavation de Baguefer, les troggs sont sortis de terre et ont tout pris.",
	["En la ficha de cada mazmorra está el botín de cada jefe y lo que mejora tu equipo."] = "Sur la fiche de chaque donjon, il y a le butin de chaque boss et ce qui améliore ton équipement.",
	["En la granja de los Saldean, la vieja yegua Blanchy necesita avena. Es de las misiones más tiernitas de los Páramos."] = "À la ferme des Saldean, la vieille jument Blanchy a besoin d'avoine. C'est l'une des quêtes les plus tendres de la marche de l'Ouest.",
	["En la guarida de Onyxia, a los lados hay nidos con huevos: si alguien los pisa salen dragoncitos... muchísimos."] = "Dans le repaire d'Onyxia, les nids sur les côtés sont pleins d'œufs : si quelqu'un marche dessus, des dragonnets sortent... énormément.",
	["En la pelea, el juego te avisa"] = "Pendant le combat, le jeu vous prévient",
	["En la sala de la Liga de Expedicionarios de Forjaz hay biblioteca, mapas y un museo con fósiles gigantes."] = "La salle de la Ligue des explorateurs à Forgefer a une bibliothèque, des cartes et un musée aux fossiles géants.",
	["En la segunda parte mátenla a ella primero: cura mucho."] = "Dans la deuxième partie, tuez-la en premier : elle soigne beaucoup.",
	["En la subasta cuenta el precio más bajo que vio, menos la comisión (%d%%, estimada). Al desencantar usa tablas del juego clásico, también estimadas."] = "Pour l'hôtel des ventes, il compte le prix le plus bas vu, moins la commission (%d%%, estimée). Pour le désenchantement, il utilise les tables du jeu classique, estimées elles aussi.",
	["En la subasta, unos %s."] = "À l'hôtel des ventes, environ %s.",
	["En la ventana y aquí. Si no estás entre ellos, tu fila sale al final."] = "Dans la fenêtre et ici. Si vous n'en faites pas partie, votre ligne apparaît à la fin.",
	["En las Cuevas de los Lamentos, el druida Naralex soñó con devolverle el verdor a Los Baldíos, y su sueño se volvió pesadilla."] = "Dans les cavernes des Lamentations, le druide Naralex a rêvé de faire reverdir les Tarides, et son rêve est devenu cauchemar.",
	["En las Guerras Trol, los altos elfos enseñaron magia a cien humanos para vencer juntos a los Amani. Fueron los primeros magos de la humanidad."] = "Pendant les guerres des Trolls, les hauts-elfes ont enseigné la magie à cent humains pour vaincre ensemble les Amani. Ce furent les premiers mages de l'humanité.",
	["En las Mazmorras de Ventormenta los presos se amotinaron, y la guardia pide ayuda para calmar el desastre."] = "À la Prison de Hurlevent, les détenus se sont mutinés, et la garde demande de l'aide pour calmer le désastre.",
	["En las Pozas de la Visión, bajo una de las mesetas, entrenan los magos y sacerdotes Renegados."] = "Dans les Bassins de vision, sous l'un des plateaux, s'entraînent les mages et prêtres réprouvés.",
	["En las cuevas de Cuna del Invierno viven yetis peludos y gruñones."] = "Dans les grottes du Berceau-de-l'Hiver vivent des yétis poilus et grincheux.",
	["En las cuevas de Feralas viven yetis, y los ogros Gordunni tienen sus campamentos en el norte."] = "Des yétis vivent dans les grottes de Féralas, et les ogres Gordunni ont leurs camps au nord.",
	["En las cuevas nevadas de Dun Morogh viven trols de las nieves que no quieren a los enanos ni tantito."] = "Dans les grottes enneigées de Dun Morogh vivent des trolls des glaces qui n'aiment pas du tout les nains.",
	["En las dos armas"] = "Sur les deux armes",
	["En las granjas del oeste hay calderos de la Plaga que siguen esparciendo la peste; la Alianza manda aventureros a destruirlos."] = "Dans les fermes de l'ouest, des chaudrons du Fléau continuent de répandre la peste ; l'Alliance envoie des aventuriers les détruire.",
	["En las ruinas de la ciudad de Alterac hoy mandan los ogros y el Sindicato, la banda de nobles caídos del viejo reino."] = "Les ogres et le Syndicat, la bande de nobles déchus de l'ancien royaume, règnent aujourd'hui sur les ruines de la ville d'Alterac.",
	["En lo alto de la sierra hay un pico sagrado para los druidas elfos, donde anidan aves enormes."] = "En haut de la chaîne se trouve un pic sacré pour les druides elfes, où nichent d'énormes oiseaux.",
	["En lo más alto de la Montaña Roca Negra manda Nefarian, hijo de Alamuerte."] = "Nefarian, fils d'Aile-de-mort, règne au sommet du mont Rochenoire.",
