	["En tus bolsas"] = "Dans vos sacs",
	["En tus bolsas, el botín, el chat o cualquier enlace: Alt+clic abre la guía para conseguirlo o, si no hay, su ficha en la enciclopedia."] = "Dans vos sacs, le butin, la discussion ou n'importe quel lien : Alt+clic ouvre le guide pour l'obtenir ou, s'il n'y en a pas, sa fiche dans l'encyclopédie.",
	["En tus bolsas: úsala para aprenderla"] = "Dans vos sacs : utilisez-la pour l'apprendre",
	["En un aviso"] = "En alerte",
	["En un aviso y en el chat"] = "En alerte et dans la discussion",
	["En un cañón de Vallefresno, Grom mató al señor demonio Mannoroth y liberó a los orcos de su sangre maldita."] = "Dans un canyon d'Orneval, Grom a tué le seigneur démon Mannoroth et libéré les orcs de son sang maudit.",
	["En un valle de Frondavil cayeron infernales del cielo, y todavía se ven sus cráteres."] = "Des infernaux sont tombés du ciel dans une vallée de Gangrebois, et on voit encore leurs cratères.",
	["En un vuelo con escalas, una línea bajo el temporizador dice dónde es la siguiente parada y cuánto falta para llegar. Necesita el temporizador de vuelo encendido."] = "Sur un vol avec escales, une ligne sous le minuteur indique la prochaine étape et le temps restant pour y arriver. Nécessite le minuteur de vol activé.",
	["En una aldea del sur del bosque, los vecinos parecen normales de día... y de noche se convierten en worgen."] = "Dans un village du sud de la forêt, les habitants semblent normaux le jour... et la nuit, ils deviennent des worgens.",
	["En una de las mesetas, los tauren honran a los espíritus de sus ancestros."] = "Sur l'un des plateaux, les Taurens honorent les esprits de leurs ancêtres.",
	["En una instancia: la flecha vuelve al salir"] = "Dans une instance : la flèche revient à la sortie",
	["En una isla de Azshara vive el duque Hydraxis, señor del agua; su gente te ayuda a apagar las runas del Núcleo de Magma."] = "Sur une île au large d'Azshara vit le duc Hydraxis, un seigneur de l'eau ; son peuple t'aide à éteindre les runes du Cœur du Magma.",
	["En una mazmorra no hay guaridas."] = "Il n’y a pas de tanières dans un donjon.",
	["En una pestaña nueva"] = "Dans un nouvel onglet",
	["En unos segundos aparece tu build."] = "Votre build apparaît dans quelques secondes.",
