	["Esquivar"] = "Esquive",
	["Esta clase no tiene pesos de estadísticas en Alfa."] = "Cette classe n'a pas de pondérations de statistiques dans Alfa.",
	["Esta clase no tiene pesos de estadísticas."] = "Cette classe n'a pas de pondérations de statistiques.",
	["Esta explicación no saldrá más. En Combate puedes volver a encenderlas."] = "Cette explication ne s'affichera plus. Vous pouvez les réactiver dans Combat.",
	["Esta guía no tiene un paso para ti ahora"] = "Ce guide n’a pas d’étape pour toi en ce moment",
	["Esta guía no tiene un paso para ti ahora: puede que hayas omitido lo que queda o que aún no te toque. Elige otra guía o vuelve a esta más adelante."] = "Ce guide n’a pas d’étape pour toi maintenant : tu as peut-être sauté le reste ou ce n’est pas encore ton tour. Choisis un autre guide ou reviens plus tard.",
	["Esta semana llevas %s"] = "Cette semaine tu en es à %s",
	["Esta semana todavía no cazamos nada. ¿Salimos?"] = "On n’a encore rien chassé cette semaine. On y va ?",
	["Esta sesión"] = "Cette session",
	["Esta sesión, por recurso"] = "Cette session, par ressource",
	["Esta sesión: %d capturas de %d lanzamientos. Desde siempre: %d."] = "Cette session : %d prises sur %d lancers. Depuis toujours : %d.",
	["Esta sesión: %s"] = "Cette session : %s",
	["Esta subasta no permite el escaneo completo."] = "Cet hôtel des ventes ne permet pas le scan complet.",
	["Esta va de %s y %s… ¿Te la cuento?"] = "Au programme : %s et %s… Je te la raconte ?",
	["Esta va de %s y de lobos… me toca de cerca. ¿Te la cuento?"] = "Au programme : %s et des loups… ça me touche de près. Je te la raconte ?",
	["Establos"] = "Maître des écuries",
	["Estadísticas"] = "Caractéristiques",
	["Estadísticas [pesca]"] = "Statistiques",
	["Este aviso ya no mostrará texto: solo el ícono. En Combate puedes volver a encenderlos."] = "Cette alerte n'affichera plus de texte : seulement l'icône. Vous pouvez les réactiver dans Combat.",
	["Este banco no vende más espacio."] = "Cette banque ne vend plus de place.",
	["Este build pega muchísimo, pero aguanta poco: elige bien cuándo entrar."] = "Ce build frappe extrêmement fort, mais encaisse peu : choisissez bien le moment d'entrer.",
	["Este clic no hace nada. Elígele algo en Tu ratón, en la página Curación."] = "Ce clic ne fait rien. Choisissez-lui une action dans Votre souris, sur la page Soins.",
	["Este cliente no carga los mosaicos del minimapa: se ve el arte pintado."] = "Ce client ne charge pas les tuiles de la minicarte : l'art peint s'affiche.",
	["Este cliente no da el arte del mapa"] = "Ce client ne fournit pas les images de la carte",
	["Este cliente no deja compartir"] = "Ce client ne permet pas de partager",
	["Este cliente no deja compartir marcadores."] = "Ce client ne permet pas de partager des marqueurs.",
	["Este cliente no deja copiar tu mapa solo: se abrió la ventana de clic para lanzar de Blizzard para que lo armes ahí."] = "Ce client ne peut pas copier votre configuration tout seul : la fenêtre de lancement par clic de Blizzard s'est ouverte pour que vous la fassiez là.",
	["Este cliente no tiene %d de estos ajustes: no se muestran."] = "Ce client n'a pas %d de ces réglages : ils ne sont pas affichés.",
	["Este cliente no tiene el clic para lanzar de Blizzard. Tus clics funcionan en los marcos de Alfa."] = "Ce client n'a pas le lancement par clic de Blizzard. Vos clics fonctionnent sur les cadres d'Alfa.",
	["Este paso"] = "Cette étape",
	["Este paso no tiene punto en el mapa."] = "Cette étape n'a pas de point sur la carte.",
	["Este paso une el Bosque del Ocaso con el Pantano de las Penas, y casi todos lo cruzan sin detenerse."] = "Ce passage relie le bois de la Pénombre au marais des Chagrins, et presque tout le monde le traverse sans s'arrêter.",
	["Este talento no está en tu build."] = "Ce talent ne fait pas partie de votre build.",
	["Este tramo quedó vacío."] = "Ce tronçon est vide.",
	["Estilo"] = "Style",
	["Estilo de las barras"] = "Style des barres",
	["Estilo del chat"] = "Style de la discussion",
	["Estilo del mapa"] = "Style de la carte",
	["Estilo del minimapa"] = "Style de la minicarte",
	["Estilo y sonido"] = "Style et son",
	["Esto no se puede cambiar en combate. Inténtalo al terminar la pelea."] = "Impossible de changer cela en combat. Réessayez à la fin du combat.",
	["Esto no se puede vincular."] = "Impossible de créer un lien pour ceci.",
	["Estos filtros los dibuja Alfa, no el juego: quedan detrás de toda la interfaz (nunca la tapan) y también se ven con la interfaz oculta (Alt+Z), para tus capturas."] = "Ces filtres sont dessinés par Alfa, pas par le jeu : ils restent derrière toute l'interface (sans jamais la couvrir) et se voient aussi interface masquée (Alt+Z), pour vos captures.",
	["Está en combate. Prueba en un momento."] = "Il est en combat. Réessaie dans un instant.",
	["Está en el Cementerio. Pone un dolor de sombras que hace daño con el tiempo."] = "Il est dans le Cimetière. Il inflige une douleur de l'ombre qui fait des dégâts sur la durée.",
	["Está en el agua, junto a la cascada: llévenlo a tierra antes de pelear."] = "Il est dans l'eau, près de la cascade : amenez-le sur la terre ferme avant de combattre.",
	["Está en la Armería. Cuando grita, gira con su hacha y golpea a todos los que están cerca: aléjate."] = "Il est dans l'Armurerie. Quand il crie, il tournoie avec sa hache et frappe tous ceux qui sont proches : éloignez-vous.",
	["Está en la Biblioteca y llega con sus perros: mátenlos primero o usen ataques en área."] = "Il est dans la Bibliothèque et arrive avec ses chiens : tuez-les d'abord ou utilisez des attaques de zone.",
	["Está escondido en la Catedral. Pone maldiciones y se cura: interrúmpelo."] = "Il est caché dans la Cathédrale. Il lance des malédictions et se soigne : interrompez-le.",
	["Está lleno de jabaespines y sus túneles de espinos: tiren de pocos a la vez."] = "Il est plein de hurans et de tunnels d'épines : attirez-en peu à la fois.",
	["Está rodeado de goblins que trabajan: tiren a esos goblins primero, de uno en uno."] = "Il est entouré de gobelins au travail : attirez d'abord ces gobelins, un par un.",
	["Está rodeado de múrlocs: tiren a sus amigos antes que a él."] = "Il est entouré de murlocs : attirez ses amis avant lui.",
	["Estás aquí"] = "Vous êtes ici",
	["Estás con un banquero: desde su ventana depositas lo que quieras con un clic."] = "Vous êtes chez un banquier : depuis sa fenêtre, déposez ce que vous voulez en un clic.",
	["Estás dentro"] = "Vous êtes à l'intérieur",
	["Estás descansando"] = "Vous êtes au repos",
	["Estás en %s. %s Abajo tienes lo que más me preguntan de aquí."] = "Tu es dans %s. %s En dessous, ce qu’on me demande le plus ici.",
	["Estás en combate. Los talentos solo se cambian fuera de combate: termina la pelea y vuelve a intentarlo."] = "Vous êtes en combat. Les talents ne se changent que hors combat : finissez le combat et réessayez.",
	["Estás en combate: busca el equipo al terminar la pelea."] = "Vous êtes en combat : cherchez l'équipement à la fin du combat.",
	["Estás en combate: lo que cambies se aplica al salir."] = "Vous êtes en combat : vos changements s'appliqueront à la sortie du combat.",
	["Estás en combate: lo que cambies se aplica en cuanto termine."] = "Vous êtes en combat : ce que vous changez s'appliquera dès qu'il sera fini.",
	["Estás en combate: se aplica en cuanto termine."] = "Vous êtes en combat : cela s'appliquera dès qu'il sera fini.",
	["Estás en combate: tus cambios se aplican en cuanto termine."] = "Vous êtes en combat : vos changements s'appliqueront dès qu'il sera fini.",
	["Estás en grupo y otro aguanta al enemigo: apuñálalo por la espalda."] = "Vous êtes en groupe et un autre retient l'ennemi : utilisez Attaque sournoise.",
	["Estás en grupo y otro aguanta al enemigo: trízalo por la espalda."] = "Vous êtes en groupe et un autre retient l'ennemi : lacérez-le avec Lambeau par derrière.",
	["Estás en la %s"] = "Tu es dans la %s",
	["Estás en la ciudad y hay habilidades por entrenar (%d). ¡Aprovecha!"] = "Tu es en ville et il y a des techniques à apprendre (%d). Profites-en !",
	["Estás en sigilo: Premeditación te da puntos de combo."] = "Vous êtes camouflé : Préméditation vous donne des points de combo.",
	["Estás en sigilo: abre con Emboscada por la espalda."] = "Vous êtes camouflé : ouvrez avec Embuscade dans le dos.",
	["Estás en sigilo: aturde al enemigo al abrir."] = "Vous êtes camouflé : étourdissez l'ennemi à l'ouverture.",
	["Estás en una instancia: la flecha vuelve al salir."] = "Vous êtes dans une instance : la flèche revient à la sortie.",
	["Evento"] = "Événement",
	["Evita golpes críticos y aplastantes: lo más importante para un tanque."] = "Évite les coups critiques et écrasants : le plus important pour un tank.",
	["Evitar misiones de grupo"] = "Éviter les quêtes de groupe",
	["Experiencia"] = "Expérience",
	["Experiencia y reputación"] = "Expérience et réputation",
	["Experto"] = "Expert",
	["Explicaciones"] = "Explications",
	["Explicar por qué"] = "Expliquer pourquoi",
	["Explicar por qué, unas pocas veces"] = "Expliquer pourquoi, quelques fois",
	["Explorar todo el mapa del mundo con un personaje es un reto del Legado. ¡Excusa perfecta para pasear conmigo!"] = "Explorer toute la carte du monde avec un personnage est un défi de l'Héritage. L'excuse parfaite pour une balade avec moi !",
	["Fallas menos golpes, sobre todo contra monstruos de nivel más alto que el tuyo."] = "Vous ratez moins de coups, surtout contre les monstres de niveau supérieur au vôtre.",
	["Fallas menos golpes."] = "Vous ratez moins de coups.",
	["Fallas menos: con dos armas fallas mucho sin esto."] = "Vous ratez moins : avec deux armes, vous ratez beaucoup sans cela.",
