	["Falta algo."] = "Il manque quelque chose.",
	["Falta el final del texto: cópialo completo."] = "La fin du texte manque : copiez-le en entier.",
	["Falta el paquete de datos de Alfa (Alfa_Codex): vuelve a instalar Alfa completo."] = "Le pack de données d'Alfa (Alfa_Codex) est manquant : réinstallez Alfa en entier.",
	["Falta en un arma"] = "Manque sur une arme",
