	["Ir por el camino es más seguro que cortar por en medio: los caminos tienen menos enemigos."] = "Suivre la route est plus sûr que couper à travers : les routes ont moins d'ennemis.",
	["Ir por él"] = "Aller le chercher",
	["Ira al romper un miedo: los rivales te asustan mucho."] = "De la rage en brisant une peur : les adversaires vous apeurent souvent.",
	["Ira aunque el rival huya o te frene."] = "De la rage même si l'adversaire fuit ou vous ralentit.",
	["Ira constante en peleas largas contra jefes."] = "Une rage constante dans les longs combats de boss.",
	["Ira constante."] = "Rage constante.",
	["Ira constante: nunca te quedas sin poder usar habilidades."] = "Rage constante : vous ne manquez jamais de quoi utiliser vos techniques.",
