	["Izquierdo"] = "Gauche",
	["Jaina Valiente fue alumna de Antonidas antes de fundar Theramore."] = "Jaina Portvaillant était l'élève d'Antonidas avant de fonder Theramore.",
	["JcJ"] = "JcJ",
	["JcJ (12): rangos de honor 3, 7, 10, 13 y 14; exaltado con las 4 facciones de los campos de batalla; las semanas 4, 7 y 10 del viaje de temporada Campo de Honor."] = "JcJ (12) : rangs d'honneur 3, 7, 10, 13 et 14 ; exalté auprès des 4 factions des champs de bataille ; les semaines 4, 7 et 10 du parcours de saison Champ d'honneur.",
	["Jefe"] = "Boss",
	["Jefe %d por descubrir"] = "Boss %d à découvrir",
	["Jefe final"] = "Boss final",
	["Jefes"] = "Boss",
	["Jefes vencidos"] = "Boss vaincus",
	["Jefes vencidos, mazmorras hechas y botín anotado de este personaje. No toca tus ajustes."] = "Les boss vaincus, les donjons terminés et le butin noté de ce personnage. Vos réglages ne changent pas.",
	["Jefes, botín y la entrada de cada mazmorra y banda."] = "Les boss, le butin et l'entrée de chaque donjon et raid.",
	["Juega con cada personaje una vez y Alfa recordará sus bolsas y su banco."] = "Jouez une fois chaque personnage et Alfa se souviendra de ses sacs et de sa banque.",
	["Juega siempre en actitud defensiva con escudo."] = "Jouez toujours en posture défensive avec un bouclier.",
	["Juguetes y consumibles de pesca"] = "Jouets et consommables de pêche",
	["Junta %d de %s"] = "Récoltez %d %s",
	["Junta 100 capturas."] = "Faites 100 prises.",
	["Junta 1000 capturas."] = "Faites 1000 prises.",
	["Junta 500 capturas."] = "Faites 500 prises.",
	["Junta dos monstruos y usa Golpes de barrido: así subes más rápido."] = "Attirez deux monstres et utilisez Attaques circulaires : c'est ainsi que vous montez plus vite.",
	["Junta dos o tres monstruos, usa Atronar y Revancha: subes seguro y sin descansar."] = "Attirez deux ou trois monstres, utilisez Coup de tonnerre et Vengeance : vous montez en sécurité et sans vous reposer.",
	["Junta lo gris y lo blanco para vender: suma más de lo que parece."] = "Ramasse le gris et le blanc pour le vendre : ça rapporte plus qu'on ne croit.",
	["Junta los montones y acomoda tus objetos con un clic."] = "Regroupe les piles et range vos objets en un clic.",
	["Junta los montones y acomoda tus objetos. No funciona en combate."] = "Regroupe les piles et range vos objets. Impossible en combat.",
	["Junta materiales de tu profesión donde más hay."] = "Récoltez les matériaux de votre métier là où il y en a le plus.",
	["Junta materiales de tu profesión, con unas misiones de XP en medio."] = "Récoltez les matériaux de votre métier, avec quelques quêtes d'XP en chemin.",
	["Junta misiones de la misma zona: haces varias en un solo viaje."] = "Regroupe les quêtes d'une même zone : tu en fais plusieurs en un seul voyage.",
	["Junta varios monstruos: tus golpes sagrados alcanzan a todos."] = "Attirez plusieurs monstres : vos frappes sacrées les touchent tous.",
	["Juntando todo lo del juego. Es solo la primera vez que la abres."] = "Rassemblement de tout le contenu du jeu. Seulement la première fois que vous l'ouvrez.",
	["Juntar %s"] = "Réunir %s",
	["Juntar los materiales de mi profesión"] = "Récolter les matériaux de mon métier",
	["Juntar materiales para vender"] = "Récolter des matériaux à vendre",
	["Juntar nodos cercanos al alejar"] = "Regrouper les nœuds proches en dézoomant",
	["Juntar oro"] = "Réunir de l'or",
	["Junto a la lupa del mapa del juego: las capas, el modo limpio y «Mapa de Alfa» para cambiar al de Alfa."] = "À côté de la loupe de la carte du jeu : les calques, le mode épuré et « Carte d'Alfa » pour passer à celle d'Alfa.",
	["Junto a tu guía hay un botón para buscar lo que tienes cerca: vuelo, banco, subasta, reparar, comerciantes y entrenadores."] = "À côté de votre guide, un bouton cherche ce qui est près de vous : vol, banque, enchères, réparation, marchands et maîtres.",
	["Kael'thas fue miembro del Kirin Tor de Dalaran antes de guiar a los elfos de sangre."] = "Kael'thas était membre du Kirin Tor de Dalaran avant de guider les elfes de sang.",
	["Karazhan, la torre de Medivh, el último Guardián, se levanta sobre un cruce de líneas de magia natural."] = "Karazhan, la tour de Medivh, le dernier Gardien, se dresse sur un croisement de lignes telluriques.",
	["Kargath, el campamento de la Horda, lleva el nombre de un viejo caudillo orco del clan Mano Destrozada."] = "Kargath, le campement de la Horde, porte le nom d'un vieux chef orc du clan de la Main-Brisée.",
	["Kel'Thuzad era un archimago de Dalaran. Lo expulsaron por estudiar nigromancia y acabó al servicio del Rey Exánime."] = "Kel'Thuzad était un archimage de Dalaran. Il a été chassé pour avoir étudié la nécromancie et a fini au service du roi-liche.",
	["Kel'Thuzad tiene un gato, el señor Bigglesworth, que lo acompaña en Naxxramas. ¡Ni se te ocurra hacerle daño!"] = "Kel'Thuzad a un chat, M. Bigglesworth, qui lui tient compagnie à Naxxramas. Ne va surtout pas lui faire de mal !",
	["Khadgar fue el aprendiz de Medivh. Al pelear contra su maestro poseído envejeció de golpe y se quedó con el pelo blanco."] = "Khadgar était l'apprenti de Medivh. En combattant son maître possédé, il a vieilli d'un coup et ses cheveux sont devenus blancs.",
	["Khaz Modan es la tierra de los enanos, desde las nieves de Dun Morogh hasta los valles de Loch Modan."] = "Khaz Modan est la terre des nains, des neiges de Dun Morogh aux vallées du Loch Modan.",
	["Kil'jaeden encerró el alma de Ner'zhul en un bloque de hielo y lo arrojó a Rasganorte: así nació el Rey Exánime."] = "Kil'jaeden a enfermé l'âme de Ner'zhul dans un bloc de glace et l'a précipité en Norfendre : c'est ainsi qu'est né le roi-liche.",
	["Kil'jaeden engañó a Ner'zhul, el chamán más sabio de Draenor, y su aprendiz Gul'dan terminó de entregar a los orcos a la Legión."] = "Kil'jaeden a trompé Ner'zhul, le plus sage chaman de Draenor, et son apprenti Gul'dan a fini de livrer les orcs à la Légion.",
	["Korialstrasz, el consorte de Alexstrasza, anduvo entre los mortales como Krasus, un mago del consejo de Dalaran."] = "Korialstrasz, le consort d'Alexstrasza, a vécu parmi les mortels sous le nom de Krasus, un mage du conseil de Dalaran.",
	["Kul Tiras es un reino isleño de marineros. Su gran almirante, Daelin Valiente, era el padre de Jaina."] = "Kul Tiras est un royaume insulaire de marins. Son grand amiral, Daelin Portvaillant, était le père de Jaina.",
	["La %s también está en el menú del juego."] = "Le réglage %s est aussi dans le menu du jeu.",
	["La Abadía de Villanorte es de las más antiguas del reino; ahí empiezan su camino muchos aventureros humanos."] = "L'abbaye de Comté-du-Nord est l'une des plus anciennes du royaume ; beaucoup d'aventuriers humains y commencent leur chemin.",
	["La Alianza nació en la Segunda Guerra, cuando los reinos humanos, los enanos y los altos elfos se unieron contra la Horda."] = "L'Alliance est née pendant la Deuxième Guerre, quand les royaumes humains, les nains et les hauts-elfes se sont unis contre la Horde.",
	["La B, Mayús+B, la tecla de cada bolsa y los comerciantes abren la ventana de Alfa. Apágalo para volver a las del juego."] = "B, Maj+B, la touche de chaque sac et les marchands ouvrent la fenêtre d'Alfa. Désactivez-le pour revenir à ceux du jeu.",
	["La Capilla de la Esperanza de la Luz resistió a la Plaga en una batalla legendaria; hoy es el gran refugio del Alba Argenta."] = "La chapelle de l'Espoir-de-Lumière a résisté au Fléau lors d'une bataille légendaire ; c'est aujourd'hui le grand refuge de l'Aube d'argent.",
	["La Catedral de la Luz es el corazón de la fe en Ventormenta; sus sacerdotes atienden a toda la Alianza."] = "La cathédrale de la Lumière est le cœur de la foi à Hurlevent ; ses prêtres servent toute l'Alliance.",
	["La Cresta de la Llama es el puesto de la Horda en las estepas, en lo alto de las rocas."] = "Crête-de-flammes est l'avant-poste de la Horde dans les steppes, en haut des rochers.",
	["La Cruzada Escarlata nació del dolor de Lordaeron tras la plaga, pero su odio la volvió tan cruel como lo que combate."] = "La Croisade écarlate est née du chagrin de Lordaeron après la peste, mais sa haine l'a rendue aussi cruelle que ce qu'elle combat.",
	["La Cruzada Escarlata tiene aquí su monasterio. Para ellos todo no-muerto debe arder, también los Renegados."] = "La Croisade écarlate a ici son monastère. Pour eux, tout mort-vivant doit brûler, Réprouvés compris.",
	["La Cuenca de Arathi, el campo de batalla, está en estas tierras: se pelea por la granja, la mina, el aserradero, los establos y la herrería."] = "Le bassin Arathi, le champ de bataille, se trouve sur ces terres : on s'y bat pour la ferme, la mine, la scierie, les écuries et la forge.",
	["La Feria de la Luna Negra tiene su propia reputación, y se sube con sus vales y sus encargos."] = "La Foire de Sombrelune a sa propre réputation, qui monte avec ses tickets et ses commandes.",
	["La Fortaleza de Grommash, en Orgrimmar, lleva el nombre de Grom Grito Infernal, el héroe que liberó a los orcos de la sangre demoníaca."] = "Le fort Grommash, à Orgrimmar, porte le nom de Grom Hurlenfer, le héros qui a libéré les orcs du sang démoniaque.",
	["La Fuente del Sol, el corazón de Quel'Thalas, nació de un frasco de agua del Pozo de la Eternidad que los altos elfos se llevaron."] = "Le Puits de soleil, cœur de Quel'Thalas, est né d'une fiole d'eau du Puits d'éternité que les hauts-elfes ont emportée.",
	["La Garganta de Fuego quedó así por culpa del Hierro Negro: su hechicero-thane Thaurissan invocó a Ragnaros y la tierra se incendió."] = "La gorge des Vents brûlants doit son état aux Sombrefer : leur thane-sorcier Thaurissan a invoqué Ragnaros et la terre s'est embrasée.",
	["La Gran Forja nunca se apaga: es el corazón de Forjaz y el orgullo de tu gente."] = "La Grande Forge ne s'éteint jamais : c'est le cœur de Forgefer et la fierté de ton peuple.",
	["La Gran Forja, en el corazón de Forjaz, nunca se apaga."] = "La Grande Forge, au cœur de Forgefer, ne s'éteint jamais.",
	["La Guardia Nocturna es la milicia de Villa Oscura: protege el pueblo de lobos, no-muertos y worgen."] = "Le Guet de nuit est la milice de Sombre-Comté : il protège le village des loups, des morts-vivants et des worgens.",
	["La Guerra de los Ancestros fue la primera invasión de la Legión Ardiente a Azeroth, hace unos diez mil años."] = "La guerre des Anciens fut la première invasion d'Azeroth par la Légion ardente, il y a environ dix mille ans.",
	["La Hermandad del Torio son enanos Hierro Negro que se separaron de su clan. Son maestros herreros y negocian con quien los respete."] = "La Confrérie du thorium, ce sont des nains Sombrefer qui ont quitté leur clan. Ce sont des maîtres forgerons qui traitent avec quiconque les respecte.",
	["La Hermandad del Torio, en La Garganta de Fuego, enseña planos que muchos herreros sueñan."] = "La Confrérie du thorium, dans la gorge des Vents brûlants, enseigne des plans dont rêvent bien des forgerons.",
	["La Horda arrasó Ventormenta en la Primera Guerra. Los albañiles que la reconstruyeron no recibieron su pago, y de ese enojo nació la Hermandad Defias."] = "La Horde a rasé Hurlevent pendant la Première Guerre. Les maçons qui l'ont reconstruite n'ont jamais été payés, et de cette colère est née la Confrérie défias.",
	["La Horda tiene su propio pueblo al norte del marjal, para vigilar Theramore de cerca."] = "La Horde a son propre village au nord du marécage, pour surveiller Theramore de près.",
	["La Horda tiene una aldea en la costa de Desolace, y la Alianza un campamento en las montañas del norte."] = "La Horde a un village sur la côte de Désolace, et l'Alliance un campement dans les montagnes du nord.",
	["La Jauría"] = "La Jauría",
	["La Jauría en el mapa"] = "La Jauría sur la carte",
	["La Jauría: estado"] = "La Jauría : état",
	["La Jauría: tu manada en el mapa, Seguir y el clan (/alfa manada ayuda)"] = "La Jauría : votre meute sur la carte, Suivre et le clan (/alfa manada ayuda)",
	["La Jauría: tus comandos"] = "La Jauría : vos commandes",
	["La Legión Ardiente es el ejército de demonios de Sargeras, un titán caído que quiere quemar toda la creación."] = "La Légion ardente est l'armée démoniaque de Sargeras, un titan déchu qui veut brûler toute la création.",
	["La Liga de Arathor y los Rapiñadores se pelean la Cuenca de Arathi; las Centinelas Ala de Plata y la Escolta Grito de Guerra, la Garganta Grito de Guerra."] = "La Ligue d'Arathor et les Profanateurs se disputent le bassin Arathi ; les Sentinelles d'Aile-argent et les Voltigeurs Chanteguerre, le goulet des Chanteguerre.",
	["La Liga de Expedicionarios, los arqueólogos de Forjaz, busca por todo el mundo las ruinas que cuenten el origen de los enanos."] = "La Ligue des explorateurs, les archéologues de Forgefer, parcourt le monde à la recherche des ruines qui racontent l'origine des nains.",
	["La Luz para los humanos y enanos, Elune para los elfos de la noche y las sombras para muchos Renegados: cada sacerdote sirve a algo distinto."] = "La Lumière pour les humains et les nains, Élune pour les elfes de la nuit et l'ombre pour bien des Réprouvés : chaque prêtre sert quelque chose de différent.",
	["La Mano de Plata la fundó el arzobispo Alonsus Faol, y Uther fue su primer paladín."] = "La Main d'argent a été fondée par l'archevêque Alonsus Faol, et Uther en fut le premier paladin.",
	["La Mano de Plata, la orden de paladines, la fundó el arzobispo Alonsus Faol, y Uther fue el primero de sus caballeros."] = "La Main d'argent, l'ordre des paladins, a été fondée par l'archevêque Alonsus Faol, et Uther fut le premier de ses chevaliers.",
	["La Masacre fue Eldre'Thalas, una ciudad de los elfos Altonato de antes de la Gran División."] = "Hache-tripes était Eldre'Thalas, une cité des elfes bien-nés d'avant la Fracture.",
	["La Milicia Popular de la Colina del Centinela la formaron los propios granjeros cuando Ventormenta dejó de mandar soldados."] = "La Milice du peuple de la colline des Sentinelles a été formée par les fermiers eux-mêmes quand Hurlevent a cessé d'envoyer des soldats.",
	["La Montaña Roca Negra se alza entre esta garganta y las Estepas Ardientes. Dentro viven los Hierro Negro, Ragnaros y los dragones negros."] = "Le mont Rochenoire se dresse entre cette gorge et les Steppes ardentes. À l'intérieur vivent les Sombrefer, Ragnaros et les dragons noirs.",
	["La Muralla de Thoradin separa Arathi de las Laderas de Trabalomas; lleva el nombre del rey que unió a los humanos."] = "Le mur de Thoradin sépare Arathi des contreforts de Hautebrande ; il porte le nom du roi qui a uni les humains.",
	["La Orden de Tirisfal, los magos secretos que elegían al Guardián de Azeroth, tomó su nombre de estos claros. Medivh fue el último Guardián."] = "L'ordre de Tirisfal, les mages secrets qui choisissaient le Gardien d'Azeroth, a pris son nom de ces clairières. Medivh fut le dernier Gardien.",
	["La Plaga es el ejército no-muerto del Rey Exánime. Kel'Thuzad la extendió por Lordaeron con grano infectado."] = "Le Fléau est l'armée morte-vivante du roi-liche. Kel'Thuzad l'a répandu dans tout Lordaeron avec du grain infecté.",
	["La Polimorfia convierte al enemigo en oveja. Yo me portaría muy bien con esa oveja, palabra de loba."] = "La Métamorphose change l'ennemi en mouton. Je serais très sage avec ce mouton, parole de louve.",
	["La Segadora de arcanita es una de las armas más famosas que puede forjar un herrero."] = "La Faucheuse d'arcanite est l'une des armes les plus célèbres qu'un forgeron puisse forger.",
	["La Sima Ígnea está bajo Orgrimmar: ahí se esconden brujos de un culto junto con troggs."] = "Le gouffre de Ragefeu se trouve sous Orgrimmar : des démonistes d'un culte s'y cachent avec des troggs.",
	["La Sociedad Real de Boticarios trabaja en Entrañas en una plaga nueva. Mejor no preguntes para quién."] = "La Société royale des apothicaires travaille à Fossoyeuse sur une nouvelle peste. Mieux vaut ne pas demander pour qui.",
	["La Sociedad Real de Boticarios trabaja en secreto en una plaga nueva... y no precisamente para los humanos solamente."] = "La Société royale des apothicaires travaille en secret sur une nouvelle peste... et pas seulement pour les humains.",
	["La Tercera Guerra empezó con la plaga del grano en Lordaeron y terminó en Hyjal con la caída de Archimonde."] = "La Troisième Guerre a commencé avec la peste du grain à Lordaeron et s'est terminée sur Hyjal avec la chute d'Archimonde.",
	["La Torre de Azora, en el este de Elwynn, es la casa de Theocritus, un mago al servicio del reino."] = "La tour d'Azora, à l'est d'Elwynn, est la demeure de Theocritus, un mage au service du royaume.",
	["La aldea Sen'jin, en la costa de Durotar, lleva el nombre del líder que dio su vida por su pueblo."] = "Le village de Sen'jin, sur la côte de Durotar, porte le nom du chef qui a donné sa vie pour son peuple.",
	["La ayuda de rotación está apagada"] = "L'aide à la rotation est désactivée",
	["La barra con el nombre de la zona y la hora toma los colores y la letra del estilo. Los botones de rastreo, calendario y correo quedan como siempre."] = "La barre avec le nom de la zone et l'heure prend les couleurs et la police du style. Les boutons de suivi, calendrier et courrier restent comme d'habitude.",
	["La barra de acción, las barras extra, la de experiencia, el menú y las bolsas toman el estilo que elijas. Solo cambia su aspecto, fuera de combate; al apagarlo vuelven las del juego."] = "La barre d'action, les barres supplémentaires, celle d'expérience, le menu et les sacs prennent le style choisi. Seul leur aspect change, hors combat ; désactivé, celles du jeu reviennent.",
	["La barra de pesca"] = "La barre de pêche",
	["La barra de tu vuelo con sus paradas sale siempre al despegar."] = "Votre barre de vol avec ses escales s'affiche toujours au décollage.",
	["La barra de vida con el color de la clase de cada uno. Apagado: barra verde y el nombre con su color."] = "La barre de vie à la couleur de la classe de chacun. Désactivé : barre verte et nom à sa couleur.",
	["La base incluida trae %s lugares en %d zonas. Tú descubriste %s."] = "La base incluse contient %s endroits dans %d zones. Vous en avez découvert %s.",
	["La bienvenida con las novedades de esta versión."] = "La bienvenue avec les nouveautés de cette version.",
	["La bienvenida ocupa toda la pantalla, con el juego oscurecido detrás."] = "L'accueil occupe tout l'écran, avec le jeu assombri derrière.",
	["La básica la venden los instructores y los vendedores de suministros de pesca."] = "La basique est vendue par les maîtres et les vendeurs de fournitures de pêche.",
	["La búsqueda de lugares cercanos no está disponible."] = "La recherche de lieux proches n'est pas disponible.",
	["La cadena de los Defias te lleva de Villadorada a los Páramos de Poniente y termina en las Minas de la Muerte, frente a VanCleef."] = "La chaîne des Défias te mène de Comté-de-l'Or à la marche de l'Ouest et se termine aux Mortemines, face à VanCleef.",
	["La cadena no trae talentos válidos."] = "La chaîne ne contient aucun talent valide.",
	["La caja donde escribes toma el estilo, con el borde de acento mientras escribes. En Clásico WoW queda la del juego."] = "Le champ où vous écrivez prend le style, avec la bordure d'accent pendant la saisie. Avec WoW classique, celui du jeu reste.",
	["La cambiaste fuera de Alfa (menú del juego o consola)."] = "Vous l'avez changé hors d'Alfa (menu du jeu ou console).",
	["La capa de escamas de Onyxia protege del aliento de Nefarian, y en su banda la piden todos."] = "La Cape en écailles d'Onyxia protège du souffle de Nefarian, et tout le monde en a besoin dans son raid.",
	["La cerveza es casi sagrada para tu gente: en Kharanos está la destilería Cebatruenos."] = "La bière est presque sacrée pour ton peuple : la distillerie Tonnebière se trouve à Kharanos.",
	["La cola está vacía."] = "La file est vide.",
	["La configuración es más visual: tres tarjetas para decidir cuánto te ayuda Alfa y tus extras en un mosaico."] = "La configuration est plus visuelle : trois cartes pour décider combien Alfa t’aide, et tes extras en mosaïque.",
	["La cura de ese clic pasa al botón central."] = "Le soin de ce clic passe au bouton du milieu.",
	["La cámara no salta hacia ti por cada árbol o poste entre ella y tu personaje."] = "La caméra ne saute pas vers vous à chaque arbre ou poteau entre elle et votre personnage.",
	["La cámara se mece un poco con tus pasos."] = "La caméra se balance un peu avec vos pas.",
	["La cámara se queda sobre el agua en lugar de meterse."] = "La caméra reste au-dessus de l'eau au lieu de plonger.",
	["La cámara te sigue"] = "La caméra vous suit",
	["La de ahora pasa a tus sesiones anteriores."] = "La session actuelle passe dans vos sessions précédentes.",
	["La de ahora pasa a tus sesiones anteriores. Tu diario y tus logros no cambian."] = "La session actuelle passe dans vos sessions précédentes. Votre journal et vos hauts faits ne changent pas.",
	["La de tu clase mientras subes: cambia sola cuando pongas talentos."] = "Celle de votre classe pendant la progression : elle change toute seule quand vous placez des talents.",
	["La derecha"] = "La droite",
	["La dirección del texto sobre tu personaje."] = "La direction du texte au-dessus de votre personnage.",
	["La empieza un objeto"] = "Commencée par un objet",
	["La enciclopedia de La Jauría"] = "L'encyclopédie de La Jauría",
	["La enciclopedia no puede abrir todavía"] = "L'encyclopédie ne peut pas encore s'ouvrir",
	["La entrada de %s"] = "L'entrée de %s",
	["La entrada de cada mazmorra en el minimapa, en verde las que ya hiciste. El mapa del mundo ya las marca con «Entradas de mazmorras»."] = "L'entrée de chaque donjon sur la minicarte, en vert ceux que vous avez déjà faits. La carte du monde les marque déjà avec « Entrées de donjon ».",
	["La familia Barov le entregó su castillo de Caer Darrow al Culto a cambio de vida eterna. Así nació Scholomance, y así les fue."] = "La famille Barov a livré son château de Caer Darrow au Culte en échange de la vie éternelle. Ainsi est née Scholomance, et tu vois comment ça a tourné pour eux.",
	["La flecha no está disponible ahora."] = "La flèche n'est pas disponible pour le moment.",
	["La flecha que te guía"] = "La flèche qui vous guide",
	["La flecha se mueve con su rastro y se detiene al llegar."] = "La flèche bouge avec sa piste et s'arrête à votre arrivée.",
	["La flecha sigue caminos por el suelo alrededor de acantilados, agua y muros, con los mapas para caminar de Alfa. Apagado: apunta directo a cada parada."] = "La flèche suit les chemins au sol en contournant falaises, eau et murs, sur les cartes de marche d'Alfa. Désactivé : elle pointe tout droit vers chaque arrêt.",
	["La flecha te lleva a %s."] = "La flèche vous mène à %s.",
	["La flecha te lleva a este paso, no al de ahora."] = "La flèche vous mène à cette étape, pas à l'étape actuelle.",
	["La flecha te lleva a su entrada."] = "La flèche vous mène à son entrée.",
	["La flecha te lleva aquí."] = "La flèche vous mène ici.",
	["La flecha te lleva de un lugar al siguiente."] = "La flèche vous mène d'un endroit au suivant.",
	["La flecha tomó otro destino: dejaste de seguir a %s."] = "La flèche a pris une autre destination : vous ne suivez plus %s.",
	["La flecha usa vuelos y tu piedra de hogar cuando conviene."] = "La flèche utilise les vols et votre pierre de foyer quand c'est rentable.",
	["La flecha y el camino"] = "La flèche et le chemin",
	["La flecha ya no sigue tu ruta de farmeo."] = "La flèche ne suit plus votre itinéraire de farm.",
	["La fuerza se cambia en la ventana, en Filtros."] = "L'intensité se règle dans la fenêtre, dans Filtres.",
	["La guarida de Onyxia está en este marjal. Onyxia, hija de Alamuerte, se hace pasar por una noble humana en Ventormenta."] = "Le repaire d'Onyxia se trouve dans ce marécage. Onyxia, fille d'Aile-de-mort, se fait passer pour une noble humaine à Hurlevent.",
	["La guía de Pesca te dice a qué agua ir según tu nivel de pesca, y la flecha te lleva."] = "Le guide de Pêche te dit où pêcher selon ta compétence, et la flèche t’y emmène.",
	["La guía en el minimapa"] = "Le guide sur la minicarte",
	["La guía que mejor te queda por tu nivel y donde estás."] = "Le guide qui vous convient le mieux selon votre niveau et l'endroit où vous êtes.",
	["La guía que sigues, tu paso de ahora y todo lo de las guías a un clic."] = "Le guide que vous suivez, votre étape actuelle et tout ce qui concerne les guides, en un clic.",
	["La guía te lleva a entrenar en %d pasos."] = "Le guide vous emmène vous entraîner en %d étapes.",
	["La guía te lleva a quien recibe cada una."] = "Le guide vous mène à celui qui reçoit chacune.",
	["La haces de paso: abre %s."] = "Vous la faites en chemin : elle ouvre %s.",
	["La haré"] = "Je la ferai",
	["La historia"] = "L'histoire",
	["La historia se guarda cuando el juego te muestra la misión."] = "L'histoire est gardée quand le jeu vous montre la quête.",
	["La lengua de la Alianza es el común y la de la Horda, el orco. Por eso lo que le dices al otro bando le llega como palabras raras."] = "L'Alliance parle le commun et la Horde l'orc. C'est pour ça que ce que tu dis à l'autre faction lui arrive en charabia.",
	["La letra del aspecto (Inter en el de Alfa, Fira Sans en Halo, la del juego en los demás) o la que elijas."] = "La police de l'habillage (Inter pour celui d'Alfa, Fira Sans pour Halo, celle du jeu pour les autres) ou celle de votre choix.",
	["La lista está apagada: enciende «Tu lista de sonidos» en Comodidades (/alfa comodidades)."] = "La liste est désactivée : activez « Votre liste de sons » dans Confort de jeu (/alfa comodidades).",
	["La lista por nivel y tu progreso."] = "La liste par niveau et votre progression.",
	["La lupa de la cabecera del rastreador abre el menú. También: /alfa cerca o tu tecla."] = "La loupe dans l'en-tête du suivi ouvre le menu. Aussi : /alfa cerca ou votre touche.",
	["La línea de tiempo de Blizzard dice qué ataque viene y cuándo, y los mensajes grandes, lo peligroso. Alfa no inventa avisos: los prendes y ajustas en Ajustes."] = "La chronologie de Blizzard indique quelle attaque arrive et quand, et les grands messages, ce qui est dangereux. Alfa n'invente pas d'alertes : vous les activez et les réglez dans les Réglages.",
	["La línea de tu personaje ya no se corta: si no cabe, quita partes y nunca tu nombre ni tu nivel."] = "La ligne de votre personnage n'est plus coupée : si elle ne tient pas, des parties sautent, mais jamais votre nom ni votre niveau.",
	["La línea del camino también en el minimapa."] = "La ligne d'itinéraire aussi sur la minicarte.",
	["La manada a la vista"] = "La meute en vue",
	["La manada aúlla contigo."] = "La meute hurle avec vous.",
	["La manada caza junta"] = "La meute chasse ensemble",
	["La manada crece"] = "La meute s'agrandit",
	["La manada desembarca en %s"] = "La meute débarque dans %s",
	["La manada es fuerte porque cada lobo lo es. Y tú lo eres."] = "La meute est forte parce que chaque loup l'est. Et toi, tu l'es.",
	["La manada no te ve en el mapa"] = "La meute ne vous voit pas sur la carte",
	["La manada no ve a tu personaje en el mapa."] = "La meute ne voit pas votre personnage sur la carte.",
	["La manada te ve en el mapa"] = "La meute vous voit sur la carte",
	["La manada te ve en el mapa: %s"] = "La meute vous voit sur la carte : %s",
	["La manada viaja"] = "La meute voyage",
	["La manada ya no ve a tu personaje en el mapa."] = "La meute ne voit plus votre personnage sur la carte.",
	["La manada ya ve a tu personaje en el mapa del juego."] = "La meute voit maintenant votre personnage sur la carte du jeu.",
	["La manada ya ve a tu personaje en el mapa del juego. Lo cambias cuando quieras en /alfa manada."] = "La meute voit maintenant votre personnage sur la carte du jeu. Changez-le quand vous voulez avec /alfa manada.",
	["La mazmorra"] = "Le donjon",
	["La mazmorra para mi nivel"] = "Le donjon pour mon niveau",
	["La mazmorra para tu nivel, sus jefes, botín, misiones y consejos."] = "Le donjon pour votre niveau, ses boss, son butin, ses quêtes et ses conseils.",
	["La mazmorra para tu nivel, sus misiones y cómo llegar."] = "Le donjon pour votre niveau, ses quêtes et comment y aller.",
	["La mazmorra para tu nivel; con un nombre, esa mazmorra (también: progreso, ajustes)"] = "Le donjon pour votre niveau ; avec un nom, ce donjon (aussi : progreso, ajustes)",
	["La mezcla de texturas del terreno."] = "Le mélange des textures du terrain.",
	["La misión"] = "La quête",
	["La montura"] = "La monture",
	["La niebla con cuerpo de valles, pantanos y amaneceres."] = "Le brouillard épais des vallées, des marais et des aurores.",
	["La pantalla se pone negra uno o dos segundos mientras el juego vuelve a arrancar los gráficos. No sales del juego ni pierdes nada."] = "L'écran devient noir une ou deux secondes pendant que le jeu redémarre ses graphismes. Vous ne quittez pas le jeu et ne perdez rien.",
	["La pesca de Alfa está apagada"] = "La pêche d'Alfa est désactivée",
	["La pesca se rehízo: una sola tecla para equiparte, lanzar y recoger, con diario, logros y una guía de 1 a 300."] = "La pêche a été refaite : une seule touche pour s'équiper, lancer et ramasser, avec journal, hauts faits et un guide de 1 à 300.",
	["La piel verde de los orcos es una huella de la magia vil que usaron sus brujos en Draenor."] = "La peau verte des orcs est une marque de la magie gangrenée que leurs démonistes ont utilisée sur Draenor.",
	["La precisión es lo más importante: con dos armas fallas mucho sin ella."] = "Le toucher est le plus important : avec deux armes, vous ratez beaucoup sans lui.",
	["La primera vez: %s%s."] = "La première fois : %s%s.",
	["La princesa Moira, hija de Magni Barbabronce, vive en las Profundidades de Roca Negra como esposa del emperador Thaurissan."] = "La princesse Moira, fille de Magni Barbe-de-bronze, vit dans les profondeurs de Rochenoire en tant qu'épouse de l'empereur Thaurissan.",
	["La profesión"] = "Le métier",
	["La página de Bolsas; «abrir» abre tus bolsas y «banco» tu banco"] = "La page Sacs ; « open » ouvre vos sacs et « bank » votre banque",
	["La que te toca, con sus misiones y su botín."] = "Celui qui vous convient, avec ses quêtes et son butin.",
	["La recoges ahora"] = "Vous la récupérez maintenant",
	["La recomendada para ti y todas las demás"] = "Celui recommandé pour vous et tous les autres",
	["La recomendada para ti y todas las demás."] = "Celui recommandé pour vous et tous les autres.",
	["La ruta más rápida desde tu nivel, misión por misión."] = "L'itinéraire le plus rapide depuis votre niveau, quête par quête.",
	["La ruta no trae tramos."] = "L'itinéraire ne contient aucun tronçon.",
	["La ruta te lleva a %s. La flecha está apagada: enciéndela en Ajustes > Guía para verla."] = "L'itinéraire vous mène à %s. La flèche est désactivée : activez-la dans Réglages > Guide pour la voir.",
	["La ruta ya no se salta para siempre una misión que todavía no puede revisar."] = "L'itinéraire ne saute plus pour toujours une quête qu'il ne peut pas encore vérifier.",
	["La sabes"] = "Connue",
	["La sacas de tu plan."] = "Vous la retirez de votre plan.",
	["La sastrería usa la tela que sueltan los humanoides: lino, lana, seda, tejido mágico y tela rúnica."] = "La Couture utilise le tissu que laissent tomber les humanoïdes : lin, laine, soie, tisse-mage et étoffe runique.",
	["La siguiente casilla cuesta %s y no te alcanza todavía."] = "Le prochain emplacement coûte %s et vous n'avez pas encore assez.",
	["La siguiente casilla cuesta %s: cómprala con el botón del banco del juego, que ya está a la vista."] = "L'emplacement suivant coûte %s : achetez-le avec le bouton de la banque du jeu, maintenant visible.",
	["La subasta deja escanear todo cada 15 minutos. Falta %s."] = "L'hôtel des ventes permet un scan complet toutes les 15 minutes. Encore %s.",
	["La subasta no aceptó el escaneo. Intenta de nuevo más tarde."] = "L'hôtel des ventes a refusé le scan. Réessayez plus tard.",
	["La subasta no envió subastas. Intenta de nuevo más tarde."] = "L'hôtel des ventes n'a envoyé aucune enchère. Réessayez plus tard.",
	["La subasta no respondió. Puede que aún esté en espera: intenta en unos minutos."] = "L'hôtel des ventes n'a pas répondu. Il est peut-être encore en attente : réessayez dans quelques minutes.",
	["La suma de lo que guardó Alfa de cada personaje (el tuyo, al día)."] = "La somme de ce qu'Alfa a enregistré pour chaque personnage (le vôtre, à jour).",
	["La tecla del botón de tu barra con esa habilidad, sobre el ícono."] = "La touche du bouton de votre barre qui porte cette technique, sur l'icône.",
	["La tecla del mapa abre este mapa"] = "La touche de la carte ouvre cette carte",
	["La tecla que abre el mapa del juego (M) abre el de Alfa; en él, un botón te lleva al del juego. Apágalo y la tecla vuelve a abrir el del juego. También puedes darle una tecla propia en Opciones > Teclado > Alfa."] = "La touche qui ouvre la carte du jeu (M) ouvre celle d'Alfa ; dans celle-ci, un bouton mène à celle du jeu. Désactivez cette option et la touche ouvre de nouveau la carte du jeu. Vous pouvez aussi lui donner sa propre touche dans Options > Raccourcis > Alfa.",
	["La tecla que usabas en tu otro addon de pesca (%s) ahora pesca con Alfa."] = "La touche que vous utilisiez dans votre autre addon de pêche (%s) pêche maintenant avec Alfa.",
	["La tela rúnica sale de humanoides de nivel 50 o más: los trols de las Tierras del Interior o los sátiros de Frondavil son buena opción."] = "L'étoffe runique vient des humanoïdes de niveau 50 et plus : les trolls des Hinterlands ou les satyres de Gangrebois sont un bon choix.",
	["La tela vil sale de sátiros y demonios de Frondavil y Azshara."] = "La gangrétoffe vient des satyres et démons de Gangrebois et d'Azshara.",
	["La tomo otra vez"] = "Je la reprends",
	["La tribu Zandalar se considera la primera de todos los trols. Sus sacerdotes acampan en la Isla de Yojamba para frenar a Hakkar."] = "La tribu Zandalar se considère comme la première de tous les trolls. Ses prêtres campent sur l'île de Yojamba pour arrêter Hakkar.",
	["La trituradora tira a la gente: vuelve a llamar su atención rápido."] = "Le déchiqueteur projette les gens : reprenez vite son attention.",
	["La tuya tiene %d semanas: salen seguido."] = "La vôtre date de %d semaines : les mises à jour sont fréquentes.",
	["La venta se detuvo: vendiste %d de %d."] = "Vente interrompue : %d vendus sur %d.",
	["La ventana"] = "La fenêtre",
	["La ventana de talentos del juego"] = "La fenêtre des talents du jeu",
	["La ventana del Legado del juego"] = "La fenêtre de l'Héritage du jeu",
	["La última vez cazamos %s"] = "La dernière fois, on a chassé %s",
	["La última: %s."] = "La dernière : %s.",
	["Lady Sylvanas Brisaveloz gobierna a los Renegados. Fue general forestal de Quel'Thalas antes de que Arthas la matara."] = "Dame Sylvanas Coursevent gouverne les Réprouvés. Elle était générale des Rôdeurs de Quel'Thalas avant qu'Arthas ne la tue.",
	["Lady Vashj, que fue dama de compañía de Azshara, ahora guía a sus naga al servicio de Illidan."] = "Dame Vashj, autrefois dame de compagnie d'Azshara, mène aujourd'hui ses nagas au service d'Illidan.",
	["Lanza bolas de fuego y fuego a su alrededor: interrúmpelo y, si peleas de lejos, aléjate."] = "Il lance des boules de feu et du feu autour de lui : interrompez-le et, si vous combattez à distance, éloignez-vous.",
	["Lanza bombas de humo que aturden: sal del humo."] = "Il lance des bombes fumigènes qui étourdissent : sortez de la fumée.",
	["Lanza enredaderas que tumban a todos los que están cerca: si peleas de lejos, quédate lejos."] = "Il lance des lianes qui renversent tous ceux qui sont proches : si vous combattez à distance, restez loin.",
	["Lanza fuego a su alrededor: si peleas de lejos, aléjate de él."] = "Il lance du feu autour de lui : si vous combattez à distance, éloignez-vous de lui.",
	["Lanza hechizos de tierra y pone tótems: rompan los tótems primero."] = "Il lance des sorts de terre et pose des totems : détruisez d'abord les totems.",
	["Lanza metal fundido: si no tanqueas, no te quedes pegado a él."] = "Il projette du métal en fusion : si vous n'êtes pas le tank, ne restez pas collé à lui.",
	["Lanza rayos y se puede curar: interrumpe sus hechizos."] = "Elle lance des éclairs et peut se soigner : interrompez ses sorts.",
	["Lanza ráfagas arcanas: interrúmpelo."] = "Il lance des déflagrations des arcanes : interrompez-le.",
	["Lanza sombras: interrúmpelo."] = "Il lance des sorts d'ombre : interrompez-le.",
	["Lanza telarañas y una maldición: quita la maldición si puedes."] = "Il lance des toiles et une malédiction : dissipez la malédiction si vous le pouvez.",
	["Lanza tormentas de arena que se mueven por la sala: no te pares en ellas."] = "Il crée des tempêtes de sable qui se déplacent dans la salle : ne restez pas dedans.",
	["Lanza tu hechizo más fuerte desde lejos y remata con los instantáneos."] = "Lancez votre sort le plus fort de loin et achevez avec les instantanés.",
	["Lanza tu hechizo más fuerte primero y remata con un choque."] = "Lancez d'abord votre sort le plus fort et achevez avec un horion.",
	["Lanza una nube de veneno hacia adelante: gíralo lejos del grupo."] = "Elle souffle un nuage de poison devant elle : tournez-la loin du groupe.",
	["Lanza una red que deja quieto a un jugador: no es grave, sigue atacando."] = "Il lance un filet qui immobilise un joueur : ce n'est pas grave, continuez d'attaquer.",
	["Lanza veneno a todos: quita el veneno si puedes."] = "Il empoisonne tout le monde : guérissez le poison si vous le pouvez.",
	["Lanzado"] = "Lancé",
	["Lanzamientos"] = "Lancers",
	["Lanzamientos: %d de %d"] = "Lancers : %d sur %d",
	["Las Cavernas del Tiempo guardan los momentos más importantes de la historia, y el Vuelo Bronce no deja que nadie los cambie."] = "Les grottes du Temps gardent les moments les plus importants de l'histoire, et le vol draconique bronze ne laisse personne les changer.",
	["Las Estepas Ardientes se incendiaron cuando Ragnaros despertó, y sus brasas siguen sin apagarse."] = "Les Steppes ardentes se sont embrasées quand Ragnaros s'est réveillé, et leurs braises ne se sont toujours pas éteintes.",
	["Las Islas del Eco eran el hogar de los Lanza Negra, hasta que el brujo Zalazane sometió a muchos con su vudú y los demás tuvieron que mudarse a tierra firme."] = "Les îles de l'Écho étaient le foyer des Sombrelances, jusqu'à ce que le féticheur Zalazane en asservisse beaucoup avec son vaudou et que les autres doivent partir sur le continent.",
	["Las Minas de la Muerte esconden el refugio de VanCleef... y hasta un barco pirata."] = "Les Mortemines cachent le repaire de VanCleef... et même un bateau pirate.",
	["Las Montañas Crestagrana deben su nombre a sus rocas rojizas."] = "Les Carmines doivent leur nom à leurs roches rougeâtres.",
	["Las Profundidades de Roca Negra son una ciudad enana entera bajo la montaña: la capital de los Hierro Negro."] = "Les profondeurs de Rochenoire sont une cité naine entière sous la montagne : la capitale des Sombrefer.",
	["Las Rocas Rojas de Mulgore son un lugar sagrado: ahí descansan los ancestros de los tauren."] = "Les Rochers rouges de Mulgore sont un lieu sacré : les ancêtres des Taurens y reposent.",
	["Las Rocas Rojas son el lugar más sagrado de Mulgore: ahí descansan los ancestros de tu gente."] = "Les Rochers rouges sont le lieu le plus sacré de Mulgore : les ancêtres de ton peuple y reposent.",
	["Las aguas de nivel 20 a 35. El rango Experto se aprende con el libro que vende el pescador de Bahía del Botín."] = "Les eaux de niveau 20 à 35. Le rang Expert s'apprend avec le livre vendu par le pêcheur de Baie-du-Butin.",
	["Las barras de abajo"] = "Les barres du bas",
	["Las bendiciones mayores duran más y cubren a toda una clase del grupo. ¡Ahorran mucho maná!"] = "Les bénédictions supérieures durent plus longtemps et couvrent toute une classe du groupe. Elles économisent beaucoup de mana !",
	["Las bolsas de Alfa acomodan todo por categorías, marcan lo nuevo y lo de misión, y depositan rápido en el banco."] = "Les sacs d’Alfa rangent tout par catégories, marquent le neuf et les objets de quête, et déposent vite à la banque.",
	["Las bolsas que coses siempre se venden: todo el mundo quiere más espacio."] = "Les sacs que tu couds se vendent toujours : tout le monde veut plus de place.",
	["Las bombas y granadas te salvan en mazmorras y en peleas contra el otro bando."] = "Les bombes et les grenades te sauvent en donjon et dans les combats contre l'autre faction.",
	["Las cajas cerradas las abren los pícaros; ofrécelas en el chat y a veces hasta te regalan el servicio."] = "Les coffrets fermés s'ouvrent grâce aux voleurs ; propose-les dans la discussion et parfois ils le font même gratuitement.",
	["Las cartas de la Luna Negra caen de enemigos por todo el mundo; un mazo completo se cambia en la Feria por un abalorio poderoso."] = "Les cartes de Sombrelune tombent sur des ennemis partout dans le monde ; un jeu complet s'échange à la Foire contre un bijou puissant.",
	["Las casas de subastas neutrales de Bahía del Botín, Gadgetzan y Vista Eterna cobran más comisión, pero te dejan comerciar con el otro bando."] = "Les hôtels des ventes neutres de Baie-du-Butin, Gadgetzan et Long-guet prennent plus de commission, mais te laissent commercer avec l'autre faction.",
	["Las centinelas de Vallefresno pelean sin descanso contra los leñadores orcos de Grito de Guerra."] = "Les sentinelles d'Orneval luttent sans relâche contre les bûcherons orcs Chanteguerre.",
	["Las centinelas domestican sables de hielo en Cuna del Invierno, y se los confían solo a quien se gana su respeto."] = "Les sentinelles dressent des sabres-de-givre au Berceau-de-l'Hiver et ne les confient qu'à ceux qui gagnent leur respect.",
	["Las criaturas que invocan los enemigos por un rato."] = "Les créatures que les ennemis invoquent pour un moment.",
	["Las cuentas"] = "Les comptes",
	["Las cuentas de prueba no pueden compartir: el juego no lo permite."] = "Les comptes d'essai ne peuvent pas partager : le jeu ne le permet pas.",
	["Las de tu ruta, las de la guía o todas: se eligen en Ajustes > Misiones, con lo demás de las misiones."] = "Celles de votre itinéraire, celles du guide ou toutes : cela se choisit dans Réglages > Quêtes, avec tout le reste des quêtes.",
	["Las demás"] = "Les autres",
	["Las demás ranuras"] = "Les autres emplacements",
	["Las dos se suben solas mientras matas y viajas, y lo que juntas se vende bien: oro para tu montura y tus habilidades."] = "Les deux montent toutes seules pendant que vous tuez et voyagez, et ce que vous récoltez se vend bien : de l'or pour votre monture et vos techniques.",
	["Las dríades son hijas de Cenarius, y los guardianes de la arboleda, sus hijos."] = "Les dryades sont les filles de Cénarius, et les gardiens du bosquet ses fils.",
	["Las esquinas de la pantalla se oscurecen poco a poco, como en una foto."] = "Les coins de l'écran s'assombrissent peu à peu, comme sur une photo.",
	["Las excavaciones de los enanos despertaron a los troggs, y ahora Thelsamar tiene que cuidarse de ellos."] = "Les fouilles des nains ont réveillé les troggs, et Thelsamar doit maintenant se méfier d'eux.",
	["Las explicaciones vuelven a salir."] = "Les explications s’affichent de nouveau.",
	["Las flores cantoras corrompidas de Frondavil se pueden purificar; al hacerlo te dan una bendición que dura un buen rato."] = "Les fleurs-chantantes corrompues de Gangrebois peuvent être purifiées ; en le faisant, tu reçois une bénédiction qui dure un bon moment.",
	["Las fronteras entre zonas ya no parpadean al mover el mapa."] = "Les frontières entre les zones ne clignotent plus quand vous déplacez la carte.",
	["Las gafas de ingeniero solo las pueden usar ingenieros: ¡lúcelas con orgullo!"] = "Les lunettes d'ingénieur ne peuvent être portées que par les ingénieurs : porte-les avec fierté !",
	["Las hierbas de nivel alto se venden muy bien en la casa de subastas."] = "Les herbes de haut niveau se vendent très bien à l'hôtel des ventes.",
	["Las líneas que escribe Anunciar en el chat de tu grupo o banda."] = "Les lignes qu'Annoncer écrit dans la discussion de votre groupe ou raid.",
	["Las marca con una flecha."] = "Les améliorations ont une flèche.",
	["Las marcas de la manada también en el minimapa, no solo en el mapa del mundo."] = "Les marques de la meute aussi sur la minicarte, pas seulement sur la carte du monde.",
	["Las marcas en el suelo de hechizos y áreas. Apagarlas esconde avisos de combate: mejor dejarlas encendidas."] = "Les marques au sol des sorts et des zones. Les désactiver cache des alertes de combat : mieux vaut les garder.",
	["Las mejores misiones que ya puedes tomar cerca de ti, en el orden más corto."] = "Les meilleures quêtes que vous pouvez déjà prendre près de vous, dans l'ordre le plus court.",
	["Las mesetas de Cima del Trueno están unidas por puentes, y a la ciudad se sube en elevadores."] = "Les plateaux des Pitons-du-Tonnerre sont reliés par des ponts, et on monte à la ville par des ascenseurs.",
	["Las metas se cumplen solas al hacerlas; las notas las marcas tú. Ordénalas como quieras."] = "Les objectifs se remplissent tout seuls quand vous les faites ; les notes, c'est vous qui les cochez. Classez-les comme vous voulez.",
	["Las misiones avisan otra vez"] = "Les quêtes s’annoncent à nouveau",
	["Las misiones de Molino Tarren mandan a la Horda contra las granjas humanas de las laderas."] = "Les quêtes de Moulin-de-Tarren envoient la Horde contre les fermes humaines des contreforts.",
	["Las misiones grises dan poca XP. Entrégalas y sigue adelante."] = "Les quêtes grises donnent peu d'XP. Rends-les et continue.",
	["Las misiones previas y el nivel que pide, para poder tomarla."] = "Les quêtes préalables et le niveau requis, pour pouvoir la prendre.",
	["Las misiones que más experiencia dan cerca de ti."] = "Les quêtes qui donnent le plus d'expérience près de vous.",
	["Las misiones repetibles de reputación, como entregar tela, también son una forma de farmeo."] = "Les quêtes de réputation répétables, comme rendre du tissu, sont aussi une forme de farm.",
	["Las monturas de los gnomos son mecazancudos, aves mecánicas que ellos mismos inventaron."] = "Les montures des gnomes sont des mécanotrotteurs, des oiseaux mécaniques qu'ils ont inventés eux-mêmes.",
	["Las monturas de otra raza de tu bando pueden pedir reputación con su ciudad: la de tu raza siempre se puede."] = "Les montures d'une autre race de votre faction peuvent demander de la réputation auprès de sa ville : celles de votre race sont toujours accessibles.",
	["Las monturas de tu raza"] = "Les montures de votre race",
	["Las monturas épicas del Clásico cuestan bastante oro; juntarlo poco a poco es parte de la aventura."] = "Les montures épiques de Classic coûtent pas mal d'or ; l'économiser petit à petit fait partie de l'aventure.",
	["Las ondas al caminar o nadar en el agua."] = "Les ondulations quand vous marchez ou nagez dans l'eau.",
	["Las orillas de la pantalla un poco más oscuras."] = "Les bords de l'écran un peu plus sombres.",
	["Las pestañas toman la letra y los colores del estilo; la elegida lleva la línea de acento. En Clásico WoW quedan las del juego."] = "Les onglets prennent la police et les couleurs du style ; l'onglet choisi porte la ligne d'accent. Avec WoW classique, ceux du jeu restent.",
	["Las piedras de afilar y los contrapesos que haces le sirven a guerreros y pícaros: siempre tienen compradores."] = "Les pierres à aiguiser et les pierres de lest que tu fais servent aux guerriers et aux voleurs : elles trouvent toujours preneur.",
	["Las piedras de salud que creas le salvan la vida a todo tu grupo."] = "Les pierres de soins que tu crées sauvent la vie de tout ton groupe.",
	["Las placas de nombre de los enemigos."] = "Les barres de nom des ennemis.",
	["Las plantas de herboristería."] = "Les plantes d'herboristerie.",
	["Las pociones de vida y maná siempre se venden: toda mazmorra las pide."] = "Les potions de soins et de mana se vendent toujours : tous les donjons en demandent.",
	["Las primeras misiones de un humano en Villanorte van de kóbolds, bandidos Defias... y lobos. No todos somos buenos, ¿eh?"] = "Les premières quêtes d'un humain à Comté-du-Nord parlent de kobolds, de bandits défias... et de loups. On n'est pas tous gentils, hein ?",
	["Las profesiones de fabricación dan retos del Legado al llegar a 150, 225 y 300."] = "Les métiers de fabrication donnent des défis de l'Héritage à 150, 225 et 300.",
	["Las profesiones de recolección dan oro desde el nivel 1. ¡Hierbas o minería!"] = "Les métiers de récolte rapportent de l'or dès le niveau 1. Herboristerie ou minage !",
	["Las que Lya ya te dijo sus tres veces. Con «Volver a mostrarlos» salen otra vez."] = "Celles que Lya vous a déjà dites trois fois. Avec « Les réafficher », elles reviennent.",
	["Las que me faltan"] = "Celles qui me manquent",
	["Las que se hacen una sola vez."] = "Celles qui ne se font qu'une fois.",
	["Las que se repiten cada día."] = "Celles qui se répètent chaque jour.",
	["Las que se repiten cada semana."] = "Celles qui se répètent chaque semaine.",
	["Las que tengo"] = "Celles que j'ai",
	["Las que vienen después, más pequeñas a la derecha."] = "Celles qui viennent ensuite, plus petites, à droite.",
	["Las que ya hiciste no cuentan."] = "Celles que vous avez déjà faites ne comptent pas.",
	["Las ranuras que tu tecla nunca cambia: cabeza, manos, pies, abalorios y las demás."] = "Les emplacements que votre touche ne change jamais : tête, mains, pieds, bijoux et les autres.",
	["Las recetas se compran a vendedores de comida y algunas caen de enemigos."] = "Les recettes s'achètent chez les vendeurs de nourriture et certaines tombent sur des ennemis.",
	["Las ruinas de Eldarath fueron una ciudad élfica; hoy están llenas de naga."] = "Les ruines d'Eldarath étaient une cité elfique ; aujourd'hui, elles sont pleines de nagas.",
	["Las rutas y los planes que armas en la página Ruta de Alfa."] = "Les itinéraires et les plans que vous créez sur la page Itinéraire d'Alfa.",
	["Las sacerdotisas de Elune guían a tu pueblo, y Tyrande lo gobierna desde el Templo de la Luna."] = "Les prêtresses d'Élune guident ton peuple, et Tyrande le gouverne depuis le temple de la Lune.",
	["Las sesiones guardadas de este personaje."] = "Les sessions enregistrées de ce personnage.",
	["Las sesiones, las zonas y los objetos de este personaje."] = "Les sessions, les zones et les objets de ce personnage.",
	["Las vendas suben de lino a lana, seda, tejido mágico y tela rúnica."] = "Les bandages montent du lin à la laine, la soie, le tisse-mage et l'étoffe runique.",
	["Las ventanas de chat, sus pestañas y la caja para escribir toman el estilo que elijas abajo y cambian con él. Al apagarlo vuelve el chat de siempre, sin /reload."] = "Les fenêtres de discussion, leurs onglets et le champ de saisie prennent le style choisi ci-dessous et changent avec lui. Désactivé, la discussion habituelle revient, sans /reload.",
	["Lavanda"] = "Lavande",
	["Lechúcico"] = "Forme de sélénien",
	["Lectura del agua"] = "Lecture de l'eau",
	["Lee el precio más bajo de cada objeto en toda la subasta. No compra ni publica nada. Se puede usar cada 15 minutos."] = "Lit le prix le plus bas de chaque objet dans tout l'hôtel des ventes. N'achète et ne met rien en vente. Utilisable toutes les 15 minutes.",
	["Lee los objetivos de la misión antes de salir: te ahorras vueltas."] = "Lis les objectifs de la quête avant de partir : tu éviteras des allers-retours.",
	["Leeroy Jenkins se hizo famoso por lanzarse solo, gritando su nombre, a una sala llena de dragoncitos en la Cumbre de Roca Negra."] = "Leeroy Jenkins est devenu célèbre en fonçant seul, en criant son propre nom, dans une salle pleine de dragonnets au pic Rochenoire.",
	["Legado"] = "Héritage",
	["Legendario"] = "Légendaire",
	["Lejos de aquí"] = "Loin d'ici",
	["Lejos de aquí: %s"] = "Loin d'ici : %s",
	["Letra del estilo"] = "Police du style",
	["Letra: grande"] = "Texte : grand",
	["Letra: muy grande"] = "Texte : très grand",
	["Letra: normal"] = "Texte : normal",
	["Letras grandes en el centro de la pantalla cuando el jefe hace algo importante."] = "De grandes lettres au centre de l'écran quand le boss fait quelque chose d'important.",
	["Leyenda"] = "Légende",
	["Leyendo precios... %d%%"] = "Lecture des prix... %d%%",
	["Leyendo tus bolsas…"] = "Lecture de vos sacs…",
	["Libera tu sello en el enemigo: daño extra."] = "Libérez votre sceau sur l'ennemi : dégâts supplémentaires.",
	["Liberar tu espíritu en campos de batalla"] = "Libérer votre esprit sur les champs de bataille",
	["Libre: %d de %d"] = "Libre : %d sur %d",
	["Libro"] = "Livre",
	["Ligado: no se subasta"] = "Lié : ne peut pas être mis aux enchères",
	["Limpien a sus ayudantes antes de empezar con él."] = "Éliminez ses aides avant de vous occuper de lui.",
	["Lista"] = "Prête",
	["Lista de pasos"] = "Liste des étapes",
	["Lista para entrar"] = "Prêt à entrer",
	["Lista para entregar"] = "Prête à rendre",
	["Listas"] = "Prêts",
	["Listas para entregar"] = "Prêtes à rendre",
	["Listo"] = "Terminé",
	["Listo [estado]"] = "Prêt",
	["Listo para ayudar a tu grupo"] = "Prêt à aider votre groupe",
	["Listo para curar"] = "Prêt à soigner",
	["Listo para pescar"] = "Prêt à pêcher",
	["Listo, fijarlos"] = "C'est bon, les verrouiller",
	["Listo: %d habilidades nuevas en tu barra de %s."] = "C'est fait : %d nouvelles techniques sur votre barre pour %s.",
	["Listo: 1 habilidad nueva en tu barra de %s."] = "C'est fait : 1 nouvelle technique sur votre barre pour %s.",
	["Listo: aprendiste %d rangos de talento"] = "C'est fait : vous avez appris %d rangs de talent",
	["Listo: aprendiste 1 rango de talento"] = "C'est fait : vous avez appris 1 rang de talent",
	["Listo: te abrimos un susurro para %s. Revisa el mensaje y pulsa Intro."] = "Terminé : nous avons ouvert un chuchotement pour %s. Vérifiez le message et appuyez sur Entrée.",
	["Listo: tu mapa también funciona en los marcos de Blizzard."] = "Terminé : votre configuration fonctionne aussi sur les cadres de Blizzard.",
	["Llama a la manada cuando necesites ayuda; los lobos de tu zona llegan con «¡Voy!». Y «Seguir» ya no se suelta al alcanzar a alguien."] = "Appelle la meute quand tu as besoin d’aide ; les loups de ta zone arrivent avec « J’arrive ! ». Et « Suivre » ne lâche plus quand tu rattrapes quelqu’un.",
	["Llama a varios lobos al empezar: usen ataques en área o maten primero a los lobos."] = "Il appelle plusieurs loups au début : utilisez des attaques de zone ou tuez d'abord les loups.",
	["Llamados de la manada"] = "Appels de la meute",
	["Llamar a la manada"] = "Appeler la meute",
	["Llamaste a la manada"] = "Tu as appelé la meute",
	["Llave"] = "Clé",
	["Llavero"] = "Trousseau",
	["Llaves"] = "Clés",
	["Llega Lya, una loba compañera que guarda la historia de cada misión y te cuenta datos de cada zona."] = "Voici Lya, une louve compagne qui garde l'histoire de chaque quête et vous raconte des anecdotes sur chaque zone.",
	["Llega a 150 de habilidad."] = "Atteignez 150 en compétence.",
	["Llega a 225 de habilidad."] = "Atteignez 225 en compétence.",
	["Llega a 75 de habilidad."] = "Atteignez 75 en compétence.",
	["Llega a la habilidad máxima de pesca."] = "Atteignez la compétence de pêche maximale.",
	["Llega a la maestría Diestro con una captura."] = "Atteignez la maîtrise Habile avec une prise.",
	["Llega a nivel %d"] = "Atteignez le niveau %d",
	["Llega a nivel 25 con cualquier clase"] = "Atteignez le niveau 25 avec n'importe quelle classe",
	["Llega al nivel 40 (te faltan %d)"] = "Atteignez le niveau 40 (encore %d)",
	["Llega con %d puntos del legado ganados en tu cuenta."] = "Atteignez %d points d'Héritage gagnés sur votre compte.",
	["Llega con ayudantes naga: mátenlos primero."] = "Elle arrive avec des nagas : tuez-les d'abord.",
	["Llega con guardias: tírenlos aparte si pueden."] = "Il arrive avec des gardes : attirez-les à part si vous le pouvez.",
	["Llega con lobos: elimínenlos primero."] = "Il arrive avec des loups : éliminez-les d'abord.",
	["Llega con su perro: una persona debe tanquear a cada uno, o maten al perro primero."] = "Il arrive avec son chien : une personne doit tanker chacun, ou tuez d'abord le chien.",
	["Llega en el nivel %d"] = "Arrive au niveau %d",
	["Llegar a nivel %d"] = "Atteindre le niveau %d",
	["Llegar a un nivel"] = "Atteindre un niveau",
	["Llegas al rival con ira para pegar de inmediato."] = "Vous atteignez l'adversaire avec de la rage pour frapper tout de suite.",
	["Llegaste al final; quedaron %d pasos sin hacer."] = "Vous êtes arrivé au bout ; %d étapes n'ont pas été faites.",
	["Llegaste con %s."] = "Vous avez rejoint %s.",
	["Llegaste con %s. La flecha te sigue llevando mientras se mueve; para soltar el rastro, «Dejar de seguir»."] = "Tu as rejoint %s. La flèche continue de te guider tant que la personne bouge ; pour lâcher la piste, « Ne plus suivre ».",
	["Llenar mi barra"] = "Remplir ma barre",
	["Lleva al máximo la distancia de la cámara (la de Opciones > Controles). Al apagarlo vuelve la que tenías."] = "Met la distance de la caméra (celle d'Options > Contrôles) au maximum. En le désactivant, vous retrouvez la vôtre.",
	["Lleva siempre un sello puesto aunque estés curando."] = "Gardez toujours un sceau actif, même quand vous soignez.",
	["Lleva siempre vendas y comida: descansar poco y seguro es más rápido que morir."] = "Ayez toujours des bandages et de la nourriture : se reposer un peu et en sécurité est plus rapide que mourir.",
	["Llevarla a Mis planes"] = "L'envoyer vers Mes plans",
	["Llevas %s ahora. Solo oro entero (10 = 10 de oro)."] = "Vous avez %s sur vous. Or entier uniquement (10 = 10 po).",
	["Llevas %s jugando. Estírate, toma agua y regresas con más fuerza."] = "Tu joues depuis %s. Étire-toi, bois de l'eau et reviens plus fort.",
	["Llevas %s. La manada te espera aunque te tomes un respiro."] = "Déjà %s. La meute t'attendra si tu fais une pause.",
	["Llevas %s. Si cierras sesión en una posada, ganas XP descansada."] = "Déjà %s. Si tu te déconnectes dans une auberge, tu gagnes de l'XP de repos.",
	["Llorar"] = "Pleurer",
	["Llámala antes de pelear."] = "Appelez-le avant de combattre.",
	["Llévame"] = "M'y emmener",
	["Llévame a la entrada"] = "M'emmener à l'entrée",
	["Llévame a la subasta"] = "M'emmener à l'hôtel des ventes",
	["Llévame a lo que falta"] = "M'emmener à ce qui manque",
	["Llévame a reparar"] = "Aller réparer",
	["Llévame a un vendedor"] = "Aller chez un marchand",
	["Llévame al banco"] = "M'emmener à la banque",
	["Llévame al comerciante"] = "M'emmener chez un marchand",
	["Llévame al instructor"] = "M'emmener au maître",
	["Llévame con mi entrenador"] = "Aller voir mon maître",
	["Lo acompañan otros lanzadores: interrúmpanlos."] = "D'autres lanceurs de sorts l'accompagnent : interrompez-les.",
	["Lo alto de cada compañero."] = "La hauteur de chaque membre.",
	["Lo ancho de cada compañero."] = "La largeur de chaque membre.",
	["Lo apagas o lo enciendes cuando quieras en Manada > La Jauría."] = "Désactivez-le ou activez-le quand vous voulez dans Meute > La Jauría.",
	["Lo conozco de memoria"] = "Je le connais par cœur",
	["Lo de %s y %s tiene su historia. ¿Te la platico?"] = "Entre %s et %s, il y a toute une histoire. Tu veux l'entendre ?",
	["Lo demás, de un vistazo"] = "Le reste, en un coup d'œil",
	["Lo enseña un instructor de la profesión"] = "Enseigné par un maître du métier",
	["Lo enseña un instructor en %s"] = "Enseigné par un maître, à %s",
	["Lo esencial"] = "L'essentiel",
	["Lo estás siguiendo"] = "Vous le suivez",
	["Lo estás siguiendo."] = "Vous le suivez.",
	["Lo gris véndelo a los vendedores, no en la subasta: nadie lo va a comprar ahí."] = "Vends le gris aux marchands, pas à l'hôtel des ventes : personne ne l'y achètera.",
	["Lo gris y lo que marcaste como chatarra. Nunca lo que marcaste para conservar ni lo que pide una misión."] = "Les objets gris et ce que vous avez marqué comme camelote. Jamais ce que vous avez marqué à garder ni ce qu'une quête demande.",
	["Lo justo para abrir la siguiente fila."] = "Juste assez pour ouvrir la rangée suivante.",
	["Lo marca como tu objetivo"] = "En fait votre cible",
	["Lo mejor de los dos lados. Si no sabes cuál elegir, elige este."] = "Le meilleur des deux côtés. Si vous ne savez pas lequel choisir, prenez celui-ci.",
	["Lo mejor para ti"] = "Le meilleur pour vous",
	["Lo mejor para tu nivel"] = "Le meilleur pour votre niveau",
	["Lo menos que espera Lya entre un consejo y otro. Lo importante no espera."] = "Le temps minimum que Lya attend entre deux conseils. L'important n'attend pas.",
	["Lo menos que espera Lya entre una historia y otra. Nunca en combate ni en mazmorras."] = "Le temps minimum que Lya attend entre deux histoires. Jamais en combat ni en donjon.",
	["Lo más cerca"] = "Le plus proche",
	["Lo más cerca de ti"] = "Le plus proche de vous",
	["Lo más gastado va al %d %%. Te llevo con quien repare."] = "Ta pièce la plus usée est à %d %%. Je t’emmène chez quelqu’un qui répare.",
	["Lo más ligero: para equipos modestos o para subir los FPS en peleas grandes."] = "Le plus léger : pour les PC modestes ou pour gagner des FPS dans les grands combats.",
	["Lo más parecido"] = "Le plus proche",
	["Lo nuevo de esta versión"] = "Nouveautés de cette version",
	["Lo nuevo de esta versión, en pocas palabras."] = "Ce qu'apporte cette version, en quelques mots.",
	["Lo nuevo en Alfa %s"] = "Nouveautés d'Alfa %s",
	["Lo nuevo en Alfa 1.0"] = "Nouveautés d'Alfa 1.0",
	["Lo pequeño que hace el juego más cómodo: el minimapa, el chat y las barras con el estilo de Alfa, marcos, cuadro de información, probador, cámara y sonidos; y en sus pestañas, viajes, invitaciones, comerciantes y más."] = "Les petites choses qui rendent le jeu plus confortable : la minicarte, le chat et les barres au style d'Alfa, les cadres, l'infobulle, la cabine d'essayage, la caméra et les sons ; et dans ses onglets, les voyages, les invitations, les marchands et plus.",
	["Lo pequeño que hace el juego más cómodo: misiones, vuelos, minimapa, chat y barras con el estilo de Alfa, marcos, cuadro de información, probador, cámara y sonidos."] = "Les petites choses qui rendent le jeu plus confortable : quêtes, vols, minicarte, discussion et barres au style d'Alfa, cadres, infobulle, cabine d'essayage, caméra et sons.",
	["Lo pescado en esta sesión"] = "Prises de cette session",
	["Lo piden estas misiones"] = "Quêtes qui le demandent",
	["Lo pones al empezar a pelear."] = "Vous l'activez au début du combat.",
	["Lo que Alfa acepta, rechaza o comparte sola. Mantén presionado Mayús para decidir tú en el momento."] = "Ce qu'Alfa accepte, refuse ou partage tout seul. Maintenez Maj pour décider vous-même sur le moment.",
	["Lo que Lya sabe de aquí"] = "Ce que Lya sait de cet endroit",
	["Lo que buscas en la Enciclopedia"] = "Ce que vous cherchez dans l'Encyclopédie",
	["Lo que comparte alguien de tu grupo con Alfa llega a tus marcadores, con su nombre, y te avisa para seguirlo."] = "Ce que partage avec Alfa quelqu'un de votre groupe arrive dans vos marqueurs, avec son nom, et vous prévient pour que vous le suiviez.",
	["Lo que conoce Alfa"] = "Ce que connaît Alfa",
	["Lo que cuentan las misiones que vas tomando"] = "Ce que racontent les quêtes que vous prenez",
	["Lo que da"] = "Ce qu'elle donne",
	["Lo que dice el diario de monturas"] = "Ce que dit la collection de montures",
	["Lo que el menú del juego no enseña, a tu gusto"] = "Ce que le menu du jeu ne montre pas, à votre goût",
	["Lo que elegiste al configurarlo: aceptar y entregar misiones, vender lo gris, reparar, tomar vuelos... Lo cambias cuando quieras."] = "Ce que tu as choisi à la configuration : accepter et rendre les quêtes, vendre le gris, réparer, prendre les vols... Change-le quand tu veux.",
	["Lo que encuentras en la manada"] = "Ce que vous trouverez dans la meute",
	["Lo que este personaje lleva en las mazmorras: se guarda solo al vencer jefes y recoger botín."] = "Ce que ce personnage a accompli dans les donjons : enregistré tout seul quand vous vainquez des boss et ramassez du butin.",
	["Lo que ganaste la última vez que jugaste con este personaje."] = "Ce que vous avez gagné la dernière fois que vous avez joué ce personnage.",
	["Lo que gastan tus hechizos"] = "Ce que consomment vos sorts",
	["Lo que hay dentro"] = "Ce qu'il y a dedans",
	["Lo que llevas"] = "Ce que vous portez",
	["Lo que llevas pescado: %s."] = "Ce que vous avez pêché jusqu'ici : %s.",
	["Lo que me sirve"] = "Ce qui m'est utile",
	["Lo que menos vale: %s"] = "Ce qui vaut le moins : %s",
	["Lo que más conviene ahora"] = "Le plus rentable maintenant",
	["Lo que obtuviste en esta sesión"] = "Ce que vous avez obtenu cette session",
	["Lo que pescaste"] = "Ce que vous avez pêché",
	["Lo que pide %s antes, en orden."] = "Ce que %s demande avant, dans l'ordre.",
	["Lo que quieras contarle al desarrollador de Alfa."] = "Ce que vous voulez dire au développeur d'Alfa.",
	["Lo que quieras; la marcas tú cuando la hagas."] = "Ce que vous voulez ; c'est vous qui la cochez quand vous la faites.",
	["Lo que sacas en %s: %s."] = "Ce que vous pêchez à %s : %s.",
	["Lo que se pesca aquí"] = "Ce qu'on pêche ici",
	["Lo que se queda la subasta de cada venta. Suele ser 5 % en la de tu facción y 15 % en la neutral. Es un estimado."] = "Ce que l'hôtel des ventes garde sur chaque vente. En général 5 % à celui de votre faction et 15 % à l'hôtel neutre. C'est une estimation.",
	["Lo que sigue en tu build no está en tu árbol"] = "La suite de votre build n'est pas dans votre arbre",
	["Lo que sigue pide este nivel: hasta entonces, la guía no te manda allá."] = "La suite demande ce niveau : d'ici là, le guide ne vous y envoie pas.",
	["Lo que sugiere Alfa"] = "Ce qu'Alfa suggère",
	["Lo que te ha contado"] = "Ce qu'elle vous a raconté",
	["Lo que te ofrece Lya (su botón)"] = "Ce que Lya te propose (son bouton)",
	["Lo que te pasa a ti: curación recibida, esquivas, recursos. Puede necesitar /reload la primera vez."] = "Ce qui vous arrive : soins reçus, esquives, ressources. Peut nécessiter un /reload la première fois.",
	["Lo que te piden"] = "Ce qu'on vous demande",
	["Lo que tenía ya está hecho, omitido o fuera de tu registro. Ármalo otra vez con las misiones que tienes ahora."] = "Ce qu’il contenait est fait, passé ou n’est plus dans ton journal. Refais-le avec les quêtes que tu as maintenant.",
	["Lo que trajo la última versión de Alfa, contado corto."] = "Ce qu’a apporté la dernière version d’Alfa, en bref.",
	["Lo que tu build necesita de tu equipo y dónde conseguirlo."] = "Ce que votre build attend de votre équipement et où l'obtenir.",
	["Lo que tu clase se pone antes de pelear está activo."] = "Ce que votre classe s'applique avant un combat est actif.",
	["Lo que tu profesión de recolección junta mejor."] = "Ce que votre métier de récolte rapporte le mieux.",
	["Lo que vale"] = "Ce que ça vaut",
	["Lo que ya tienes en el banco"] = "Ce que vous avez déjà à la banque",
	["Lo recolectaste %d veces"] = "Vous l'avez récolté %d fois",
	["Lo recolectaste 1 vez"] = "Vous l'avez récolté 1 fois",
	["Lo revisa el desarrollador de Alfa. En ese canal nadie más ve tu mensaje. Si aún no estás en el Discord, entra con la invitación de arriba."] = "Le développeur d'Alfa le lit. Dans ce canal, personne d'autre ne voit votre message. Si vous n'êtes pas encore sur le Discord, rejoignez-le avec l'invitation ci-dessus.",
	["Lo sigues"] = "Suivi",
	["Lo sigues: el rastreador te muestra la meta de ahora y la flecha va a cada lugar."] = "Vous le suivez : le suivi affiche l'objectif actuel et la flèche va à chaque lieu.",
	["Lo siguiente"] = "La suite",
	["Lo siguiente para ti"] = "La suite pour vous",
	["Lo sueltan"] = "Laissé par",
	["Lo último que consultaste"] = "Vos dernières recherches",
	["Lo último que te dije"] = "Ce que je t’ai dit en dernier",
	["Lobo"] = "Loup",
	["Lobos conectados"] = "Loups connectés",
	["Logrado el %s"] = "Obtenu le %s",
	["Logrados"] = "Obtenus",
	["Logro de pesca: %s"] = "Haut fait de pêche : %s",
	["Logros"] = "Hauts faits",
	["Logros de pesca"] = "Hauts faits de pêche",
	["Lord Kazzak, un demonio enorme, ronda las Tierras Devastadas; en el Clásico es un jefe de mundo para bandas."] = "Le seigneur Kazzak, un démon énorme, rôde dans les Terres foudroyées ; en Classic, c'est un boss de monde pour raids.",
	["Lord Xavius, el consejero de Azshara, convenció a los Altonato de abrirle la puerta a Sargeras. Cuando murió, Sargeras lo trajo de vuelta como el primer sátiro."] = "Lord Xavius, le conseiller d'Azshara, a convaincu les Bien-nés d'ouvrir la voie à Sargeras. À sa mort, Sargeras l'a ramené comme le premier satyre.",
	["Los Altonato eran la nobleza élfica que vivía para la magia del Pozo. Su reina, Azshara, era tan bella que su pueblo la adoraba."] = "Les Bien-nés étaient la noblesse elfe qui vivait pour la magie du Puits. Leur reine, Azshara, était si belle que son peuple la vénérait.",
	["Los Amani pelearon contra los altos elfos durante miles de años. Su capital, Zul'Aman, está en los bosques cerca de Quel'Thalas."] = "Les Amani ont combattu les hauts-elfes pendant des milliers d'années. Leur capitale, Zul'Aman, se trouve dans les forêts près de Quel'Thalas.",
	["Los Barbabronce ganaron la Guerra de los Tres Martillos, y por eso Forjaz es suya."] = "Les Barbe-de-bronze ont gagné la guerre des Trois marteaux, et c'est pour ça que Forgefer leur appartient.",
	["Los Claros de Tirisfal guardan las ruinas de Lordaeron, el reino de Arthas. Bajo su antigua capital, los Renegados levantaron Entrañas."] = "Les clairières de Tirisfal abritent les ruines de Lordaeron, le royaume d'Arthas. Sous son ancienne capitale, les Réprouvés ont bâti Fossoyeuse.",
	["Los Defias usan cosechadores mecánicos que trabajan solos en los campos... y no les gustan las visitas."] = "Les Défias utilisent des moissonneuses mécaniques qui travaillent seules dans les champs... et qui n'aiment pas les visites.",
	["Los Furiarena de Zul'Farrak son trols del desierto, primos lejanos de los Lanza Negra."] = "Les Furie-des-sables de Zul'Farrak sont des trolls du désert, cousins éloignés des Sombrelances.",
	["Los Gurubashi llamaron a Hakkar, el Desollador de Almas. Cuando vieron lo que hacía, las demás tribus se unieron para echarlo."] = "Les Gurubashi ont appelé Hakkar l'Écorcheur d'âmes. Quand ils ont vu ce qu'il faisait, les autres tribus se sont unies pour le chasser.",
	["Los Hierro Negro invocaron a Ragnaros sin querer al final de la Guerra de los Tres Martillos, y desde entonces son sus esclavos."] = "Les Sombrefer ont invoqué Ragnaros par accident à la fin de la guerre des Trois marteaux, et ils sont ses esclaves depuis.",
	["Los Hierro Negro también excavan en Uldaman, buscando lo mismo que los enanos de Forjaz."] = "Les Sombrefer fouillent aussi Uldaman, à la recherche de la même chose que les nains de Forgefer.",
	["Los Lanza Negra suelen terminar sus frases con un «mon». ¡Se pega, mon!"] = "Les Sombrelances finissent souvent leurs phrases par un « man ». Ça s'attrape, man !",
	["Los PNJ dejan de hablar al saludarte o al darte misiones. También calla las voces de error."] = "Les PNJ cessent de parler quand ils vous saluent ou vous donnent des quêtes. Coupe aussi les voix d'erreur.",
	["Los Perdidos del pantano son draenei que llegaron de Draenor y quedaron cambiados para siempre."] = "Les Égarés du marais sont des draeneï venus de Draenor et changés pour toujours.",
	["Los Páramos de Poniente eran el granero de Ventormenta; hoy muchas de sus granjas están en manos de la Hermandad Defias."] = "La marche de l'Ouest était le grenier de Hurlevent ; aujourd'hui, beaucoup de ses fermes sont aux mains de la Confrérie défias.",
	["Los Renegados aguantan bajo el agua mucho más que los vivos. ¡No necesitan respirar tanto!"] = "Les Réprouvés tiennent sous l'eau bien plus longtemps que les vivants. Ils n'ont pas tant besoin de respirer !",
	["Los Renegados entraron a la Horda gracias a los tauren, que esperaban encontrarles una cura. Muchos orcos aún no se fían de ellos."] = "Les Réprouvés sont entrés dans la Horde grâce aux Taurens, qui espéraient leur trouver un remède. Beaucoup d'orcs ne leur font toujours pas confiance.",
	["Los Renegados hicieron de Rémol, un viejo pueblo humano, su primera parada en Tirisfal."] = "Les Réprouvés ont fait de Brill, un vieux village humain, leur première étape à Tirisfal.",
	["Los Renegados nuevos despiertan en Camposanto, en Tirisfal, como no-muertos libres del Rey Exánime."] = "Les nouveaux Réprouvés se réveillent au Glas-Mortuaire, à Tirisfal, en morts-vivants libérés du roi-liche.",
	["Los Renegados pueden comerse cadáveres para recuperar vida. Yo prefiero las salchichas, gracias."] = "Les Réprouvés peuvent dévorer des cadavres pour récupérer de la vie. Moi, je préfère les saucisses, merci.",
	["Los Renegados recuerdan quiénes fueron en vida, y eso pesa más que cualquier herida."] = "Les Réprouvés se souviennent de qui ils étaient de leur vivant, et ça pèse plus lourd que n'importe quelle blessure.",
	["Los Renegados son no-muertos que recuperaron su voluntad cuando el poder del Rey Exánime se debilitó."] = "Les Réprouvés sont des morts-vivants qui ont retrouvé leur libre arbitre quand le pouvoir du roi-liche s'est affaibli.",
	["Los Tótem Siniestro son tauren que no quieren a la Horda; su jefa Magatha vive en la misma Cima del Trueno."] = "Les Totem-Sinistre sont des Taurens qui n'aiment pas la Horde ; leur cheffe Magatha vit aux Pitons-du-Tonnerre même.",
	["Los ajustes de los recordatorios están en la búsqueda de la ventana de Alfa."] = "Les réglages des rappels sont dans la recherche de la fenêtre d'Alfa.",
	["Los altos elfos pelearon con la Alianza en la Segunda Guerra por una vieja deuda de sangre con el linaje de Thoradin."] = "Les hauts-elfes ont combattu avec l'Alliance pendant la Deuxième Guerre à cause d'une vieille dette de sang envers la lignée de Thoradin.",
	["Los altos elfos que sobrevivieron a la Plaga empezaron a llamarse elfos de sangre, en honor a los suyos caídos. Kael'thas los guía."] = "Les hauts-elfes qui ont survécu au Fléau se sont mis à s'appeler elfes de sang, en l'honneur des leurs tombés. Kael'thas les guide.",
	["Los antídotos que haces curan venenos. ¡En las arañas de Vallefresno se agradecen!"] = "Les antivenins que tu fais soignent les poisons. Avec les araignées d'Orneval, c'est bienvenu !",
	["Los aqir eran un imperio antiguo de insectos que peleó contra los trols. De ellos vienen los qiraji de Ahn'Qiraj y los nerubianos del norte."] = "Les aqir étaient un ancien empire d'insectes qui a combattu les trolls. D'eux descendent les Qiraji d'Ahn'Qiraj et les Nérubiens du nord.",
	["Los avisos de viaje hablan como la manada: «La manada viaja», el lobo en el aro y una huellita que camina mientras llega tu barco."] = "Les alertes de voyage parlent comme la meute : « La meute voyage », le loup dans l’anneau et une empreinte qui avance pendant que ton bateau arrive.",
	["Los avisos pequeños de Alfa los dice Lya en su globo, con su botón, en vez de salir arriba. Si está oculta o en combate, salen como siempre."] = "Les petites alertes d’Alfa, c’est Lya qui les dit dans sa bulle, avec leur bouton, au lieu d’apparaître en haut. Si elle est cachée ou en combat, elles s’affichent comme d’habitude.",
	["Los ayudantes de los enemigos."] = "Les auxiliaires des ennemis.",
	["Los botones de otros addons alrededor del minimapa (también el de Alfa) solo aparecen al pasar el ratón por encima."] = "Les boutons des autres addons autour de la minicarte (celui d'Alfa aussi) n'apparaissent qu'au survol de la souris.",
	["Los cebos suben tu habilidad de pesca un rato: úsalos en aguas difíciles."] = "Les appâts augmentent ta compétence de pêche un moment : utilise-les dans les eaux difficiles.",
	["Los cementerios del Ocaso están llenos de no-muertos levantados por nigromantes que se esconden en el bosque."] = "Les cimetières du bois de la Pénombre sont pleins de morts-vivants relevés par des nécromanciens cachés dans la forêt.",
	["Los centauros dicen descender de Zaetar, hijo del semidiós Cenarius, y de Theradras, la princesa de la tierra. Pelean entre sus clanes casi tanto como contra los demás."] = "Les centaures disent descendre de Zaetar, fils du demi-dieu Cénarius, et de Theradras, la princesse de la terre. Leurs clans se battent entre eux presque autant que contre les autres.",
	["Los cinco Aspectos Dragón recibieron su poder de los titanes: Alexstrasza la vida, Ysera el sueño, Nozdormu el tiempo, Malygos la magia y Neltharion la tierra."] = "Les cinq Aspects draconiques ont reçu leur pouvoir des titans : Alexstrasza la vie, Ysera le rêve, Nozdormu le temps, Malygos la magie et Neltharion la terre.",
	["Los clanes Gelkis y Magram de Desolace pelean entre sí, y ambos buscan aliados entre los aventureros."] = "Les clans Gelkis et Magram de Désolace se battent entre eux, et tous deux cherchent des alliés parmi les aventuriers.",
	["Los clanes orcos tienen historias distintas: Lobo Gélido, Grito de Guerra, Roca Negra, Faucedraco... cada uno con su orgullo."] = "Les clans orcs ont des histoires très différentes : Loup-de-givre, Chanteguerre, Rochenoire, Gueule-de-dragon... chacun avec sa fierté.",
	["Los cruzados escarlata vienen en grupos y algunos curan: interrumpan a los que curan."] = "Les croisés écarlates viennent en groupe et certains soignent : interrompez les soigneurs.",
	["Los críticos hacen el doble de daño y al guerrero le dan más ira."] = "Les critiques font le double de dégâts et donnent plus de rage au guerrier.",
	["Los cuatro dragones verdes de la pesadilla, Ysondre, Lethon, Emeriss y Taerar, aparecen junto a los grandes árboles del Sueño."] = "Les quatre dragons verts du cauchemar, Ysondre, Léthon, Émeriss et Taerar, apparaissent près des grands arbres du Rêve.",
	["Los cuatro señores elementales son Ragnaros del fuego, Al'Akir del aire, Therazane de la tierra y Neptulon del agua."] = "Les quatre seigneurs élémentaires sont Ragnaros du feu, Al'Akir de l'air, Therazane de la terre et Neptulon de l'eau.",
	["Los cultistas del Martillo Crepuscular usan piedras de viento para invocar a sus señores; con su disfraz, tú también puedes."] = "Les cultistes du Marteau du crépuscule utilisent des pierres du vent pour invoquer leurs seigneurs ; avec leur déguisement, tu le peux aussi.",
	["Los datos de Alfa no cargaron (%s)."] = "Les données d'Alfa ne se sont pas chargées (%s).",
	["Los datos de Alfa no traen botín propio de sus jefes."] = "Les données d'Alfa n'ont pas de butin propre pour ses boss.",
	["Los datos de las mazmorras no están cargados."] = "Les données des donjons ne sont pas chargées.",
	["Los datos de las mazmorras se cargan fuera de combate. Esta página se llena sola al terminar la pelea."] = "Les données des donjons se chargent hors combat. Cette page se remplit toute seule à la fin du combat.",
	["Los datos del mundo (Codex) no están disponibles: faltan los bancos, las misiones y de dónde sale cada cosa."] = "Les données du monde (Codex) ne sont pas disponibles : il manque les bancs, les quêtes et la provenance de chaque chose.",
	["Los datos del mundo de Alfa están apagados: activa «Alfa Codex» en la lista de addons."] = "Les données du monde d'Alfa sont désactivées : activez « Alfa Codex » dans la liste des addons.",
	["Los datos son del medidor oficial del juego: tú, tu grupo o banda y sus mascotas."] = "Les données viennent du compteur officiel du jeu : vous, votre groupe ou raid, et leurs familiers.",
	["Los dioses antiguos son seres de antes de los titanes, encerrados bajo la tierra de Azeroth. C'Thun y Yogg-Saron susurran a quien quiera escuchar."] = "Les Dieux très anciens sont des êtres antérieurs aux titans, emprisonnés sous le sol d'Azeroth. C'Thun et Yogg-Saron murmurent à qui veut bien les écouter.",
	["Los dioses antiguos susurran en la mente de los mortales; muchos cultos, como el Martillo Crepuscular, nacieron de escucharlos."] = "Les Dieux très anciens murmurent dans l'esprit des mortels ; beaucoup de cultes, comme le Marteau du crépuscule, sont nés de leur écoute.",
	["Los dos"] = "Les deux",
	["Los dos bandos"] = "Les deux factions",
	["Los dracoleones son las monturas voladoras de la Horda; los grifos, las de la Alianza; y los hipogrifos, las de los elfos de la noche."] = "Les coursiers du vent sont les montures volantes de la Horde ; les griffons, celles de l'Alliance ; et les hippogriffes, celles des elfes de la nuit.",
	["Los dracónidos negros rondan la entrada de la guarida de Onyxia, al sur del marjal."] = "Des dragoniens noirs rôdent à l'entrée du repaire d'Onyxia, au sud du marécage.",
	["Los dracónidos son los soldados de los dragones; los negros sirven a Nefarian en la Montaña Roca Negra."] = "Les dragoniens sont les soldats des dragons ; les noirs servent Nefarian au mont Rochenoire.",
	["Los draenei huyeron de su mundo, Argus, con el profeta Velen. Su nombre quiere decir «los exiliados»."] = "Les draeneï ont fui leur monde, Argus, avec le prophète Velen. Leur nom veut dire « les exilés ».",
	["Los dragones cromáticos, con escamas de todos los colores, son experimentos de Nefarian. Su obra más temida es Chromaggus."] = "Les dragons chromatiques, aux écailles de toutes les couleurs, sont les expériences de Nefarian. Sa création la plus redoutée est Chromaggus.",
	["Los dragones negros se disfrazan de humanos para engañar: Onyxia es Lady Katrana Prestor en Ventormenta, y Nefarian se hace llamar Lord Victor Nefarius."] = "Les dragons noirs se déguisent en humains pour tromper : Onyxia est dame Katrana Prestor à Hurlevent, et Nefarian se fait appeler lord Victor Nefarius.",
	["Los dragones verdes siguen vigilando el templo hundido para que nadie vuelva a llamar a Hakkar."] = "Les dragons verts surveillent toujours le temple englouti pour que personne n'appelle à nouveau Hakkar.",
	["Los elementales de fuego de La Garganta de Fuego y del Cráter de Un'Goro sueltan materiales de fuego que piden muchas profesiones."] = "Les élémentaires de feu de la gorge des Vents brûlants et du cratère d'Un'Goro laissent tomber des matériaux de feu que demandent beaucoup de métiers.",
	["Los elementales de fuego y las arañas de lava son los vecinos de siempre de La Garganta de Fuego."] = "Les élémentaires de feu et les araignées de lave sont les voisins habituels de la gorge des Vents brûlants.",
	["Los elfos de la noche fueron inmortales gracias a Nordrassil, hasta que lo sacrificaron para vencer a Archimonde en el Monte Hyjal."] = "Les elfes de la nuit étaient immortels grâce à Nordrassil, jusqu'à ce qu'ils le sacrifient pour vaincre Archimonde au mont Hyjal.",
	["Los elfos de la noche montan sables, grandes felinos. No es por nada, pero un lobo es más simpático."] = "Les elfes de la nuit montent des sabres, de grands félins. Ce n'est pas pour dire, mais un loup est plus sympathique.",
	["Los elfos de la noche nuevos empiezan en la Cañada Umbría, en Teldrassil, entre arañas y fuegos fatuos."] = "Les nouveaux elfes de la nuit commencent à Sombrevallon, sur Teldrassil, entre araignées et feux follets.",
	["Los elfos de la noche pueden fundirse con las sombras cuando se quedan quietos."] = "Les elfes de la nuit peuvent se fondre dans les ombres quand ils restent immobiles.",
	["Los elfos de la noche se unieron a la Alianza después de la Tercera Guerra."] = "Les elfes de la nuit ont rejoint l'Alliance après la Troisième Guerre.",
	["Los enanos Hierro Negro tomaron Dun Modr, al norte de Los Humedales, y desde ahí molestan a quien cruce el puente."] = "Les nains Sombrefer ont pris Dun Modr, au nord des Paluns, et harcèlent de là quiconque traverse le pont.",
	["Los enanos creen descender de los terráneos de piedra de los titanes, y por eso la Liga de Expedicionarios excava sin parar."] = "Les nains croient descendre des terrestres de pierre des titans, et c'est pour ça que la Ligue des explorateurs fouille sans arrêt.",
	["Los enanos de Forjaz pelean contra los Hierro Negro en Los Humedales y en las Tierras Inhóspitas."] = "Les nains de Forgefer combattent les Sombrefer dans les Paluns et les Terres ingrates.",
	["Los enanos nuevos empiezan en un valle helado de Dun Morogh, peleando contra trols de las nieves y troggs."] = "Les nouveaux nains commencent dans une vallée glacée de Dun Morogh, à combattre des trolls des glaces et des troggs.",
	["Los encantadores también hacen varitas: los magos, sacerdotes y brujos te lo agradecerán."] = "Les enchanteurs font aussi des baguettes : mages, prêtres et démonistes t'en remercieront.",
	["Los enemigos de alrededor pegan menos."] = "Les ennemis autour de vous frappent moins fort.",
	["Los enemigos de tus misiones marcados sobre su placa de nombre y los objetos de misión brillando en tus bolsas."] = "Les ennemis de vos quêtes marqués sur leur barre de nom et les objets de quête qui brillent dans vos sacs.",
	["Los enemigos lanzan radiación y veneno: lleven pociones de vida."] = "Les ennemis utilisent radiations et poison : prévoyez des potions de soins.",
	["Los enemigos más débiles, que el juego marca con un signo de menos."] = "Les ennemis les plus faibles, que le jeu marque d'un signe moins.",
	["Los espíritus de las elfas caídas que la Plaga esclaviza se vuelven banshees. Sylvanas es la más famosa de todas."] = "Les esprits des elfes tombées que le Fléau asservit deviennent des banshees. Sylvanas est la plus célèbre de toutes.",
	["Los fragmentos de alma se ganan drenando el alma del enemigo justo cuando muere."] = "Les fragments d'âme s'obtiennent en siphonnant l'âme de l'ennemi juste au moment où il meurt.",
	["Los frascos del Clásico duran dos horas y aguantan aunque mueras: por eso las bandas los piden tanto."] = "Les flacons de Classic durent deux heures et persistent même si tu meurs : c'est pour ça que les raids en demandent autant.",
	["Los frascos más poderosos llevan Loto negro, la hierba más rara de Azeroth."] = "Les flacons les plus puissants demandent du Lotus noir, l'herbe la plus rare d'Azeroth.",
	["Los fuegos artificiales también son ingeniería. ¡Uno para festejar cada nivel!"] = "Les feux d'artifice, c'est aussi de l'ingénierie. Un pour fêter chaque niveau !",
	["Los fuegos fatuos son espíritus de elfos de la noche que siguen cuidando el bosque después de morir."] = "Les feux follets sont les esprits d'elfes de la nuit qui continuent de veiller sur la forêt après leur mort.",
	["Los furbolgs Fauces de Madera son de los pocos que no se han corrompido; sus túneles llevan a Cuna del Invierno y al Claro de la Luna."] = "Les furbolgs Grumegueules sont parmi les rares à ne pas avoir été corrompus ; leurs tunnels mènent au Berceau-de-l'Hiver et à Reflet-de-Lune.",
	["Los furbolgs de Costa Oscura se están corrompiendo, y los elfos de Auberdine no saben bien por qué."] = "Les furbolgs de Sombrivage se corrompent, et les elfes d'Auberdine ne savent pas bien pourquoi.",
	["Los furbolgs eran un pueblo pacífico de hombres oso, pero la corrupción de los demonios enloqueció a muchas de sus tribus."] = "Les furbolgs étaient un peuple paisible d'hommes-ours, mais la corruption démoniaque a rendu fous beaucoup de leurs tribus.",
	["Los geomantes lanzan fuego y ponen tótems: interrúmpanlos y rompan los tótems."] = "Les géomanciens lancent du feu et posent des totems : interrompez-les et détruisez les totems.",
	["Los gnomos empiezan con los enanos en Dun Morogh: Gnomeregan está perdida y tu gente vive refugiada en Forjaz."] = "Les gnomes commencent avec les nains à Dun Morogh : Gnomeregan est perdue et ton peuple vit réfugié à Forgefer.",
	["Los gnomos inventaron el Tranvía Subterráneo que une Forjaz con Ventormenta."] = "Les gnomes ont inventé le tram des profondeurs qui relie Forgefer à Hurlevent.",
	["Los gnomos que se quedaron en Gnomeregan quedaron dañados por la radiación; algunos perdieron la razón."] = "Les gnomes restés à Gnomeregan ont été abîmés par les radiations ; certains ont perdu la raison.",
	["Los goblins de la fundición tienen ayudantes cerca: miren alrededor antes de atacar."] = "Les gobelins de la fonderie ont des aides à proximité : regardez autour avant d'attaquer.",
	["Los goblins vienen de la isla de Kezan, y su gran ciudad es Minahonda. Le son más leales al oro que a cualquier bando."] = "Les gobelins viennent de l'île de Kezan, et leur grande ville est Terremine. Ils sont plus fidèles à l'or qu'à n'importe quelle faction.",
	["Los grandes árboles que hablan en Darnassus y Vallefresno son Ancestros, guardianes del bosque."] = "Les grands arbres qui parlent à Darnassus et en Orneval sont des Anciens, gardiens de la forêt.",
	["Los grifos (o dragones) a los lados de la barra principal."] = "Les griffons (ou wyvernes) de chaque côté de la barre principale.",
	["Los grifos (o dragones) a los lados de la barra principal. «Del color del estilo» necesita el estilo de las barras; «Ocultos» funciona siempre."] = "Les griffons (ou wyvernes) de chaque côté de la barre principale. « De la couleur du style » demande le style des barres ; « Cachés » marche toujours.",
	["Los gules, las abominaciones y las gárgolas son los soldados más comunes de la Plaga. Las abominaciones se cosen con partes de muchos cadáveres."] = "Goules, abominations et gargouilles sont les soldats les plus courants du Fléau. Les abominations sont cousues à partir de nombreux cadavres.",
	["Los herreros hacen llaves que abren cofres y cajas cerradas. ¡Útil y divertido!"] = "Les forgerons font des clés qui ouvrent les coffres et les coffrets fermés. Utile et amusant !",
	["Los humanos fueron los primeros en aprender magia de los altos elfos, allá en las Guerras Trol."] = "Les humains ont été les premiers à apprendre la magie des hauts-elfes, à l'époque des guerres des Trolls.",
	["Los infernales son demonios que la Legión arroja desde el cielo como meteoritos."] = "Les infernaux sont des démons que la Légion fait tomber du ciel comme des météores.",
	["Los ingenieros pueden fabricar mascotas mecánicas, como una ardilla."] = "Les ingénieurs peuvent fabriquer des mascottes mécaniques, comme un écureuil.",
	["Los instructores y vendedores de pesca se ven en el mapa y el minimapa."] = "Les maîtres et vendeurs de pêche s'affichent sur la carte et la minicarte.",
	["Los jefes opcionales y raros se descubren al terminar la mazmorra."] = "Les boss optionnels et rares se découvrent à la fin du donjon.",
	["Los jefes se descubren al vencerlos: su nombre y su botín quedan ocultos hasta entonces. Sus consejos siempre se pueden ver."] = "Les boss se découvrent en les vainquant : leur nom et leur butin restent cachés jusque-là. Leurs conseils sont toujours visibles.",
	["Los kits de armadura que haces le sirven a todo el mundo: siempre hay quien los compre."] = "Les nécessaires d'armure que tu fais servent à tout le monde : il y a toujours un acheteur.",
	["Los kodos son los compañeros de viaje de los tauren, y en Desolace está su cementerio."] = "Les kodos sont les compagnons de voyage des Taurens, et leur cimetière est en Désolace.",
	["Los kóbolds de las minas de Elwynn cuidan sus velas como un tesoro: bajo tierra, la luz lo es todo."] = "Les kobolds des mines d'Elwynn gardent leurs bougies comme un trésor : sous terre, la lumière est tout.",
	["Los lobos aprenden Aullido furioso, que sube el daño de tu grupo. ¡Ya ves, los lobos somos lo máximo!"] = "Les loups apprennent Hurlement furieux, qui augmente les dégâts de ton groupe. Tu vois ? Les loups, on est les meilleurs !",
	["Los lobos de tu zona saben dónde estás. Te aviso quién viene."] = "Les loups de ta zone savent où tu es. Je te dis qui vient.",
	["Los lobos que se dejan ver en el mapa. Un clic en su marca y la flecha te lleva."] = "Les loups qui se laissent voir sur la carte. Un clic sur leur marque et la flèche vous y mène.",
	["Los lobos que usan Alfa y se dejan ver en el mapa, y tu grupo, que ves ahora."] = "Les loups qui utilisent Alfa et se laissent voir sur la carte, et votre groupe, que vous voyez maintenant.",
	["Los logros de la manada: se ganan pescando, cocinando lo que pescas y explorando aguas nuevas. Cada uno se anuncia una sola vez."] = "Les hauts faits de la meute : ils se gagnent en pêchant, en cuisinant ce que vous pêchez et en explorant de nouvelles eaux. Chacun n'est annoncé qu'une fois.",
	["Los lugares que pides ver en el mapa desde la Enciclopedia."] = "Les lieux que vous demandez à voir sur la carte depuis l'Encyclopédie.",
	["Los maestros de vuelo de tu facción y los neutrales: verdes si ya los conoces, ámbar con «?» si te falta descubrirlos. Clic: seguirlo con la flecha."] = "Les maîtres de vol de votre faction et les neutres : verts si vous les connaissez déjà, ambre avec « ? » s'il vous reste à les découvrir. Clic : le suivre avec la flèche.",
	["Los magos de Dalaran forman el Kirin Tor, su consejo de sabios."] = "Les mages de Dalaran forment le Kirin Tor, leur conseil des sages.",
	["Los marcos de Curación están apagados"] = "Les cadres de Soins sont désactivés",
	["Los marcos se mueven fuera de combate."] = "Les cadres se déplacent hors combat.",
	["Los marcos, fondos, botones y letras del propio juego, con títulos en oro."] = "Les cadres, fonds, boutons et polices du jeu, avec des titres dorés.",
	["Los mismos marcadores de misiones en el minimapa."] = "Les mêmes marqueurs de quête sur la minicarte.",
	["Los múrlocs hablan con gorgoteos y burbujas: ese «mrglglgl» es su idioma de verdad."] = "Les murlocs parlent en gargouillis et en bulles : ce « mrglglgl », c'est leur vraie langue.",
	["Los nagas y sátiros lanzan escarcha y rayos: interrumpan a los lanzadores primero."] = "Les nagas et les satyres lancent du givre et des éclairs : interrompez d'abord les lanceurs de sorts.",
	["Los nerubianos, arañas gigantes de Rasganorte, pelearon contra el Rey Exánime y perdieron; muchos hoy le sirven."] = "Les Nérubiens, araignées géantes du Norfendre, ont combattu le roi-liche et ont perdu ; beaucoup le servent aujourd'hui.",
	["Los no-muertos de la Plaga no sienten miedo ni cansancio, y por eso es tan difícil detenerlos."] = "Les morts-vivants du Fléau ne ressentent ni peur ni fatigue, et c'est pour ça qu'ils sont si difficiles à arrêter.",
	["Los nodos de la zona que miras, con su nombre, nivel y cuántas veces los recolectaste al pasar el ratón. Clic en uno: la flecha te lleva."] = "Les nœuds de la zone affichée ; survolez-en un pour voir son nom, son niveau et combien de fois vous l'avez récolté. Cliquez sur l'un d'eux : la flèche vous y mène.",
	["Los nodos que se pisarían en pantalla van en un solo pin con su cantidad. Al acercar el mapa se separan."] = "Les nœuds qui se chevaucheraient à l'écran partagent un seul repère avec leur nombre. En zoomant, ils se séparent.",
	["Los nodos que tienes cerca. El punto del rastreo del juego dice si ahora hay algo ahí."] = "Les nœuds près de vous. Le point du pistage du jeu indique s'il y a quelque chose en ce moment.",
	["Los nodos que trae Alfa. Sin esto solo ves los que tú descubriste."] = "Les nœuds fournis avec Alfa. Sans cela, vous ne voyez que ceux que vous avez découverts.",
	["Los números de las habilidades de tu mascota."] = "Les chiffres des techniques de votre familier.",
	["Los números de lo que curas encima de quien recibe."] = "Les chiffres de vos soins au-dessus de celui qui les reçoit.",
	["Los números de los golpes de tu mascota."] = "Les chiffres des coups de mêlée de votre familier.",
	["Los números de tu daño encima de quien golpeas."] = "Les chiffres de vos dégâts au-dessus de celui que vous frappez.",
	["Los oasis de Los Baldíos se están secando y llenando de bestias raras: los Druidas del Colmillo, que salieron de las Cuevas de los Lamentos, los corrompen."] = "Les oasis des Tarides s'assèchent et se remplissent de bêtes étranges : les druides du Croc, sortis des cavernes des Lamentations, les corrompent.",
	["Los objetos se juntan al final de tus bolsas en lugar de al principio."] = "Les objets se regroupent à la fin de vos sacs au lieu du début.",
	["Los orcos Faucedraco siguen en Los Humedales, aunque ya sin la Reina Dragón."] = "Les orcs Gueule-de-dragon sont toujours dans les Paluns, même sans la Reine-dragon.",
	["Los orcos Roca Negra de Rend se adueñaron de la cumbre de la montaña y la llaman su hogar."] = "Les orcs Rochenoire de Rend se sont emparés du sommet de la montagne et l'appellent leur foyer.",
	["Los orcos Roca Negra ocupan una vieja fortaleza humana al este de las montañas."] = "Les orcs Rochenoire occupent une vieille forteresse humaine à l'est des montagnes.",
	["Los orcos llegaron de Draenor corrompidos por la sangre de Mannoroth. Thrall los sacó de los campos de internamiento y fundó la nueva Horda."] = "Les orcs sont venus de Draenor, corrompus par le sang de Mannoroth. Thrall les a sortis des camps d'internement et a fondé la nouvelle Horde.",
	["Los orcos nuevos empiezan en el Valle de los Retos, en Durotar, donde prueban su valor."] = "Les nouveaux orcs commencent dans la vallée des Épreuves, en Durotar, où ils prouvent leur valeur.",
	["Los orcos vienen de Draenor, un mundo que hoy está roto y se llama Terrallende."] = "Les orcs viennent de Draenor, un monde aujourd'hui brisé qui s'appelle l'Outreterre.",
	["Los otros %d puntos del plan llegan con tus próximos niveles."] = "Les %d autres points du plan arrivent avec vos prochains niveaux.",
	["Los peleteros hacen carcajes y bolsas de munición para los cazadores."] = "Les travailleurs du cuir font des carquois et des gibernes pour les chasseurs.",
	["Los portales a pie que puedes usar, con a dónde llevan."] = "Les portails à pied que vous pouvez utiliser, avec leur destination.",
	["Los precios cambian: después de estos días Alfa te recuerda escanear otra vez."] = "Les prix changent : après ce nombre de jours, Alfa vous rappelle de scanner à nouveau.",
	["Los primeros caballeros de la muerte los creó Gul'dan: cuerpos de caballeros humanos caídos con almas de brujos orcos."] = "Gul'dan a créé les premiers chevaliers de la mort : des corps de chevaliers humains tombés avec les âmes de démonistes orcs.",
	["Los puntos de ruta que ponen otros addons, y el comando /way, apuntan la flecha de Alfa. Un addon que espere los ajustes de otro addon de puntos de ruta puede no funcionar con esto encendido."] = "Les points de passage placés par d'autres addons, et la commande /way, dirigent la flèche d'Alfa. Un addon qui attend les réglages d'un autre addon de points de passage peut mal fonctionner avec cette option.",
	["Los puntos de vuelo y de viaje ya se ven en el mapa."] = "Les points de vol et de voyage s'affichent maintenant sur la carte.",
	["Los puntos que ganas en la cuenta también llenan el registro del Legado: premios de aspecto, sin ventaja en el juego. Al salir Forever son un rifle de réplica de Forjaz (juguete), la cría de oso espectral (mascota), el tabardo del oso espectral y las riendas del oso espectral (montura)."] = "Les points gagnés sur le compte remplissent aussi la piste de récompenses de l'Héritage : récompenses cosmétiques, sans avantage en jeu. Au lancement de Forever : une réplique de fusil à air de Forgefer (jouet), le petit ours spectral (mascotte), le tabard de l'ours spectral et les rênes de l'ours spectral (monture).",
	["Los puntos que ganas también llenan el registro del Legado, con premios de aspecto como la cría de oso espectral."] = "Les points que tu gagnes remplissent aussi la piste de récompenses de l'Héritage, avec des récompenses cosmétiques comme le petit ours spectral.",
	["Los raros están apagados (página Descubrir)."] = "Les rares sont désactivés (page Découverte).",
	["Los raros también en el minimapa."] = "Les rares aussi sur la minicarte.",
	["Los recolectaste %d veces en total"] = "Vous les avez récoltés %d fois au total",
	["Los sacerdotes Atal'ai siguieron adorando a Hakkar en secreto. Los desterraron, y levantaron su templo en el Pantano de las Penas."] = "Les prêtres Atal'ai ont continué d'adorer Hakkar en secret. Ils ont été exilés et ont élevé leur temple dans le marais des Chagrins.",
	["Los servicios también en el minimapa."] = "Les services aussi sur la minicarte.",
	["Los señores del terror, como Mal'Ganis, Balnazzar y Varimathras, eran los carceleros que la Legión le puso al Rey Exánime."] = "Les seigneurs de l'effroi, comme Mal'Ganis, Balnazzar et Varimathras, étaient les geôliers que la Légion avait placés auprès du roi-liche.",
	["Los señores elementales servían a los dioses antiguos. Cuando los titanes encerraron a esos dioses, desterraron a los elementales a sus propios planos."] = "Les seigneurs élémentaires servaient les Dieux très anciens. Quand les titans ont emprisonné ces dieux, ils ont banni les élémentaires dans leurs propres plans.",
	["Los sumos sacerdotes de Zul'Gurub tomaron el poder de los loa animales: el murciélago, la serpiente, la araña, la pantera y el tigre."] = "Les grands prêtres de Zul'Gurub ont pris le pouvoir des loa animaux : la chauve-souris, le serpent, l'araignée, la panthère et le tigre.",
	["Los sátiros de Azshara sueltan tela vil, muy buscada por los sastres."] = "Les satyres d'Azshara laissent tomber de la gangrétoffe, très recherchée par les couturiers.",
	["Los talentos confirmados no se quitan gratis: revisa la lista antes de aceptar."] = "Les talents confirmés ne s'enlèvent pas gratuitement : vérifiez la liste avant d'accepter.",
	["Los talentos que siguen en el plan no están en tu árbol o no se pueden tomar todavía. Ponlos a mano en la ventana de talentos del juego o elige otro build."] = "Les prochains talents du plan ne sont pas dans votre arbre ou ne peuvent pas encore être pris. Placez-les à la main dans la fenêtre des talents du jeu ou choisissez un autre build.",
	["Los tauren Tótem Siniestro tienen campamentos en Las Mil Agujas, y no son nada amigables."] = "Les Taurens Totem-Sinistre ont des campements à Mille pointes, et ils ne sont pas du tout amicaux.",
	["Los tauren ayudaron a los Renegados a entrar a la Horda, con la esperanza de encontrarles una cura."] = "Les Taurens ont aidé les Réprouvés à entrer dans la Horde, dans l'espoir de leur trouver un remède.",
	["Los tauren de Viento Libre viven en lo alto de Las Mil Agujas, a salvo de los centauros."] = "Les Taurens de Librevent vivent en haut de Mille pointes, à l'abri des centaures.",
	["Los tauren de Viento Libre viven en lo alto de las agujas, unidas por puentes colgantes, a salvo de los centauros de abajo."] = "Les Taurens de Librevent vivent au sommet des pointes, reliées par des ponts de corde, à l'abri des centaures d'en bas.",
	["Los tauren honran a la Madre Tierra. Dicen que el sol y la luna son sus ojos: An'she y Mu'sha."] = "Les Taurens honorent la Terre-Mère. Ils disent que le soleil et la lune sont ses yeux : An'she et Mu'sha.",
	["Los tauren llaman An'she al sol y Mu'sha a la luna: los ojos de la Madre Tierra."] = "Les Taurens appellent le soleil An'she et la lune Mu'sha : les yeux de la Terre-Mère.",
	["Los tauren nuevos empiezan en el Campamento Narache, en Mulgore."] = "Les nouveaux Taurens commencent au camp Narache, en Mulgore.",
	["Los tauren vivían como nómadas, acosados por los centauros, hasta que Cairne Pezuña de Sangre se alió con Thrall. Con la ayuda de la Horda encontraron su hogar en Mulgore."] = "Les Taurens vivaient en nomades, traqués par les centaures, jusqu'à ce que Cairne Sabot-de-Sang s'allie à Thrall. Avec l'aide de la Horde, ils ont trouvé leur foyer en Mulgore.",
	["Los tesoros también en el minimapa."] = "Les trésors aussi sur la minicarte.",
	["Los titanes dejaron guardianes de piedra y metal en Azeroth. En Uldaman todavía hay uno despierto: Archaedas."] = "Les titans ont laissé des gardiens de pierre et de métal en Azeroth. À Uldaman, l'un d'eux est encore éveillé : Archaedas.",
	["Los titanes le dieron forma a Azeroth y dejaron guardianes y ciudades, como Uldaman, para cuidar su obra."] = "Les titans ont façonné Azeroth et laissé des gardiens et des cités, comme Uldaman, pour veiller sur leur œuvre.",
	["Los titanes son seres colosales que recorren el cosmos poniendo orden en los mundos. Los más famosos forman el Panteón, que guiaba Aman'Thul."] = "Les titans sont des êtres colossaux qui parcourent le cosmos pour mettre de l'ordre dans les mondes. Les plus célèbres forment le Panthéon, que guidait Aman'Thul.",
	["Los titanes usaron este cráter como un jardín de pruebas para la vida; por eso hay dinosaurios y plantas gigantes."] = "Les titans ont utilisé ce cratère comme jardin d'essai pour la vie ; c'est pour ça qu'on y trouve des dinosaures et des plantes géantes.",
	["Los troggs huyen cuando tienen poca vida y traen amigos: deténganlos antes de que escapen."] = "Les troggs fuient quand leur vie est basse et ramènent des amis : arrêtez-les avant qu'ils ne s'échappent.",
	["Los troggs invadieron Gnomeregan, y los gnomos inundaron su propia ciudad de radiación al intentar sacarlos. Fue idea del mekigeniero Termochufe."] = "Les troggs ont envahi Gnomeregan, et les gnomes ont inondé leur propre ville de radiations en essayant de les chasser. C'était l'idée du mekgénieur Thermojoncteur.",
	["Los troggs salieron de las profundidades de Uldaman. Todo indica que son una creación antigua de los titanes que salió mal."] = "Les troggs sont sortis des profondeurs d'Uldaman. Tout indique qu'ils sont une ancienne création des titans qui a mal tourné.",
	["Los trols Lanza Negra conocieron a Thrall en las islas donde naufragó su flota rumbo a Kalimdor. Su líder Sen'jin murió ahí, y desde entonces los guía su hijo Vol'jin."] = "Les trolls Sombrelance ont rencontré Thrall sur les îles où sa flotte a fait naufrage en route vers Kalimdor. Leur chef Sen'jin y est mort, et son fils Vol'jin les guide depuis.",
	["Los trols Lanza Negra empiezan con los orcos, en el Valle de los Retos de Durotar."] = "Les trolls Sombrelance commencent avec les orcs, dans la vallée des Épreuves de Durotar.",
	["Los trols adoran a espíritus llamados loa. Hakkar es uno de ellos, y de los más peligrosos."] = "Les trolls vénèrent des esprits appelés loa. Hakkar en est un, et l'un des plus dangereux.",
	["Los trols de estas tierras descienden de los Amani, el antiguo imperio de los trols del bosque. En Jintha'Alor siguen levantando sus altares."] = "Les trolls de ces terres descendent des Amani, l'ancien empire des trolls des forêts. À Jintha'Alor, ils dressent toujours leurs autels.",
	["Los vendedores de suministros de pesca tienen cañas, lombrices y baratijas."] = "Les vendeurs de fournitures de pêche ont des cannes, des vers et des babioles.",
	["Los worgen son hombres lobo de origen misterioso. Arugal los trajo a Lordaeron. ¡No me confundas con ellos, eh!"] = "Les worgens sont des loups-garous d'origine mystérieuse. Arugal les a amenés à Lordaeron. Ne me confonds pas avec eux, hein !",
	["Los zepelines salen de las torres junto a Orgrimmar hacia Entrañas y hacia Grom'gol, en la Vega de Tuercespina."] = "Les zeppelins partent des tours près d'Orgrimmar vers Fossoyeuse et vers Grom'gol, dans la vallée de Strangleronce.",
	["Los árboles del Legado son tres: Profesiones, Aventura y Recursos. Al salir Forever, cada personaje gasta hasta 16 puntos."] = "Il y a trois arbres de l'Héritage : Métiers, Aventure et Ingéniosité. Au lancement de Forever, chaque personnage dépense jusqu'à 16 points.",
	["Los íconos, los nombres y tu flecha se mueven pegados al mapa al hacer zoom o arrastrar: ya no brincan un píxel."] = "Les icônes, les noms et votre flèche restent collés à la carte quand vous zoomez ou la faites glisser : ils ne sautent plus d'un pixel.",
	["Los últimos Altonato de Kalimdor siguen en La Masacre: se llaman Shen'dralar y cuidan su vieja biblioteca."] = "Les derniers Bien-nés de Kalimdor sont toujours à Hache-tripes : on les appelle les Shen'dralar et ils veillent sur leur vieille bibliothèque.",
	["Los últimos puntos."] = "Les derniers points.",
	["Lothar cayó ante Orgrim Martillo Maldito al pie de la Montaña Roca Negra. Turalyon tomó su lugar y ganó la Segunda Guerra."] = "Lothar est tombé face à Orgrim Marteau-du-Destin au pied du mont Rochenoire. Turalyon a pris sa place et a gagné la Deuxième Guerre.",
	["Luego cópialo con Ctrl+C."] = "Copiez-le ensuite avec Ctrl+C.",
	["Lugar"] = "Position",
	["Lugar conocido: el punto del rastreo del juego dice si ahora hay algo."] = "Endroit connu : le point du pistage du jeu indique s'il y a quelque chose en ce moment.",
	["Lugar de los marcos"] = "Position des cadres",
	["Lugar desconocido"] = "Lieu inconnu",
	["Lugar: %s"] = "Lieu : %s",
	["Luna"] = "Lune",
	["Luz y efectos"] = "Lumière et effets",
	["Lya"] = "Lya",
	["Lya ahora es una loba negra de cuerpo completo, con 39 cuadros de animación: se sienta, corre, se busca la cola, bosteza y duerme enroscada."] = "Lya est maintenant une louve noire en entier, avec 39 images d'animation : elle s'assoit, court, court après sa queue, bâille et dort roulée en boule.",
	["Lya cuenta historias"] = "Lya raconte des histoires",
	["Lya de cuerpo completo"] = "Lya en entier",
	["Lya descansa. La llamas con /alfa lya o /alfa ayuda cuando quieras."] = "Lya se repose. Appelle-la avec /alfa lya ou /alfa ayuda quand tu veux.",
	["Lya en tu pantalla"] = "Lya sur votre écran",
	["Lya encontró un tesoro"] = "Lya a trouvé un trésor",
	["Lya es quien olfatea los raros y los tesoros: su tarjeta trae «Ir de caza», «Su ficha» y «Seleccionarlo»."] = "C’est Lya qui flaire les rares et les trésors : sa carte propose « Partir en chasse », « Sa fiche » et « Le cibler ».",
	["Lya está calladita"] = "Lya se fait toute discrète",
	["Lya está descansando"] = "Lya se repose",
	["Lya fue una gran perrita: noble, leal y siempre al lado de los suyos, la gordita consentida de la casa. Alfa la recuerda así, como la loba que cuida a la manada y nunca deja a nadie atrás."] = "Lya était une merveilleuse petite chienne : noble, loyale et toujours aux côtés des siens, la petite ronde gâtée de la maison. Alfa se souvient d'elle ainsi, comme la louve qui veille sur la meute et n'abandonne jamais personne.",
	["Lya guarda la historia de cada misión que tomas, aunque la aceptes sin leerla. Tú sigue la flecha: ella se acuerda de todo."] = "Lya garde l'histoire de chaque quête que vous prenez, même si vous l'acceptez sans la lire. Vous, suivez la flèche : elle se souvient de tout.",
	["Lya olfateó un raro"] = "Lya a flairé un rare",
	["Lya platica mucho más: lore de Warcraft, datos de cada zona, de tu raza, tu clase y tus profesiones, y consejos de eventos y de farmeo. ¡Y le encantan las salchichas!"] = "Lya bavarde beaucoup plus : lore de Warcraft, anecdotes sur chaque zone, votre race, votre classe et vos métiers, et conseils pour les fêtes et le farm. Et elle adore les saucisses !",
	["Lya recuerda lo que te dijo, tiene una tecla para su botón y te cuenta tu semana de caza y tu mejor día."] = "Lya se souvient de ce qu’elle t’a dit, a une touche pour son bouton et te raconte ta semaine de chasse et ton meilleur jour.",
	["Lya se fue a descansar. Vuelve con /alfa lya."] = "Lya est partie se reposer. Faites-la revenir avec /alfa lya.",
	["Lya se queda calladita una hora. Aquí sigue, cuidándote."] = "Lya reste silencieuse pendant une heure. Elle est toujours là et veille sur vous.",
	["Lya se queda en tu pantalla: consejos cortos, historias y atajos a todo Alfa."] = "Lya reste sur ton écran : conseils courts, histoires et raccourcis vers tout Alfa.",
	["Lya te acompaña"] = "Lya vous accompagne",
	["Lya te dice los avisos"] = "Lya te dit les alertes",
	["Lya te espera"] = "Lya vous attend",
	["Lya te guía, un asistente más sencillo y las guaridas"] = "Lya te guide, une configuration plus simple et les tanières",
	["Lya te lo dice todo"] = "Lya te dit tout",
	["Lya tiene mucho que contar"] = "Lya a beaucoup à raconter",
	["Lya volvió. Dale clic cuando quieras un consejo."] = "Lya est de retour. Cliquez sur elle quand vous voulez un conseil.",
	["Lya vuelve a contarte sus consejos desde el principio."] = "Lya vous redonne ses conseils depuis le début.",
	["Lya vuelve a hablar."] = "Lya reparle.",
	["Lya, la loba de confianza del Alfa"] = "Lya, la louve de confiance de l'Alfa",
	["Lya, la manada y tus récords"] = "Lya, la meute et tes records",
	["Lánzalo antes de la siguiente pelea."] = "Lancez-le avant le prochain combat.",
	["Lánzalo antes de pelear."] = "Lancez-le avant de combattre.",
