	["Panel de estadísticas"] = "Panneau des statistiques",
	["Pantalla de película para capturas y paseos. Solo cambia cómo se ve: no da más FPS."] = "Un écran façon cinéma pour les captures et les balades. Ne change que l'apparence : ne donne pas plus de FPS.",
	["Pantalla gris al morir"] = "Écran gris à la mort",
	["Para abandonar"] = "À abandonner",
	["Para abrirlo con la tecla del mapa, enciende «Abrir el mapa de Alfa con la tecla del mapa» abajo."] = "Pour l'ouvrir avec la touche de la carte, activez « Ouvrir la carte d'Alfa avec la touche de la carte » plus bas.",
	["Para alguien de tu hermandad, agrega su rango."] = "Pour un membre de votre guilde, ajoute son rang.",
	["Para armar la espada legendaria de Thunderaan, el Buscavientos, hacen falta dos ataduras que sueltan Garr y el barón Geddon en el Núcleo de Magma."] = "Pour assembler l'épée légendaire de Thunderaan, le Cherchevent, il faut deux liens que laissent tomber Garr et le baron Geddon dans le Cœur du Magma.",
	["Para cada objeto Alfa compara tres caminos: venderlo al comerciante, ponerlo en la subasta o transformarlo (con una receta que conoces o desencantándolo)."] = "Pour chaque objet, Alfa compare trois options : le vendre au marchand, le mettre aux enchères ou le transformer (avec une recette que vous connaissez ou en le désenchantant).",
	["Para capturas y paseos. No da más FPS."] = "Pour les captures et les balades. Ne donne pas plus de FPS.",
	["Para cerrarle el paso a la Legión, Malfurion y sus aliados destruyeron el Pozo de la Eternidad. La explosión hundió el centro de Kalimdor."] = "Pour barrer la route à la Légion, Malfurion et ses alliés ont détruit le Puits d'éternité. L'explosion a englouti le cœur de Kalimdor.",
	["Para comprar espacio, habla con un banquero."] = "Pour acheter de la place, parlez à un banquier.",
	["Para conservar"] = "À garder",
	["Para cruzar de los Reinos del Este a Kalimdor, toma un barco en el Puerto de Menethil, en Los Humedales."] = "Pour passer des royaumes de l'Est à Kalimdor, prends un bateau au port de Menethil, dans les Paluns.",
	["Para depositar, habla con un banquero."] = "Pour déposer, parlez à un banquier.",
	["Para empezar"] = "Pour commencer",
	["Para encantar necesitas una vara rúnica; con el tiempo la mejoras."] = "Pour enchanter, il te faut un bâtonnet runique ; avec le temps, tu l'améliores.",
	["Para entregar"] = "À rendre",
	["Para gastar"] = "À dépenser",
	["Para invitar a %s a %s: abre «Hermandad y comunidades», elige %s, pulsa «Invitar a miembro» y escribe: %s"] = "Pour inviter %s dans %s : ouvre « Guilde et communautés », choisis %s, clique sur « Inviter un membre » et écris : %s",
	["Para ir de Los Humedales a las Tierras Altas de Arathi cruza el Puente Thandol, pero ojo con los Hierro Negro."] = "Pour aller des Paluns aux hautes-terres d'Arathi, traverse le viaduc de Thandol, mais attention aux Sombrefer.",
	["Para llamar a la manada, deja que te vean en el mapa (La Jauría)."] = "Pour appeler la meute, laisse-la te voir sur la carte (La Jauría).",
	["Para llegar a la Fuente del Sol, la Plaga de Arthas arrasó Quel'Thalas y su capital, Lunargenta."] = "Pour atteindre le Puits de soleil, le Fléau d'Arthas a ravagé Quel'Thalas et sa capitale, Lune-d'argent.",
	["Para lo que elegiste no hay uno con este estilo: Alfa usa el más cercano."] = "Il n'y en a pas avec ce style pour votre choix : Alfa utilise le plus proche.",
	["Para mi nivel (±3)"] = "Pour mon niveau (±3)",
	["Para minar torio, el Cráter de Un'Goro y Cuna del Invierno tienen muchas vetas."] = "Pour miner du thorium, le cratère d'Un'Goro et le Berceau-de-l'Hiver ont beaucoup de filons.",
	["Para mí"] = "Pour moi",
	["Para no chocar con él, Alfa no reemplaza tus bolsas mientras esté activo. Igual puedes abrir la ventana de Alfa desde aquí."] = "Pour éviter les conflits, Alfa ne remplace pas vos sacs tant qu'il est activé. Vous pouvez quand même ouvrir la fenêtre d'Alfa d'ici.",
	["Para no moverla sin querer. Sin bloquear, arrástrala a donde quieras."] = "Pour ne pas la déplacer par erreur. Déverrouillée, faites-la glisser où vous voulez.",
	["Para no ver dos veces a tu grupo. Se cambia fuera de combate."] = "Pour ne pas voir votre groupe en double. Se change hors combat.",
	["Para que no choquen, Alfa no toma tu tecla ni cambia tus ajustes. Desactiva uno de los dos en la lista de addons (pantalla de personajes) y recarga. Si dejas Alfa, tomará sola la tecla que usabas en el otro addon."] = "Pour éviter les conflits, Alfa ne prend pas votre touche et ne modifie pas vos réglages. Désactivez l'un des deux dans la liste des addons (écran de sélection des personnages) et rechargez. Si vous gardez Alfa, il reprendra tout seul la touche que vous utilisiez dans l'autre addon.",
	["Para que no dejes botín tirado por falta de espacio."] = "Pour ne jamais laisser de butin faute de place.",
	["Para quien prefiere seleccionar con el izquierdo: la cura de ese clic pasa al botón central. Se vuelve a aplicar tu preajuste."] = "Pour ceux qui préfèrent cibler au clic gauche : le soin de ce clic passe au bouton central. Votre préréglage est réappliqué.",
	["Para recoger ahora"] = "À récupérer maintenant",
	["Para subir de nivel"] = "Avant le prochain niveau",
	["Para subir solo, el daño de las sombras ayuda mucho: los hechizos que dañan con el tiempo trabajan por ti."] = "Pour monter de niveau en solo, les dégâts d'Ombre aident beaucoup : les sorts de dégâts sur la durée travaillent pour toi.",
	["Para tela de nivel bajo, los Defias de los Páramos de Poniente sueltan lino y lana a montones."] = "Pour du tissu de bas niveau, les Défias de la marche de l'Ouest laissent tomber du lin et de la laine à la pelle.",
	["Para templar la espada élfica Quel'Serrar hay que dejarla en el piso y que Onyxia le eche su aliento de fuego encima."] = "Pour tremper l'épée elfique Quel'Serrar, il faut la poser au sol et laisser Onyxia souffler son feu dessus.",
	["Para ti"] = "Pour vous",
	["Para ti ahora"] = "Pour vous maintenant",
	["Para tu %s"] = "Pour votre %s",
	["Para tu habilidad conviene pescar en: %s."] = "Pour votre compétence, mieux vaut pêcher à : %s.",
