	["Para ver las guaridas de la manada, deja que te vean en el mapa."] = "Pour voir les tanières de la meute, laisse-la te voir sur la carte.",
	["Para ver y romper los tótems enemigos."] = "Pour repérer et détruire les totems ennemis.",
	["Para verlas mejor"] = "Pour mieux les voir",
	["Para volver a acumularla, descansa (o cierra sesión) en una posada o una ciudad."] = "Pour en accumuler à nouveau, reposez-vous (ou déconnectez-vous) dans une auberge ou une ville.",
	["Parada"] = "Parade",
