	["Revancha más fuerte y puede aturdir."] = "Vengeance plus forte et pouvant étourdir.",
	["Revancha pega fuerte y puede aturdir: tu golpe principal al subir."] = "Vengeance frappe fort et peut étourdir : votre coup principal pour monter.",
	["Revancha pega más y puede aturdir: tu mejor golpe de amenaza."] = "Vengeance frappe plus fort et peut étourdir : votre meilleur coup de menace.",
	["Revancha: barata y con mucha amenaza tras bloquear o esquivar."] = "Vengeance : peu coûteuse et beaucoup de menace après un blocage ou une esquive.",
	["Reveladas"] = "Révélées",
	["Reveladas con otro tono"] = "Révélées avec un autre ton",
	["Reverencia"] = "Révérence",
	["Revisa la lista antes de abandonar."] = "Vérifiez la liste avant d'abandonner.",
	["Revisa lo que elegiste. Cada cosa se cambia aquí con «Cambiar» o después en Ajustes."] = "Vérifiez vos choix. Chaque point se change ici avec « Changer » ou plus tard dans les Réglages.",
	["Revisa miles de misiones para elegir las que sí puedes tomar: tarda unos segundos."] = "Il passe en revue des milliers de quêtes pour choisir celles que vous pouvez vraiment prendre : cela prend quelques secondes.",
	["Revisa tu equipo al subir de nivel: una mejora pequeña también cuenta."] = "Vérifie ton équipement en montant de niveau : une petite amélioration compte aussi.",
	["Revisando tu registro..."] = "Vérification de votre journal...",
	["Revisión rápida"] = "Vérification rapide",
	["Rexxar, el señor de las bestias, recorre los caminos de Desolace con su osa Misha."] = "Rexxar, le seigneur des bêtes, parcourt les routes de Désolace avec son ourse Misha.",
	["Rexxar, mitad orco y mitad ogro, es un señor de las bestias que ayudó a fundar Durotar. Siempre lo acompaña su osa Misha."] = "Rexxar, mi-orc mi-ogre, est un seigneur des bêtes qui a aidé à fonder Durotar. Son ourse Misha est toujours à ses côtés.",
	["Reír"] = "Rire",
	["Ritmo: %s XP por hora; subes de nivel en %s."] = "Rythme : %s XP par heure ; prochain niveau dans %s.",
	["Roble"] = "Chêne",
	["Rocal es el gran bastión de la Horda en el sur de los Reinos del Este."] = "Pierrêche est le grand bastion de la Horde dans le sud des royaumes de l'Est.",
	["Rojo"] = "Rouge",
	["Rosa"] = "Rose",
	["Rueda abajo"] = "Molette vers le bas",
	["Rueda arriba"] = "Molette vers le haut",
	["Rueda del ratón: acercar o alejar donde está el cursor. Arrastrar: mover el mapa (al soltar rápido sigue un poco). Doble clic: acercar."] = "Molette : zoomer ou dézoomer sous le curseur. Glisser : déplacer la carte (relâchez vite et elle glisse un peu). Double-clic : zoomer.",
	["Rueda: zoom  ·  Arrastra: mover  ·  Clic derecho: marcador  ·  Ctrl+clic: llévame"] = "Molette : zoom  ·  Glisser : déplacer  ·  Clic droit : marqueur  ·  Ctrl+clic : m'y emmener",
	["Rugir"] = "Rugir",
	["Rut'theran es el muelle al pie del árbol; de ahí un portal te sube a Darnassus."] = "Rut'theran est le quai au pied de l'arbre ; de là, un portail te monte à Darnassus.",
	["Ruta"] = "Itinéraire",
	["Ruta %d/%d: %s"] = "Itinéraire %d/%d : %s",
	["Ruta borrada"] = "Itinéraire effacé",
	["Ruta en el minimapa"] = "Itinéraire sur la minicarte",
	["Ruta en marcha"] = "Itinéraire en cours",
	["Ruta importada"] = "Itinéraire importé",
	["Ruta lista en %s: %s"] = "Itinéraire prêt dans %s : %s",
	["Rutas propias"] = "Nos propres itinéraires",
	["Saca %d para la primera maestría (%s)."] = "Pêchez-en %d pour la première maîtrise (%s).",
	["Saca 15 capturas seguidas sin que se te escape ninguna."] = "Faites 15 prises d'affilée sans qu'aucune ne s'échappe.",
	["Saca 25 capturas de bancos de peces."] = "Faites 25 prises dans des bancs de poissons.",
	["Saca tu primera captura del agua."] = "Sortez votre première prise de l'eau.",
	["Saca una captura en Tuercespina durante el concurso de pesca."] = "Faites une prise à Strangleronce pendant le concours de pêche.",
	["Sacarla"] = "La retirer",
	["Sacerdote"] = "Prêtre",
	["Sagrado"] = "Sacré",
	["Sagrado para subir"] = "Sacré pour monter",
	["Sal de combate y vuelve a intentarlo."] = "Sortez du combat et réessayez.",
	["Sal de tu grupo primero: el juego te pasa a la guarida de quien te invita."] = "Quitte d’abord ton groupe : le jeu t’emmène dans la tanière de celui qui t’invite.",
	["Sale en aguas abiertas; los datos del juego no dicen dónde. Tu diario lo anota cuando lo saques."] = "Il vient des eaux libres ; les données du jeu ne disent pas où. Votre journal le note quand vous le pêchez.",
	["Salen de tu registro. Para hacerlas otra vez tendrías que volver a pedirlas."] = "Elles quittent votre journal. Pour les refaire, il faudrait les reprendre.",
	["Salidas de zona"] = "Sorties de zone",
	["Salir del grupo"] = "Quitter le groupe",
	["Salir del modo limpio"] = "Quitter le mode épuré",
	["Saltar la charla de una sola opción"] = "Passer les dialogues à une seule option",
	["Saltar las misiones grises"] = "Passer les quêtes grises",
	["Saltarla"] = "La sauter",
	["Salud cada 5 s"] = "Vie toutes les 5 s",
	["Saludar"] = "Saluer",
	["Saludos y diálogos de los PNJ"] = "Salutations et dialogues des PNJ",
	["Sanación"] = "Soins",
	["Sanador"] = "Soigneur",
	["Sangrado fuerte desde el nivel 13; lo necesitas para Heridas profundas."] = "Saignement puissant dès le niveau 13 ; il vous le faut pour Blessures profondes.",
	["Sangrado fuerte; abre Heridas profundas."] = "Saignement puissant ; ouvre Blessures profondes.",
	["Sangre fría: tu siguiente remate es crítico seguro."] = "Sang froid : votre prochain coup de grâce est un critique assuré.",
	["Sapphiron, el dragón de escarcha de Naxxramas, fue un dragón azul antes de que la Plaga lo levantara."] = "Saphiron, le wyrm de givre de Naxxramas, était un dragon bleu avant que le Fléau ne le relève.",
	["Sargeras fue el gran campeón del Panteón. De tanto pelear contra demonios concluyó que la creación no tenía remedio, y fundó la Legión Ardiente."] = "Sargeras était le grand champion du Panthéon. À force de combattre les démons, il a conclu que la création n'avait pas de remède, et il a fondé la Légion ardente.",
	["Sastrería"] = "Couture",
	["Sastrería hace tu ropa con lo que cae en mazmorras, y Encantamiento deshace lo que no usas y mejora tu equipo."] = "La Couture fabrique vos vêtements avec ce qui tombe en donjon, et l'Enchantement désenchante ce que vous n'utilisez pas et améliore votre équipement.",
	["Sastrería y Encantamiento: tu equipo siempre al día."] = "Couture et Enchantement : votre équipement toujours à jour.",
	["Scholomance, en la isla de Caer Darrow, es la escuela donde la Plaga enseña nigromancia. Antes fue el hogar de la familia Barov."] = "Scholomance, sur l'île de Caer Darrow, est l'école où le Fléau enseigne la nécromancie. C'était autrefois la demeure de la famille Barov.",
	["Se abandona con «Abandonar marcadas», que pide confirmación."] = "Elle s'abandonne avec « Abandonner les cochées », qui demande une confirmation.",
	["Se abre a nivel %d: te faltan %d niveles. Mientras, sigue tu ruta."] = "S'ouvre au niveau %d : encore %d niveaux. En attendant, suivez votre itinéraire.",
	["Se abre al salir de combate."] = "Elle s'ouvre à la fin du combat.",
	["Se abre al terminar %s."] = "S'ouvre après %s.",
	["Se abren con la B. Elige la vista (todo junto, por categorías o por bolsa), busca por nombre o nivel y arrastra tus bolsas en su barra para cambiarlas."] = "Ils s'ouvrent avec B. Choisissez la vue (tout ensemble, par catégorie ou par sac), cherchez par nom ou niveau et faites glisser vos sacs sur leur barre pour les remplacer.",
	["Se acabaron los textos cortados con «…» en Hoy, La Jauría, Buscar cerca y la Enciclopedia."] = "Fini les textes coupés par « … » dans Aujourd'hui, La Jauría, Chercher à proximité et l'Encyclopédie.",
	["Se acabó el aviso «Alfa_Builds se ha bloqueado…»: la ventana de talentos, el clic para lanzar y el Legado ahora los abre el juego, y tus hechizos se lanzan sin problema desde el libro."] = "Fini le message « Alfa_Builds a été bloqué… » : la fenêtre des talents, le lancement par clic et l'Héritage sont maintenant ouverts par le jeu, et vos sorts se lancent sans problème depuis le grimoire.",
	["Se acabó tu XP descansada"] = "Votre XP de repos est épuisée",
	["Se acelera a sí mismo y lanza rayos: interrúmpelo."] = "Il s'accélère et lance des éclairs : interrompez-le.",
	["Se acelera a sí mismo: interrúmpelo si puedes."] = "Il s'accélère : interrompez-le si vous le pouvez.",
	["Se activó Claridad: tu siguiente hechizo es gratis."] = "Idées claires activé : votre prochain sort est gratuit.",
	["Se activó Claridad: tus Misiles arcanos salen gratis."] = "Idées claires activé : vos Projectiles des arcanes sont gratuits.",
	["Se activó Trance de las Sombras: tu Descarga de las Sombras es instantánea."] = "Transe de l'ombre activée : votre Trait de l'ombre est instantané.",
	["Se agregó el sonido %d a tu lista."] = "Son %d ajouté à votre liste.",
	["Se aplica al salir de combate."] = "S'applique à la sortie du combat.",
	["Se aprende con %s"] = "S'apprend avec %s",
	["Se borra el progreso de mazmorras de este personaje. No se puede deshacer."] = "La progression des donjons de ce personnage est effacée. Impossible d'annuler.",
	["Se borran las sesiones guardadas de este personaje. La sesión de ahora sigue contando."] = "Les sessions enregistrées de ce personnage sont effacées. La session en cours continue de compter.",
	["Se borran las sesiones, las zonas y los objetos de este personaje. No se puede deshacer."] = "Les sessions, les zones et les objets de ce personnage sont effacés. Impossible d'annuler.",
	["Se borran los %d marcadores de todos tus personajes. No se puede deshacer."] = "Les %d marqueurs de tous vos personnages sont effacés. Impossible d'annuler.",
	["Se borran los jefes vencidos, las veces completada y el botín anotado de %s para este personaje."] = "Les boss vaincus, le nombre de fois terminé et le butin noté de %s sont effacés pour ce personnage.",
	["Se borran los precios guardados de la subasta de este reino y facción. Tus recetas se quedan."] = "Les prix enregistrés de l'hôtel des ventes pour ce royaume et cette faction sont effacés. Vos recettes restent.",
	["Se borran todas las peleas guardadas, también en la ventana del medidor del juego."] = "Tous les combats enregistrés sont effacés, y compris dans la fenêtre du compteur du jeu.",
	["Se borran tus sesiones, tu diario, tus logros y tus metas de este personaje. Tu habilidad de pesca no cambia."] = "Les sessions, le journal, les hauts faits et les objectifs de ce personnage sont effacés. Votre compétence de pêche ne change pas.",
	["Se carga al salir de combate"] = "Se charge à la sortie du combat",
	["Se cerró la subasta antes de recibir los precios. Vuelve a intentarlo después."] = "L'hôtel des ventes s'est fermé avant de recevoir les prix. Réessayez plus tard.",
	["Se cerró la ventana de clic para lanzar de Blizzard. Vuelve a pulsar «Abrir clic para lanzar» para abrirla."] = "La fenêtre de lancement par clic de Blizzard s'est fermée. Cliquez de nouveau sur « Ouvrir le lancement par clic » pour l'ouvrir.",
	["Se cumple al llegar a ese nivel."] = "Rempli quand vous atteignez ce niveau.",
	["Se cura a sí mismo: interrumpe su curación."] = "Il se soigne : interrompez son soin.",
	["Se cura comiendo: mátenlo rápido."] = "Il se soigne en mangeant : tuez-le vite.",
	["Se cura: interrúmpelo."] = "Il se soigne : interrompez-le.",
	["Se descubren todos los jefes de %s, como si la hubieras terminado. Si te equivocas, puedes olvidar tu progreso aquí."] = "Tous les boss de %s sont révélés, comme si vous l'aviez terminé. En cas d'erreur, vous pouvez oublier votre progression ici.",
	["Se detuvo al cerrar el banco: guardaste %d y faltaron %d."] = "Interrompu à la fermeture de la banque : %d rangés et %d restants.",
	["Se detuvo al entrar en combate: guardaste %d y faltaron %d."] = "Interrompu à l'entrée en combat : %d rangés et %d restants.",
	["Se enfurece al final: guarden su mejor daño."] = "Il devient enragé à la fin : gardez vos meilleurs dégâts.",
	["Se enfurece con poca vida: termínenlo rápido."] = "Il devient enragé quand sa vie est basse : achevez-le vite.",
	["Se enfurece y pega más fuerte con el tiempo: mátenlo rápido."] = "Il s'énerve et frappe de plus en plus fort : tuez-le vite.",
	["Se entrega con %s"] = "À rendre à %s",
	["Se entrega dentro"] = "Se rend à l'intérieur",
	["Se escapó"] = "Échappé",
	["Se fabrica"] = "Fabriqué",
	["Se marcan como chatarra"] = "Marqués comme camelote",
	["Se me antoja un buen filete de jabalí. Solo digo."] = "J'ai bien envie d'un steak de sanglier. Je dis ça comme ça.",
	["Se pelea bajo el agua: vigila tu barra de respiración y sube a tomar aire si hace falta."] = "Le combat a lieu sous l'eau : surveillez votre barre de respiration et remontez prendre de l'air si besoin.",
	["Se pesca"] = "Pêché",
	["Se protege con su escudo y aturde: ataquen a los otros dos primero."] = "Il se protège avec son bouclier et étourdit : attaquez d'abord les deux autres.",
	["Se puede al salir de combate."] = "Possible à la fin du combat.",
	["Se puede anunciar al salir de combate."] = "Vous pourrez annoncer à la sortie du combat.",
	["Se puede enviar ahora: %s"] = "Envoi possible maintenant : %s",
	["Se pueden conseguir"] = "Obtenables",
	["Se pusieron %d de %d opciones"] = "%d options réglées sur %d",
	["Se queda en el modo limpio."] = "Reste en mode épuré.",
	["Se quita de tu lista. Si lo necesitas otra vez, vuelve a importar su cadena."] = "Il est retiré de votre liste. Si vous en avez de nouveau besoin, réimportez sa chaîne.",
	["Se quitan los nodos que anotaste al recolectar y cuántas veces los recolectaste. La base incluida se queda. No se puede deshacer."] = "Les nœuds notés pendant vos récoltes et le nombre de fois où vous les avez récoltés sont supprimés. La base incluse reste. Impossible d'annuler.",
	["Se quitó el sonido %d de tu lista."] = "Son %d retiré de votre liste.",
	["Se saltan (no están en tu árbol): %s."] = "Ignorés (absents de votre arbre) : %s.",
	["Se teletransporta a las orillas de la sala: si peleas cuerpo a cuerpo, síguelo."] = "Il se téléporte aux bords de la salle : si vous combattez au corps à corps, suivez-le.",
	["Se toma dentro de la mazmorra: ahí la verás."] = "Elle se prend dans le donjon : vous la verrez là-bas.",
	["Se ve después de reiniciar los gráficos."] = "Visible après un redémarrage des graphismes.",
	["Se vende ahora"] = "Vendu maintenant",
	["Se vende en"] = "Vendu par",
	["Se vende en %s cada uno."] = "Se vend %s pièce.",
	["Seccionar puede inmovilizar al rival: no se te escapa."] = "Brise-genou peut immobiliser l'adversaire : il ne vous échappe pas.",
	["Seccionar puede inmovilizar: nadie se te escapa para traer amigos."] = "Brise-genou peut immobiliser : personne ne s'échappe pour aller chercher des amis.",
	["Secundaria"] = "Secondaire",
	["Secundaria [mano]"] = "Main gauche",
	["Sed de sangre: tu golpe más fuerte, cada vez que esté listo."] = "Sanguinaire : votre coup le plus puissant, dès qu'il est prêt.",
	["Seguimiento"] = "Suivi",
	["Seguir"] = "Suivre",
	["Seguir (flecha y ruta)"] = "Suivre (flèche et itinéraire)",
	["Seguir a %s"] = "Suivre %s",
	["Seguir con %s"] = "Continuer avec %s",
	["Seguir el terreno"] = "Suivre le terrain",
	["Seguir esta guía"] = "Suivre ce guide",
	["Seguir esta ruta"] = "Suivre cet itinéraire",
	["Seguir este build"] = "Suivre ce build",
	["Seguir este plan"] = "Suivre ce plan",
	["Seguir jugando"] = "Continuer à jouer",
	["Seguir muestra tu guía y la flecha, y cierra esta ventana para que las veas."] = "« Suivre » affiche votre guide et la flèche, et ferme cette fenêtre pour que vous les voyiez.",
	["Seguir por aquí"] = "Passer par ici",
	["Seguir ruta"] = "Suivre l'itinéraire",
	["Seguir sola con la siguiente guía"] = "Continuer tout seul avec le guide suivant",
	["Seguir un build de %s"] = "Suivre un build %s",
	["Segundos junto a la barra"] = "Secondes à côté de la barre",
	["Según su leyenda, los jabaespines nacieron de la sangre de Agamaggan, el gran jabalí semidiós. Por eso viven entre espinas gigantes."] = "Selon leur légende, les huran sont nés du sang d'Agamaggan, le grand sanglier demi-dieu. C'est pourquoi ils vivent parmi des épines géantes.",
	["Seleccionar objetivo"] = "Cibler",
	["Seleccionar para copiar"] = "Sélectionner pour copier",
	["Seleccionar todo"] = "Tout sélectionner",
	["Seleccionarlo"] = "Le cibler",
	["Sello"] = "Sceau",
	["Sepia"] = "Sépia",
	["Servicio"] = "Service",
	["Servicios"] = "Services",
	["Servicios en el minimapa"] = "Services sur la minicarte",
	["Será una mejora más adelante"] = "Ce sera une amélioration plus tard",
	["Sesiones anteriores"] = "Sessions précédentes",
	["Sesiones que guarda el diario"] = "Sessions conservées dans le journal",
	["Sesiones, diario, logros y metas de este personaje. No se puede deshacer."] = "Sessions, journal, hauts faits et objectifs de ce personnage. Impossible à annuler.",
	["Sesión de pesca nueva."] = "Nouvelle session de pêche.",
	["Señalar"] = "Montrer du doigt",
	["Señor de las aguas"] = "Seigneur des eaux",
	["Si Toxic, el fundador de La Jauría, anda cerca, Alfa te avisa para que lo saludes."] = "Si Toxic, le fondateur de La Jauría, est dans le coin, Alfa te prévient pour que tu le salues.",
	["Si aguantas bien, usa Golpe heroico con la ira sobrante para más amenaza."] = "Si vous tenez bien, utilisez Frappe héroïque avec la rage en trop pour plus de menace.",
	["Si algo sale mal, tu habilidad para desaparecer te saca de la pelea. Úsala antes de que sea tarde."] = "Si ça tourne mal, ta capacité à disparaître te sort du combat. Utilise-la avant qu'il ne soit trop tard.",
	["Si alguien de la manada te pasa uno, impórtalo y Alfa te guía con él punto por punto."] = "Si quelqu'un de la meute vous en donne un, importez-le et Alfa vous guide point par point.",
	["Si alguien huye, puede traer a más presos: deténganlo con un ataque que lo frene."] = "Si quelqu'un s'enfuit, il peut ramener d'autres prisonniers : arrêtez-le avec une attaque qui ralentit.",
	["Si alguna vez ves salchichas en una posada, guárdame una… o dos."] = "Si tu vois des saucisses dans une auberge, garde-m'en une… ou deux.",
	["Si bajas por el Gran Elevador, verás por qué se llama así: cientos de agujas de roca."] = "Si tu descends par le Grand ascenseur, tu verras pourquoi l'endroit s'appelle ainsi : des centaines de pointes rocheuses.",
	["Si en estas fechas ves calabazas en las posadas, es Halloween: los posaderos te dan dulces con truco o trato, y a veces un disfraz."] = "Si tu vois des citrouilles dans les auberges en cette saison, c'est la Sanssaint : les aubergistes te donnent des friandises pour « des bonbons ou un sort », et parfois un costume.",
	["Si en estas fechas ves faroles y fuegos artificiales, es el Festival Lunar: visita a los Ancestros por el mundo, que cada uno te da una moneda."] = "Si tu vois des lanternes et des feux d'artifice en cette saison, c'est la fête lunaire : rends visite aux Anciens à travers le monde, chacun te donne une pièce.",
	["Si en febrero las ciudades huelen a perfume, es «Amor en el aire»: la gente reparte regalos y hasta los guardias reciben detalles."] = "Si les villes sentent le parfum en février, c'est « De l'amour dans l'air » : les gens distribuent des cadeaux et même les gardes en reçoivent.",
	["Si encuentras un hueso, es mío. ¿Trato hecho?"] = "Si tu trouves un os, il est à moi. Marché conclu ?",
	["Si eres desollador, las zonas llenas de bestias, como raptores, kodos o felinos, te dan cuero sin parar."] = "Si tu es dépeceur, les zones pleines de bêtes, comme les raptors, les kodos ou les félins, te donnent du cuir sans arrêt.",
	["Si está fuera de tu alcance, su marco se ve más tenue."] = "S'il est hors de votre portée, son cadre est plus pâle.",
	["Si fabricas para otros, cobra justo: la gente vuelve y te recomienda."] = "Si tu fabriques pour les autres, fais un prix juste : les gens reviennent et te recommandent.",
	["Si hoy cuesta, mañana sale. Aquí sigo contigo."] = "Si c'est dur aujourd'hui, ça ira demain. Je suis toujours là avec toi.",
	["Si juegas sin grupo, la ventana se esconde."] = "Si vous jouez sans groupe, la fenêtre se masque.",
	["Si la pelea va mal, desvanécete y vuelve a empezar."] = "Si le combat tourne mal, utilisez Disparition et recommencez.",
	["Si la recompensa tiene varias opciones, eliges tú."] = "Si la récompense propose plusieurs choix, c'est vous qui choisissez.",
	["Si la terminas"] = "Si vous la terminez",
	["Si la vida baja de la mitad y el sanador no llega, usa Último recurso."] = "Si votre vie passe sous la moitié et que le soigneur ne suit pas, utilisez Dernier rempart.",
	["Si le haces el gesto de gallina a una gallina de granja muchas veces, a veces te pide ayuda... y la historia termina en mascota."] = "Si tu fais l'emote poulet à une poule de ferme assez de fois, elle te demande parfois de l'aide... et l'histoire se termine par une mascotte.",
	["Si llega a 0 % se rompe y deja de darte sus estadísticas. Repara cuanto antes con un herrero o un vendedor que repare."] = "Si sa durabilité tombe à 0 % sans réparation, la pièce se brise et ne donne plus ses statistiques. Réparez dès que possible chez un forgeron ou un marchand qui répare.",
	["Si llegas a exaltado con otra raza de tu bando, te venden sus monturas. ¡Un kodo para un orco o un sable de la noche para un humano!"] = "Si tu deviens exalté auprès d'une autre race de ta faction, elle te vend ses montures. Un kodo pour un orc ou un sabre-de-nuit pour un humain !",
	["Si llevas puesto el abalorio del Alba Argenta, los no-muertos de las Tierras de la Peste sueltan piedras que cambias por reputación y fichas."] = "Si tu portes le bijou de l'Aube d'argent, les morts-vivants des Maleterres laissent tomber des pierres à échanger contre de la réputation et des insignes.",
	["Si lo que te dan mejora tu equipo, te lo pones al salir de combate."] = "Si ce que vous recevez améliore votre équipement, vous l'équipez en sortant du combat.",
	["Si moviste los avisos y ya no los encuentras."] = "Si vous avez déplacé les alertes et ne les trouvez plus.",
	["Si mueres seguido, cambia al estilo Tranquilo."] = "Si vous mourez souvent, passez au style Prudent.",
	["Si necesitas silencio, con clic derecho me callas un rato."] = "Si tu as besoin de calme, un clic droit me fait taire un moment.",
	["Si no eres druida, al Claro de la Luna se llega por los túneles de los Fauces de Madera, desde Frondavil."] = "Si tu n'es pas druide, on rejoint Reflet-de-Lune par les tunnels des Grumegueules, depuis Gangrebois.",
	["Si no tienes ninguna abierta, abre la recomendada para tu nivel."] = "Si vous n'en avez aucun d'ouvert, ouvre celui recommandé pour votre niveau.",
	["Si nos perdemos en %s, tú lees el mapa y yo sigo el rastro."] = "Si on se perd à %s, tu lis la carte et moi je suis la piste.",
	["Si peleas de lejos, quédate lejos de ella."] = "Si vous combattez à distance, restez loin d'elle.",
	["Si quieres matar más rápido en solitario, cambia a Armas cuando tengas oro para reiniciar."] = "Si vous voulez tuer plus vite en solo, passez à Armes quand vous aurez l'or pour réinitialiser vos talents.",
	["Si quieres, tu personaje aparece en el mapa del juego de los lobos que usan Alfa, y ellos en el tuyo: quién anda cerca, dónde y, con un clic, la flecha te lleva. Solo es el lugar de tu personaje dentro de WoW, nunca tu ubicación real. Tu grupo se ve siempre."] = "Si vous le voulez, votre personnage apparaît sur la carte du jeu des loups qui utilisent Alfa, et eux sur la vôtre : qui est dans le coin, où, et d'un clic la flèche vous y mène. C'est seulement l'emplacement de votre personnage dans WoW, jamais votre position réelle. Votre groupe est toujours visible.",
	["Si sigues el consejo"] = "Si vous suivez le conseil",
	["Si sigues la cadena del mariscal Windsor, en Ventormenta destaparás quién es en realidad Lady Prestor."] = "Si tu suis la chaîne du maréchal Windsor, tu démasqueras à Hurlevent qui est vraiment dame Prestor.",
	["Si sigues la historia del Templo Sumergido, en el pantano te espera Itharius, un dragón verde."] = "Si tu suis l'histoire du temple englouti, Itharius, un dragon vert, t'attend dans le marais.",
	["Si sigues los consejos"] = "Si vous suivez les conseils",
	["Si sigues los consejos ganas %s"] = "En suivant les conseils, vous gagnez %s",
	["Si te alcanzan, usa tus golpes cuerpo a cuerpo y aléjate otra vez."] = "S'ils vous rattrapent, utilisez vos coups au corps à corps et éloignez-vous de nouveau.",
	["Si te baja mucho la vida, cambia a actitud defensiva: tu ira no se pierde."] = "Si votre vie baisse beaucoup, passez en posture défensive : vous ne perdez pas votre rage.",
	["Si te invitan a su grupo, acepta con el botón del juego: el juego te pasa a su guarida al rato."] = "S’ils t’invitent dans leur groupe, accepte avec le bouton du jeu : le jeu t’emmène dans leur tanière peu après.",
	["Si te pegan mientras te vendas, se corta: aléjate un poco antes de usarla."] = "Si on te frappe pendant un bandage, il s'interrompt : éloigne-toi un peu avant de l'utiliser.",
	["Si te quedas sin lanzar"] = "Si vous arrêtez de lancer",
	["Si te sobra un pedacito de carne, aquí hay una panza que lo recibe con gusto."] = "S'il te reste un petit bout de viande, il y a ici un ventre qui l'accueillera avec plaisir.",
	["Si tienes poco tiempo, si no tienes con quién jugar o quién te ayude, puedes apoyarte en Alfa y en Lya en tu travesía."] = "Si vous avez peu de temps, personne avec qui jouer ou pour vous aider, vous pouvez compter sur Alfa et Lya pendant votre périple.",
	["Si tu caña no tiene cebo, tu tecla pone el mejor que tengas (o el que prefieras) antes de lanzar."] = "Si votre canne n'a pas d'appât, votre touche met le meilleur que vous ayez (ou votre préféré) avant de lancer.",
	["Si tu objetivo es un jugador, su fondo toma el color de su clase en lugar del de su reacción."] = "Si votre cible est un joueur, son fond prend la couleur de sa classe au lieu de celle de sa réaction.",
	["Si tu rango lo permite, la hermandad paga y tu dinero pone el resto."] = "Si votre rang le permet, la guilde paie et votre argent complète le reste.",
	["Si tú o tus personajes pueden"] = "Si vous ou vos personnages le pouvez",
	["Si un día ganamos mucho oro, yo ya sé en qué gastarlo: salchichas."] = "Si un jour on gagne beaucoup d'or, je sais déjà comment le dépenser : en saucisses.",
	["Si un enemigo te persigue, no corras: acércate al tanque."] = "Si un ennemi vous poursuit, ne fuyez pas : rapprochez-vous du tank.",
	["Si un enemigo viene hacia ti, llévalo hacia el tanque: no corras lejos."] = "Si un ennemi vient vers vous, amenez-le au tank : ne courez pas loin.",
	["Si un lugar está lleno de jugadores farmeando lo mismo, cámbiate de zona: te rinde más."] = "Si un endroit est bondé de joueurs qui farment la même chose, change de zone : ça rapporte plus.",
	["Si un monstruo esquiva, usa Abrumar enseguida (Alfa te avisa)."] = "Si un monstre esquive, utilisez Fulgurance tout de suite (Alfa vous prévient).",
	["Si una misión se pone difícil, pide ayuda en el chat. En manada todo pesa menos."] = "Si une quête devient difficile, demande de l'aide dans la discussion. En meute, tout pèse moins lourd.",
	["Si una subasta no se vende, pierdes el depósito: no pongas precios fuera de la realidad."] = "Si une enchère ne se vend pas, tu perds le dépôt : ne fixe pas de prix irréalistes.",
	["Si vendes todo al comerciante"] = "Si vous vendez tout au marchand",
	["Si ves a otro lobo por ahí, salúdalo de mi parte."] = "Si tu vois un autre loup dans le coin, salue-le de ma part.",
	["Si ves carpas de colores en Villadorada o en Mulgore, llegó la Feria de la Luna Negra: hay juegos, premios y cartas que se juntan en mazos."] = "Si tu vois des tentes colorées à Comté-de-l'Or ou en Mulgore, la Foire de Sombrelune est arrivée : il y a des jeux, des prix et des cartes à réunir en jeux complets.",
	["Si viajas con un mago, pídele un portal a la capital: te ahorra mucho camino."] = "Si tu voyages avec un mage, demande-lui un portail vers la capitale : ça économise beaucoup de route.",
	["Siempre"] = "Toujours",
	["Siempre con cebo"] = "Toujours appâtée",
	["Siempre: te ofrece la historia de cada misión y un dato de cada zona nueva. A veces: de las misiones que tomas sin leer, y no siempre. Solo si le pido: con clic derecho, «Cuéntame algo de aquí». Las historias se guardan igual."] = "Toujours : elle vous propose l'histoire de chaque quête et une anecdote sur chaque nouvelle zone. Parfois : pour les quêtes que vous prenez sans lire, et pas à chaque fois. Seulement si je demande : clic droit, « Raconte-moi quelque chose sur cet endroit ». Les histoires sont gardées dans tous les cas.",
	["Sigilo"] = "Camouflage",
	["Sigilo y emboscadas: tú eliges cuándo pelear y desapareces cuando quieres."] = "Camouflage et embuscades : vous choisissez quand combattre et disparaissez quand vous voulez.",
	["Siglos después de la División, los Altonato que no soltaban la magia arcana fueron desterrados. Cruzaron el mar y fundaron Quel'Thalas: son los altos elfos."] = "Des siècles après la Fracture, les Bien-nés qui refusaient de lâcher la magie des arcanes ont été exilés. Ils ont traversé la mer et fondé Quel'Thalas : ce sont les hauts-elfes.",
	["Siglos después, los orcos Faucedraco usaron el Alma de Demonio para tener presa a Alexstrasza y criar dragones de guerra para la Horda."] = "Des siècles plus tard, les orcs Gueule-de-dragon se sont servis de l'Âme des démons pour retenir Alexstrasza et élever des dragons de guerre pour la Horde.",
	["Sigue a tu lado, pero no habla hasta las %s."] = "Elle est toujours à vos côtés, mais ne parlera pas avant %s.",
	["Sigue a tu lado, pero no habla por un rato."] = "Elle est toujours à vos côtés, mais ne parlera pas pendant un moment.",
	["Sigue donde ibas"] = "Reprendre où vous en étiez",
	["Sigue la flecha."] = "Suivez la flèche.",
	["Sigue la flecha: las paradas van en el orden más corto, juntas por PNJ."] = "Suivez la flèche : les étapes sont dans l'ordre le plus court, regroupées par PNJ.",
	["Sigue subiendo: %d de %d"] = "Continuez à monter : %d sur %d",
	["Sigue: %s"] = "Ensuite : %s",
	["Sigue: %s. Lee sus consejos antes de la pelea."] = "Ensuite : %s. Lisez ses conseils avant le combat.",
	["Sigues a %s"] = "Vous suivez %s",
	["Sigues con tu equipo de pesca."] = "Vous portez toujours votre équipement de pêche.",
	["Siguiendo"] = "Suivi en cours",
	["Siguiendo a %s."] = "Vous suivez %s.",
	["Siguiendo el rastro"] = "Sur la piste",
	["Siguiendo el rastro de %s. La flecha te lleva hasta su posición."] = "Sur la piste de %s. La flèche vous mène jusqu'à sa position.",
	["Siguiendo tu ruta de %s"] = "Vous suivez votre itinéraire de %s",
	["Siguiente"] = "Suivant",
	["Siguiente parada:"] = "Prochaine étape :",
	["Siguiente paso de la guía"] = "Étape suivante du guide",
	["Siguiente: %s (%d de %d)"] = "Suivant : %s (%d sur %d)",
	["Silencia los sonidos que agregues por su número de archivo (FileDataID): /alfa silenciar <número>; /alfa silenciar quitar <número> lo quita."] = "Coupe les sons que vous ajoutez par leur numéro de fichier (FileDataID) : /alfa silenciar <numéro> ; /alfa silenciar quitar <numéro> le retire.",
	["Silenciar 1 hora"] = "Silence pendant 1 heure",
	["Silenciar sonidos"] = "Couper des sons",
	["Silenciar un sonido por su número (FileDataID)"] = "Couper un son par son numéro (FileDataID)",
	["Silithus es la puerta de Ahn'Qiraj, donde los silítidos y los qiraji sirven al dios antiguo C'Thun."] = "Silithus est la porte d'Ahn'Qiraj, où les silithides et les Qiraji servent le Dieu très ancien C'Thun.",
	["Sin Minería no ves filones; sin Herboristería, hierbas; sin Pesca, bancos. Los tesoros siempre se ven."] = "Sans Minage, pas de filons ; sans Herboristerie, pas d'herbes ; sans Pêche, pas de bancs. Les trésors s'affichent toujours.",
	["Sin Pesca"] = "Sans Pêche",
	["Sin XP descansada"] = "Pas d'XP de repos",
	["Sin acción"] = "Aucune action",
	["Sin activar"] = "Désactivé",
	["Sin aprender"] = "Non apprise",
	["Sin aullido"] = "Sans hurlement",
	["Sin bloqueos y más claro"] = "Sans blocages et plus clair",
	["Sin cambiar de forma."] = "Sans changement de forme.",
	["Sin cambios"] = "Aucun changement",
	["Sin datos"] = "Pas de données",
	["Sin demonio"] = "Sans démon",
	["Sin el ratón encima, la barra guarda sus botones y deja solo lo que pasa."] = "Sans la souris dessus, la barre range ses boutons et ne montre que ce qui se passe.",
	["Sin encantar"] = "Non enchantée",
	["Sin fuente conocida"] = "Aucune source connue",
	["Sin grupo"] = "Sans groupe",
	["Sin límite de tiempo"] = "Sans limite de durée",
	["Sin mascota"] = "Sans familier",
	["Sin metas todavía"] = "Pas encore d'objectifs",
	["Sin metas todavía. Pulsa + para ponerte una: un pez, capturas, tiempo o valor."] = "Pas encore d'objectifs. Appuyez sur + pour en fixer un : un poisson, des prises, un temps ou une valeur.",
	["Sin metas todavía: ábrelo y agrégale una."] = "Pas encore d'objectifs : ouvrez-le et ajoutez-en un.",
	["Sin munición"] = "Sans munitions",
	["Sin objeto"] = "Aucun objet",
	["Sin otros personajes, uno solo puede ganar 29: 3 por subir de nivel, 6 de profesiones, 12 de JcJ, 2 de aventura y 6 de mazmorras y bandas. El resto sale de subir otras clases."] = "Sans autres personnages, un seul peut en gagner 29 : 3 en montant de niveau, 6 avec les métiers, 12 en JcJ, 2 en aventure et 6 en donjons et raids. Le reste vient de la progression d'autres classes.",
	["Sin precio todavía: escanea la subasta."] = "Pas encore de prix : scannez l'hôtel des ventes.",
	["Sin precios"] = "Pas de prix",
	["Sin precios todavía"] = "Pas encore de prix",
	["Sin profesión"] = "Sans métier",
	["Sin sello"] = "Sans sceau",
	["Sin tecla"] = "Sans touche",
	["Sin tinte"] = "Sans teinte",
	["Sin ubicación"] = "Sans position",
	["Sin ubicación ahora: en una instancia o fuera del mapa"] = "Sans position pour l'instant : en instance ou hors de la carte",
	["Sin veneno"] = "Sans poison",
	["Sin zona"] = "Sans zone",
	["Sobre Lya"] = "À propos de Lya",
	["Sobre tu compañero, este clic %s."] = "Sur votre allié, ce clic %s.",
	["Solo %s"] = "%s uniquement",
	["Solo al acabarse"] = "Seulement quand elle est épuisée",
	["Solo al moverte"] = "Seulement en mouvement",
	["Solo buffs"] = "Buffs seulement",
	["Solo con quienes usan Alfa y aceptaron compartir. Tú decides."] = "Seulement avec ceux qui utilisent Alfa et ont accepté de partager. C'est vous qui décidez.",
	["Solo cuando estás en grupo"] = "Seulement en groupe",
	["Solo cuando te llame"] = "Seulement quand je t’appelle",
	["Solo el botín que me sirve"] = "Seulement le butin qui me sert",
	["Solo en una fiesta del año"] = "Seulement pendant une fête annuelle",
	["Solo en warcraft.wiki.gg e Icy Veins: cuántos puntos pide cada premio (15, 25, 40 y 55). Ninguna fuente publica cuánto cuesta cada rango de los árboles: míralo en la ventana del Legado."] = "Seulement sur warcraft.wiki.gg et Icy Veins : combien de points demande chaque récompense (15, 25, 40 et 55). Aucune source ne publie le coût de chaque rang des arbres : regardez dans la fenêtre de l'Héritage.",
	["Solo encontré %d misiones que te sirvan ahora."] = "Je n'ai trouvé que %d quêtes qui vous conviennent pour l'instant.",
	["Solo importantes"] = "Importants seulement",
	["Solo la entrada"] = "Juste l'entrée",
	["Solo las misiones de tu ruta"] = "Seulement les quêtes de votre itinéraire",
	["Solo las que puedes tomar: tu bando, raza, clase y nivel, y que no hayas hecho."] = "Seulement celles que vous pouvez prendre : votre faction, race, classe et niveau, et pas encore faites.",
	["Solo lo de mi papel"] = "Seulement mon rôle",
	["Solo lo que tu clase puede usar y le conviene a tu especialización."] = "Seulement ce que votre classe peut utiliser et qui convient à votre spécialisation.",
	["Solo lo que tu personaje puede usar hoy: clase, armadura, armas, nivel y profesión."] = "Seulement ce que votre personnage peut utiliser aujourd'hui : classe, armure, armes, niveau et métier.",
	["Solo lo que ya puedes recolectar"] = "Seulement ce que vous pouvez déjà récolter",
	["Solo los de la zona donde estás."] = "Seulement ceux de la zone où vous êtes.",
	["Solo los de tus profesiones, en el mapa del mundo y en el minimapa."] = "Seulement ceux de vos métiers, sur la carte du monde et la minicarte.",
	["Solo los graves"] = "Seulement les graves",
	["Solo los que me apuntan a mí"] = "Seulement ceux qui me visent",
	["Solo misiones de XP, las mejores cerca de ti, en tres tandas."] = "Seulement des quêtes d'XP, les meilleures près de vous, en trois séries.",
	["Solo para %s."] = "Seulement pour %s.",
	["Solo para mirar: tu paso de ahora no cambia. Alfa avanza sola cuando lo cumples."] = "Juste pour regarder : votre étape actuelle ne change pas. Alfa avance d'elle-même quand vous l'accomplissez.",
	["Solo puedes tener dos principales a la vez; las secundarias son libres. Se aprenden con su entrenador en las ciudades."] = "Vous ne pouvez avoir que deux métiers principaux à la fois ; les secondaires sont libres. Ils s'apprennent auprès de leur maître dans les villes.",
	["Solo salen los clanes donde puedes invitar, y Alfa te confirma en el chat a quién invitaste. Lo apagas en La Jauría > Invitar."] = "Seuls les endroits où tu peux inviter apparaissent, et Alfa confirme dans la discussion qui tu as invité. Désactive-le dans La Jauría > Inviter.",
	["Solo se admite la versión 1 de la cadena de escala."] = "Seule la version 1 de la chaîne d'échelle est prise en charge.",
	["Solo si falta"] = "Seulement s'il manque",
	["Solo si le pido"] = "Seulement si je demande",
	["Solo sirve con un monitor HDR y el HDR de Windows encendido (Configuración > Pantalla). Sin eso, déjalo apagado: los colores se ven lavados."] = "Ne fonctionne qu'avec un moniteur HDR et le HDR de Windows activé (Paramètres > Affichage). Sinon, laissez-le désactivé : les couleurs paraissent délavées.",
	["Solo tocan gráficos: nunca la cámara, el ratón ni la interfaz. «Deshacer» devuelve lo que tenías antes del último que aplicaste."] = "Ils ne touchent que les graphismes : jamais la caméra, la souris ni l'interface. « Annuler » rétablit ce que vous aviez avant le dernier appliqué.",
	["Solo tu grupo y quienes usan Alfa y aceptaron compartir."] = "Seulement votre groupe et ceux qui utilisent Alfa et ont accepté de partager.",
	["Solo tú"] = "Vous seul",
	["Solo tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "Seulement vous, votre groupe, vos marqueurs et la prochaine étape du guide.",
	["Sombra"] = "Ombre",
	["Sombra para subir"] = "Ombre pour monter",
	["Sombra suave en rincones, pliegues y bajo los objetos: da volumen a todo."] = "Une ombre douce dans les coins, les plis et sous les objets : donne du volume à tout.",
	["Sombras"] = "Ombres",
	["Sombras con bordes más finos. Usa más memoria de video."] = "Ombres aux bords plus fins. Utilise plus de mémoire vidéo.",
	["Sombras suaves"] = "Ombres douces",
	["Son %s más que venderlo todo al comerciante."] = "Soit %s de plus que tout vendre au marchand.",
	["Son puntos de tu cuenta: los ganas con los retos del Legado (logros de Forever) en cualquier personaje, y cada personaje los gasta por su cuenta en sus árboles."] = "Ce sont des points de compte : vous les gagnez avec les défis de l'Héritage (hauts faits de Forever) sur n'importe quel personnage, et chaque personnage les dépense de son côté dans ses arbres.",
	["Son tres enanos que pelean juntos: uno dispara de lejos, otro es muy veloz y otro se protege con escudo. Mátenlos uno por uno."] = "Ce sont trois nains qui combattent ensemble : l'un tire de loin, l'autre est très rapide et le dernier se protège d'un bouclier. Tuez-les un par un.",
	["Sonido"] = "Son",
	["Sonido con el juego en segundo plano"] = "Son avec le jeu en arrière-plan",
	["Sonido de los avisos"] = "Son des alertes",
	["Sonido en los avisos urgentes"] = "Son pour les alertes urgentes",
	["Sonido suave"] = "Son doux",
	["Sonido y avisos"] = "Son et alertes",
	["Sonidos de gestos"] = "Sons des émotes",
	["Sonidos de mascotas"] = "Sons des familiers",
	["Sonidos en tu lista (%d): %s"] = "Sons de votre liste (%d) : %s",
	["Sonidos suaves del juego: nada de voces ni sonidos repetidos."] = "Sons doux du jeu : ni voix ni sons répétés.",
	["Sorpresa"] = "Surprise",
	["Sorpresas y cofres"] = "Surprises et coffres",
	["Soy Lya, la loba de confianza del Alfa. Te acompaño, te cuento el lore de cada lugar y te ayudo con todo lo de Alfa. Y me encantan las salchichas."] = "Je suis Lya, la louve de confiance de l’Alpha. Je t’accompagne, je te raconte l’histoire de chaque lieu et je t’aide avec tout Alfa. Et j’adore les saucisses.",
	["Stromgarde, la heredera de Strom, resiste a medias: trols, ogros y el Sindicato se pelean por sus ruinas."] = "Stromgarde, l'héritière de Strom, résiste tant bien que mal : trolls, ogres et Syndicat se disputent ses ruines.",
	["Su arpón envenena: quita el veneno si puedes."] = "Son harpon empoisonne : guérissez le poison si vous le pouvez.",
	["Su botín está por descubrir"] = "Son butin reste à découvrir",
	["Su electricidad salta de un jugador a otro: sepárense."] = "Son électricité saute d'un joueur à l'autre : écartez-vous.",
	["Su ficha"] = "Sa fiche",
	["Su final no alcanzó a guardarse."] = "Sa fin n'a pas pu être gardée à temps.",
	["Su grupo está lleno o no puede invitar."] = "Son groupe est plein ou il ne peut pas inviter.",
	["Su guarida ya no está abierta."] = "Sa tanière n’est plus ouverte.",
	["Su mordida envenena: quita el veneno si puedes."] = "Sa morsure empoisonne : guérissez le poison si vous le pouvez.",
	["Su oro y sus recompensas ya son tuyos: solo falta entregarlas."] = "Leur or et leurs récompenses sont déjà à vous : il ne reste qu'à les rendre.",
	["Su rayo salta de un jugador a otro: no se queden todos juntos."] = "Son éclair saute d'un joueur à l'autre : ne restez pas tous groupés.",
	["Su rayo salta de un jugador a otro: sepárense un poco."] = "Son éclair saute d'un joueur à l'autre : écartez-vous un peu.",
	["Suave"] = "Doux",
	["Subasta"] = "Hôtel des ventes",
	["Subasta:"] = "Hôtel des ventes :",
	["Subastador"] = "Commissaire-priseur",
	["Subastadores"] = "Commissaires-priseurs",
	["Subastar"] = "Mettre aux enchères",
	["Subastar %d"] = "Mettre aux enchères %d",
	["Sube los efectos y baja la música y el ambiente para que oigas el chapoteo. Al terminar, todo vuelve a como estaba."] = "Monte les effets et baisse la musique et l'ambiance pour que vous entendiez le plouf. À la fin, tout redevient comme avant.",
	["Sube tu profesión o junta sus materiales donde más hay."] = "Faites progresser votre métier ou récoltez ses matériaux là où il y en a le plus.",
	["Sube tus oficios con lo que tienes cerca."] = "Faites progresser vos métiers avec ce qui est à proximité.",
	["Subidón de adrenalina: recuperas energía mucho más rápido."] = "Poussée d'adrénaline : vous récupérez l'énergie beaucoup plus vite.",
	["Subir"] = "Monter",
	["Subir %s a %d"] = "Monter %s à %d",
	["Subir cocina y pesca juntas"] = "Monter cuisine et pêche ensemble",
	["Subir como tanque: más lento que Armas, pero casi nunca mueres, juntas varios monstruos a la vez y llegas listo para tanquear cualquier mazmorra."] = "Monter en tank : plus lent qu'Armes, mais vous ne mourez presque jamais, vous attirez plusieurs monstres à la fois et vous arrivez prêt à tanker n'importe quel donjon.",
	["Subir de nivel"] = "Monter de niveau",
	["Subir de nivel, profesiones, hacer oro o mazmorras: dos clics y Alfa te lleva."] = "Monter de niveau, métiers, faire de l'or ou donjons : deux clics et Alfa vous y mène.",
	["Subir de nivel, profesiones, oro o mazmorras."] = "Monter de niveau, métiers, or ou donjons.",
	["Subir el sonido al pescar"] = "Monter le son pendant la pêche",
	["Subir rápido"] = "Monter vite",
	["Subir solo"] = "Monter en solo",
	["Subir una profesión"] = "Monter un métier",
	["Succionar vida: daño con el tiempo que te cura."] = "Siphon de vie : dégâts sur la durée qui vous soignent.",
	["Suelta"] = "Laisse tomber",
	["Suelta el lanzamiento de ahora y lanza otra vez, sin poner equipo ni cebo."] = "Abandonne le lancer en cours et relance, sans équipement ni appât.",
	["Suelta lo que tienes en el cursor y vuelve a intentarlo."] = "Lâchez ce que vous avez sur le curseur et réessayez.",
	["Suelta una carta que empieza una misión: revisa su botín."] = "Il laisse tomber une lettre qui commence une quête : vérifiez son butin.",
	["Suelta una llave que abre una puerta más adelante: alguien debe recogerla."] = "Il laisse tomber une clé qui ouvre une porte plus loin : quelqu'un doit la ramasser.",
	["Suelta una nube de enfermedad a su alrededor: quiten enfermedades."] = "Il libère un nuage de maladie autour de lui : guérissez les maladies.",
	["Suelta una ola de fuego a su alrededor: si peleas de lejos, quédate lejos de él."] = "Il libère une vague de feu autour de lui : si vous combattez à distance, restez loin de lui.",
	["Suena ahora, aunque el aullido esté apagado."] = "Le joue maintenant, même si le hurlement est désactivé.",
	["Sueño con una montaña de salchichas... y yo en la punta, feliz."] = "Je rêve d'une montagne de saucisses... et moi tout en haut, heureuse.",
	["Sugerida para ti: %s"] = "Suggéré pour vous : %s",
	["Sugerir qué vender"] = "Suggérer quoi vendre",
	["Sugiere con la prioridad de Alfa para tu clase. Apagado, usa la ayuda de Blizzard cuando el juego da una sugerencia que Alfa puede leer; en combate Forever la oculta, así que ahí sigue la de Alfa."] = "Suggère avec la priorité d’Alfa pour ta classe. Désactivé, utilise l’aide au combat de Blizzard quand le jeu donne une suggestion lisible par Alfa ; en combat Forever la masque, donc celle d’Alfa reste.",
	["Sulfuras es el martillo de Ragnaros. Con su ojo, los más valientes pueden forjar una versión legendaria."] = "Sulfuras est le marteau de Ragnaros. Avec son œil, les plus braves peuvent en forger une version légendaire.",
	["Suma tus sesiones de hoy con este personaje."] = "Additionne vos sessions du jour avec ce personnage.",
	["Suma «conseguir este objeto» a tu plan de ahora (o a uno nuevo)."] = "Ajoute « obtenir cet objet » à votre plan actuel (ou à un nouveau).",
	["Supervivencia"] = "Survie",
	["Supervivencia para subir"] = "Survie pour monter",
	["Sus bolas de sombra pegan mucho: interrúmpelo."] = "Ses Traits de l'ombre font très mal : interrompez-le.",
	["Sus consejos"] = "Ses conseils",
	["Sus consejos te esperan en Alfa."] = "Ses conseils vous attendent dans Alfa.",
	["Sus jefes, su botín, sus misiones y cómo llegar."] = "Ses boss, son butin, ses quêtes et comment y aller.",
	["Sus misiones dan"] = "Ses quêtes donnent",
	["Sus rayos saltan entre jugadores: sepárense."] = "Ses éclairs sautent entre les joueurs : écartez-vous.",
	["Sutileza"] = "Finesse",
	["Sutileza para subir"] = "Finesse pour monter",
	["Sylvanas era hermana de Alleria y de Vereesa Brisaveloz. Hoy guía a los Renegados con mano firme."] = "Sylvanas était la sœur d'Alleria et de Vereesa Coursevent. Aujourd'hui, elle guide les Réprouvés d'une main ferme.",
	["Sylvanas recibe en el Barrio Real de Entrañas, con Varimathras a su lado."] = "Sylvanas tient sa cour dans le quartier Royal de Fossoyeuse, avec Varimathras à ses côtés.",
	["Sylvanas tiene dos hermanas: Alleria, que se fue más allá del Portal Oscuro, y Vereesa, que se casó con el mago Rhonin."] = "Sylvanas a deux sœurs : Alleria, partie au-delà de la Porte des Ténèbres, et Vereesa, qui a épousé le mage Rhonin.",
	["Sí"] = "Oui",
	["Sí, que la manada me vea"] = "Oui, que la meute me voie",
	["Sí, que me vean"] = "Oui, qu'ils me voient",
	["Sí, ya la hice"] = "Oui, je l'ai déjà fait",
	["Sí: Alfa, Clásico WoW o Cristal, con tu color. También puede vestir el chat, el minimapa y las barras."] = "Oui : Alfa, WoW Classique ou Cristal, avec ta couleur. Il peut aussi habiller le chat, la minicarte et les barres.",
	["Sí: en las asignaciones de teclas del juego, en la sección Alfa, ponle una tecla a «Pregúntale a Lya» y otra a «Lo que te ofrece Lya», que hace lo de su botón."] = "Oui : dans les raccourcis du jeu, section Alfa, donne une touche à « Demande à Lya » et une autre à « Ce que Lya te propose », qui fait ce que fait son bouton.",
	["Sí: en las asignaciones de teclas del juego, en la sección Alfa, ponle una tecla a «Pregúntale a Lya»."] = "Oui : dans les raccourcis du jeu, section Alfa, donne une touche à « Demande à Lya ».",
	["Sí: sale «[Misión] está lista para entregar» y «¡Misión completada!» en el chat del grupo. Solo, te sale a ti."] = "Oui : « [Quête] est prête à rendre » et « Quête terminée ! » s’affichent dans le chat du groupe. Seul, toi seul le vois.",
	["Tabardo"] = "Tabard",
	["Talentos"] = "Talents",
	["Talentos de %s"] = "Talents de %s",
	["Talentos te dice cuál sigue."] = "Talents vous dit lequel prendre ensuite.",
	["Talentos y combate"] = "Talents et combat",
	["Talentos: qué poner ahora y tu build (/alfa builds aplicar | equipo | compartir)"] = "Talents : quoi prendre maintenant et votre build (/alfa builds aplicar | equipo | compartir)",
	["Tamaño"] = "Taille",
	["Tamaño de la barra"] = "Taille de la barre",
	["Tamaño de las casillas"] = "Taille des emplacements",
