	["También con /alfa dps. No se cierra con Esc, para que la tengas a la vista al pelear."] = "Aussi avec /alfa dps. Elle ne se ferme pas avec Échap, pour rester visible pendant le combat.",
	["También cuando el juego hace brillar otra habilidad"] = "Aussi quand le jeu fait briller une autre technique",
	["También dentro de cuevas, criptas y edificios."] = "Aussi dans les grottes, cryptes et bâtiments.",
	["También el de venenos, sangrados y efectos que duran."] = "Aussi celui des poisons, saignements et effets durables.",
	["También en el minimapa"] = "Aussi sur la minicarte",
	["También en montura"] = "Aussi sur une monture",
	["También está en el menú de opciones del juego."] = "Aussi dans le menu des options du jeu.",
	["También fuera de combate"] = "Aussi hors combat",
	["También las de las mascotas de enemigos."] = "Aussi celles des familiers des ennemis.",
	["También las que no son de la guía (de esas se encarga \"Aceptar misiones de la guía\"). No toma misiones grises, no entrega las que piden oro, monedas o materiales de oficio, y si hay varias recompensas eliges tú. Mantén presionado Mayús para hacerlo tú."] = "Aussi celles qui ne viennent pas du guide (« Accepter les quêtes du guide » s'occupe de celles-là). Les quêtes grises sont ignorées, celles qui demandent de l'or, des monnaies ou des matériaux d'artisanat ne sont pas rendues, et s'il y a plusieurs récompenses, c'est vous qui choisissez. Maintenez Maj enfoncée pour le faire vous-même.",
	["También las que no son de tu guía"] = "Aussi celles hors de votre guide",
	["Tanque"] = "Tank",
	["Tanque de amenaza"] = "Tank de menace",
	["Tanque de escudo"] = "Tank bouclier",
	["Tanque muralla"] = "Tank rempart",
	["Taretha Foxton, una muchacha humana de Durnholde, fue la amiga de Thrall y lo ayudó a escapar."] = "Taretha Foxton, une jeune humaine de Fort-de-Durn, était l'amie de Thrall et l'a aidé à s'évader.",
	["Tarjeta de habilidades nuevas al subir de nivel"] = "Fiche des nouvelles compétences à chaque niveau",
	["Tauren"] = "Taurens",
	["Te abrimos un susurro para %s con tu mensaje. Revísalo y pulsa Intro para enviarlo."] = "Nous avons ouvert un chuchotement pour %s avec votre message. Vérifiez-le et appuyez sur Entrée pour l'envoyer.",
	["Te acompaña"] = "T’accompagne",
	["Te avisa al momento de %s."] = "Vous prévient au moment d'utiliser %s.",
	["Te avisa cuando tu clase tiene algo que aprovechar ahora, como una habilidad que se encendió."] = "Vous prévient quand votre classe a quelque chose à exploiter maintenant, comme une technique qui vient de s'illuminer.",
	["Te da %s."] = "Vous donne %s.",
	["Te da consejos cortos y ánimo sin repetirse: cada frase sale tres veces como mucho. Dale clic para pedirle uno; clic derecho para sus opciones."] = "Elle vous donne de courts conseils et des encouragements sans se répéter : chaque phrase apparaît trois fois au plus. Cliquez sur elle pour lui en demander un ; clic droit pour ses options.",
	["Te da poder de ataque: cada golpe pega más. Para el guerrero también sube el bloqueo con escudo."] = "Vous donne de la puissance d'attaque : chaque coup frappe plus fort. Pour le guerrier, elle augmente aussi le blocage au bouclier.",
	["Te damos la bienvenida a Alfa, el todo en uno de La Jauría."] = "Bienvenue dans Alfa, le tout-en-un de La Jauría.",
	["Te dice qué pieza está por romperse, para que la repares a tiempo."] = "Vous indique quelle pièce va se briser, pour la réparer à temps.",
	["Te enseña %s."] = "Vous apprend %s.",
	["Te enseña Pesca y sus rangos. También vende la caña básica."] = "Enseigne la Pêche et ses rangs. Vend aussi la canne de base.",
