	["Te falta ira: Enfurecer te la da."] = "Il vous manque de la rage : Enrager vous en donne.",
	["Te falta ira: Ira sangrienta te la da gratis."] = "Vous manquez de rage : Rage sanguinaire vous en donne gratuitement.",
	["Te falta ira: esta habilidad te la da al recibir golpes."] = "Il vous manque de la rage : cette technique vous en donne quand vous encaissez des coups.",
	["Te falta la forma de las Sombras: más daño de sombras y menos daño recibido."] = "Il vous manque Forme d'Ombre : plus de dégâts d'Ombre et moins de dégâts subis.",
	["Te falta la forma de lechúcico lunar: más daño con tus hechizos."] = "Il vous manque Forme de sélénien : plus de dégâts avec vos sorts.",
	["Te falta la profesión"] = "Métier requis",
	["Te falta reputación"] = "Réputation insuffisante",
	["Te falta tu armadura demoníaca."] = "Il vous manque votre Armure démoniaque.",
