	["Te falta un aspecto: el del mono te ayuda a esquivar."] = "Il vous manque un aspect : celui du singe vous aide à esquiver.",
	["Te falta una bendición: Poderío da más poder de ataque."] = "Il vous manque une bénédiction : Puissance donne plus de puissance d'attaque.",
	["Te falta una bendición: Sabiduría te devuelve maná."] = "Il vous manque une bénédiction : Sagesse vous rend du mana.",
	["Te falta una bendición: Santuario reduce el daño que recibes."] = "Il vous manque une bénédiction : Sanctuaire réduit les dégâts subis.",
	["Te faltan %d niveles para tomarla."] = "Encore %d niveaux avant de pouvoir la prendre.",
