	["Te faltan %s XP para el nivel %d"] = "%s XP avant le niveau %d",
	["Te faltan %s XP para el nivel %d, a tu ritmo actual."] = "Encore %s XP avant le niveau %d, à votre rythme actuel.",
	["Te faltan ingredientes para el siguiente lote."] = "Il vous manque des ingrédients pour la fournée suivante.",
	["Te faltan ingredientes."] = "Il vous manque des ingrédients.",
	["Te faltan niveles para llegar a %d: la guía te lo marca y sigues subiendo con tu ruta."] = "Il vous manque des niveaux pour atteindre le %d : le guide vous l'indique et vous continuez à monter avec votre itinéraire.",
	["Te faltan niveles: cada nivel desde el 10 te da un punto."] = "Il vous manque des niveaux : chaque niveau à partir du 10 vous donne un point.",
	["Te la da %s, en %s."] = "%s vous la donne, à %s.",
	["Te la da %s."] = "%s vous la donne.",
	["Te la dio %s"] = "Donnée par %s",
	["Te la dio %s · Se entrega con %s"] = "Donnée par %s · À rendre à %s",
	["Te la dio y la recibe %s"] = "Donnée et reçue par %s",
	["Te lleva a las misiones de tu ruta que ya puedes tomar."] = "Vous mène aux quêtes de votre itinéraire que vous pouvez déjà prendre.",
	["Te llevo a %s"] = "Je vous mène à %s",
	["Te llevo a entregarlas todas en el mejor orden."] = "Je t’emmène les rendre toutes dans le meilleur ordre.",
	["Te llevo a la mejor fuente. Recuerda que una montura pide nivel, equitación y oro."] = "Je vous mène à la meilleure source. N'oubliez pas qu'une monture demande un niveau, la monte et de l'or.",
	["Te llevo a quien recibe cada una y recoges las que siguen."] = "Je vous mène à celui qui reçoit chacune, et vous récupérez les suivantes.",
	["Te llevo la cuenta de tu día de caza: misiones, niveles, oro, raros y el tiempo. Escribe /alfa lya dia y te lo cuento."] = "Je tiens le compte de ta journée de chasse : quêtes, niveaux, or, rares et temps. Tape /alfa lya dia et je te raconte.",
	["Te llevo la cuenta de tu semana de caza y tu mejor día. Escribe /alfa lya semana y te lo cuento."] = "Je tiens le compte de ta semaine de chasse et de ton meilleur jour. Tape /alfa lya semana et je te raconte.",
	["Te lo da un PNJ"] = "Donné par un PNJ",
	["Te lo enseña cualquier instructor de pesca. Hasta que lo aprendas, tu habilidad no pasa del tope."] = "N'importe quel maître de pêche vous l'enseigne. Tant que vous ne l'avez pas appris, votre compétence ne dépasse pas le plafond.",
	["Te lo enseña tu entrenador."] = "Votre maître vous l'enseigne.",
	["Te lo pido de corazón: nunca desuelles a un lobo enfrente de mí, ¿sí?"] = "Je te le demande de tout cœur : ne dépèce jamais un loup devant moi, d'accord ?",
	["Te los enseña tu entrenador."] = "Votre maître vous les enseigne.",
	["Te presento a Lya"] = "Je te présente Lya",
	["Te queda 1 espacio"] = "Il vous reste 1 emplacement",
	["Te queda muy poco maná: Estimular lo recupera."] = "Vous êtes presque à sec de mana : Innervation le restaure.",
	["Te queda muy poco maná: Evocación lo recupera."] = "Vous êtes presque à sec de mana : Évocation le restaure.",
	["Te queda poca XP descansada"] = "Il vous reste peu d'XP de repos",
	["Te queda poco maná y te sobra vida: cambia vida por maná."] = "Peu de mana et de la vie à revendre : échangez de la vie contre du mana.",
	["Te queda poco maná: cambia vida por maná."] = "Vous manquez de mana : échangez de la vie contre du mana.",
	["Te queda poco maná: usa tu varita."] = "Vous êtes à court de mana : utilisez votre baguette.",
	["Te quedan %d de %d espacios"] = "Il vous reste %d emplacements sur %d",
	["Te quedan %d espacios en las bolsas. Vende lo gris o guarda en el banco."] = "Il te reste %d emplacements dans tes sacs. Vends le gris ou range à la banque.",
	["Te saluda según la hora, comenta la zona y a veces se sienta a pedirte algo con su huesito."] = "Elle vous salue selon l'heure, commente la zone et s'assoit parfois pour quémander avec son petit os.",
	["Te sobra ira y hay varios enemigos: tu siguiente golpe alcanza a dos."] = "Vous avez de la rage en trop et plusieurs ennemis : votre prochain coup en touche deux.",
	["Te sobra ira: gástala en tu siguiente golpe."] = "Vous avez de la rage en trop : dépensez-la dans votre prochain coup.",
	["Te sobra ira: tu siguiente golpe es más fuerte."] = "Vous avez de la rage en trop : votre prochain coup est plus puissant.",
	["Te sugiere objetivos de pasos más adelante que tienes muy cerca."] = "Vous suggère des objectifs d'étapes suivantes qui sont tout près.",
	["Te sugiere qué habilidad usar ahora y cuáles siguen. Solo sugiere: nunca presiona nada por ti."] = "Vous suggère quelle technique utiliser maintenant et lesquelles suivent. Il ne fait que suggérer : il n'appuie jamais sur rien à votre place.",
	["Tecla del modo pesca"] = "Touche du mode pêche",
