	["Trilineal"] = "Trilinéaire",
	["Trinquete es un puerto goblin neutral: ahí se tolera a cualquiera que traiga oro, y su barco lleva hasta Bahía del Botín."] = "Cabestan est un port gobelin neutre : quiconque apporte de l'or y est toléré, et son bateau va jusqu'à Baie-du-Butin.",
