	["Tu día con la manada: el plan, lo urgente y tu clase."] = "Votre journée avec la meute : le plan, l'urgent et votre classe.",
	["Tu día de caza"] = "Ta journée de chasse",
	["Tu día de caza: Lya cuenta tus misiones, niveles, oro y raros del día. Pídeselo con /alfa lya dia."] = "Ta journée de chasse : Lya compte les quêtes, niveaux, or et rares du jour. Demande-lui avec /alfa lya dia.",
	["Tu elección"] = "Votre choix",
	["Tu entrenador de clase tiene algo para ti."] = "Votre maître de classe a quelque chose pour vous.",
	["Tu entrenador de equitación"] = "Votre maître de monte",
	["Tu entrenador tiene algo nuevo para ti"] = "Votre maître a quelque chose de nouveau pour vous",
	["Tu entrenador: %s (%s)."] = "Votre maître : %s (%s).",
	["Tu entrenador: %s."] = "Votre maître : %s.",
	["Tu equipo está al %d%%. Mejor repararlo antes de la siguiente pelea."] = "Ton équipement est à %d%%. Mieux vaut le réparer avant le prochain combat.",
	["Tu equipo está por romperse"] = "Ton équipement va bientôt casser",
	["Tu equipo se está gastando"] = "Votre équipement s'use",
	["Tu equipo, tus bolsas y tu entrenamiento están al día."] = "Votre équipement, vos sacs et votre entraînement sont à jour.",
	["Tu escudo protege mucho, pero deja al aliado con el alma debilitada un rato: no puedes ponérselo otra vez enseguida."] = "Ton bouclier protège beaucoup, mais laisse ton allié avec une Âme affaiblie un moment : tu ne peux pas lui en remettre un tout de suite.",
	["Tu especialización"] = "Votre spécialisation",
	["Tu estilo"] = "Votre style",
	["Tu estilo (Alfa, Clásico WoW o Cristal), el color de acento y el aullido."] = "Votre style (Alfa, WoW classique ou Cristal), la couleur d'accent et le hurlement.",
	["Tu estilo: %s"] = "Votre style : %s",
	["Tu facción (%s)"] = "Votre faction (%s)",
	["Tu forma de viaje es un felino veloz... pero en una carrera yo no te la pondría fácil."] = "Ta forme de voyage est un félin rapide... mais à la course, je ne te laisserais pas gagner facilement.",
	["Tu gente no confía en la magia arcana: recuerda bien lo que pasó con Azshara y el Pozo de la Eternidad."] = "Ton peuple ne fait pas confiance à la magie des arcanes : il se souvient bien de ce qui s'est passé avec Azshara et le Puits d'éternité.",
	["Tu gente, los humanos, desciende de las tribus que el rey Thoradin unió en Arathor hace miles de años."] = "Ton peuple, les humains, descend des tribus que le roi Thoradin a unies en Arathor il y a des milliers d'années.",
	["Tu golpe más fuerte desde el nivel 40 hasta el 60."] = "Votre coup le plus fort du niveau 40 au 60.",
	["Tu golpe más fuerte desde el nivel 40."] = "Votre coup le plus fort dès le niveau 40.",
	["Tu golpe más fuerte, crece con tu bloqueo."] = "Votre coup le plus fort, il grandit avec votre blocage.",
	["Tu golpe más fuerte, y además reduce las curas del enemigo."] = "Votre coup le plus fort, qui réduit en plus les soins de l'ennemi.",
	["Tu golpe más fuerte."] = "Votre coup le plus fort.",
	["Tu golpe principal contra jefes."] = "Votre coup principal contre les boss.",
	["Tu golpe principal."] = "Votre coup principal.",
	["Tu grupo"] = "Votre groupe",
	["Tu grupo en el mapa"] = "Votre groupe sur la carte",
	["Tu grupo o banda en el mapa y el minimapa, con el color de su clase."] = "Votre groupe ou raid sur la carte et la minicarte, à la couleur de sa classe.",
	["Tu grupo y tu banda con su vida, para curar con un clic. Se cambia fuera de combate."] = "Votre groupe et votre raid avec leur vie, pour soigner en un clic. Se change hors combat.",
	["Tu grupo, tu hermandad y tus amigos en el mapa, con Seguir y la página del clan."] = "Votre groupe, votre guilde et vos amis sur la carte, avec Suivre et la page du clan.",
	["Tu guarida a la vista"] = "Ta tanière en vue",
	["Tu guarida en el rastreador y en el cuadro de los lobos, y Lya te avisa si el juego te cambia de capa."] = "Ta tanière dans le suivi et dans la bulle des loups, et Lya te prévient si le jeu change ta couche.",
	["Tu guarida está abierta: si alguien de la manada pide entrar, Alfa lo invita a tu grupo."] = "Ta tanière est ouverte : si quelqu’un de la meute demande à entrer, Alfa l’invite dans ton groupe.",
	["Tu guía"] = "Votre guide",
	["Tu guía deja fuera las misiones que ya no dan experiencia, salvo que otra las necesite."] = "Votre guide laisse de côté les quêtes qui ne donnent plus d'expérience, sauf si une autre en a besoin.",
	["Tu guía está lista. Ábrela para ver tu paso."] = "Votre guide est prêt. Ouvrez-le pour voir votre étape.",
	["Tu guía puede elegir y avanzar sola, o preguntarte en cada cruce."] = "Votre guide peut choisir et avancer tout seul, ou vous demander à chaque embranchement.",
	["Tu guía te lleva a entrenar en %d pasos."] = "Votre guide vous emmène apprendre vos sorts en %d étapes.",
	["Tu guía te lleva a entrenar en este paso."] = "Votre guide vous emmène apprendre vos sorts à cette étape.",
	["Tu guía te lleva a tomarla."] = "Votre guide vous emmène la prendre.",
	["Tu guía terminó y el camino se abre"] = "Votre guide est terminé et le chemin se divise",
	["Tu guía y Hoy dicen lo mismo: al terminar «Desbloquear» vuelves solo a tu guía, y el final de una guía con pasos sin hacer ya no dice «terminaste»."] = "Ton guide et Aujourd’hui disent la même chose : en finissant « Débloquer », tu reviens seul à ton guide, et la fin d’un guide avec des étapes non faites ne dit plus « terminé ».",
	["Tu guía ya no te manda a entregar misiones sin terminar: primero te lleva a lo que falta, y «Cerrar mis misiones» se pone al día sola."] = "Votre guide ne vous envoie plus rendre des quêtes inachevées : il vous mène d'abord à ce qui manque, et « Terminer mes quêtes » se met à jour tout seul.",
	["Tu hechizo principal de fuego."] = "Votre principal sort de feu.",
	["Tu hechizo principal."] = "Votre sort principal.",
	["Tu hechizo principal: daño y frena al enemigo."] = "Votre sort principal : des dégâts et ralentit l'ennemi.",
	["Tu hermandad conectada"] = "Votre guilde en ligne",
	["Tu hermandad y tu grupo reciben los horarios que tomas, y tú los suyos."] = "Votre guilde et votre groupe reçoivent les horaires que vous relevez, et vous les leurs.",
	["Tu historial"] = "Votre historique",
	["Tu insignia de La Jauría en el borde de tu retrato, y en el de tu objetivo si la lleva."] = "Ton insigne de La Jauría au bord de ton portrait, et sur celui de ta cible si elle en a un.",
	["Tu insignia en los retratos"] = "Ton insigne sur les portraits",
	["Tu instalación está mezclada o incompleta (%s). Cierra el juego, borra todas las carpetas de Alfa en Interface/AddOns e instala Alfa de nuevo con la app de CurseForge o el zip más reciente (no \"Source code\")."] = "Votre installation est mélangée ou incomplète (%s). Fermez le jeu, supprimez tous les dossiers d'Alfa dans Interface/AddOns et réinstallez Alfa avec l'application CurseForge ou le zip le plus récent (pas « Source code »).",
	["Tu ira se llena al pegar y al recibir golpes: entra a la pelea con Cargar para empezar con ira."] = "Ta rage se remplit en frappant et en encaissant : engage le combat avec Charge pour commencer avec de la rage.",
	["Tu libro no tiene hechizos para aliados"] = "Votre grimoire n'a pas de sorts pour les alliés",
	["Tu lista de sonidos"] = "Votre liste de sons",
	["Tu lista de sonidos está vacía. Agrega uno con /alfa silenciar <número>."] = "Votre liste de sons est vide. Ajoutez-en un avec /alfa silenciar <numéro>.",
	["Tu lista de sonidos quedó vacía."] = "Votre liste de sons est maintenant vide.",
	["Tu lista: síguelos con la flecha, compártelos con el grupo, cámbialos o bórralos."] = "Votre liste : suivez-les avec la flèche, partagez-les avec le groupe, modifiez-les ou effacez-les.",
	["Tu loba compañera: consejos cortos, ánimo y nunca te deja atrás."] = "Votre louve compagne : de courts conseils, des encouragements, et elle ne vous laisse jamais derrière.",
	["Tu loba compañera: te da consejos y ánimo. También con /alfa lya."] = "Votre louve compagne : elle vous donne conseils et encouragements. Aussi avec /alfa lya.",
	["Tu lugar resalta más: tu flecha lleva un aro y un pulso suave, y se ve bien hasta en la nieve."] = "Ta position ressort mieux : ta flèche porte un anneau et une pulsation douce, et se voit bien même dans la neige.",
	["Tu manada"] = "Votre meute",
	["Tu manada en el mapa: tu grupo y quienes usan Alfa y comparten. Síguelos con la flecha, invítalos y conoce al clan."] = "Votre meute sur la carte : votre groupe et ceux qui utilisent Alfa et partagent. Suivez-les avec la flèche, invitez-les et découvrez le clan.",
	["Tu manada está fuera del mapa"] = "Votre meute est hors de la carte",
	["Tu mapa"] = "Votre carte",
	["Tu mapa del ratón está vacío: elige algo en una ranura primero."] = "Votre configuration de souris est vide : choisissez d'abord quelque chose pour un emplacement.",
	["Tu marcador"] = "Votre marqueur",
	["Tu mascota"] = "Votre familier",
	["Tu mascota aprende habilidades de otras bestias: doma una que sepa lo que quieres y te lo enseña."] = "Ton familier apprend des techniques d'autres bêtes : apprivoises-en une qui connaît ce que tu veux et elle te l'apprendra.",
	["Tu mascota hace gran parte del trabajo y aguanta los golpes: la forma más fácil y segura de subir con cazador."] = "Votre familier fait une grande partie du travail et encaisse les coups : la façon la plus facile et la plus sûre de monter un chasseur.",
	["Tu mascota tiene poca vida: cúrala."] = "Votre familier a peu de points de vie : soignez-le.",
	["Tu mejor día: %d misiones."] = "Ton meilleur jour : %d quêtes.",
	["Tu montura de clase"] = "Votre monture de classe",
	["Tu montura rápida (nivel 60)"] = "Votre monture rapide (niveau 60)",
	["Tu munición"] = "Vos munitions",
	["Tu nivel"] = "Votre niveau",
	["Tu nivel, reparar, comida y bebida, y la entrada de la mazmorra para ti."] = "Votre niveau, la réparation, nourriture et boisson, et l'entrée du donjon pour vous.",
	["Tu nota"] = "Votre note",
	["Tu objetivo esquivó: Abrumar no se puede esquivar y pega fuerte. Necesita actitud de batalla."] = "Votre cible a esquivé : Fulgurance ne peut pas être esquivée et frappe fort. Nécessite la posture de combat.",
	["Tu oro"] = "Votre or",
	["Tu pantalla y tu compañera"] = "Votre écran et votre compagne",
	["Tu paso de ahora es el %d."] = "Votre étape actuelle est la %d.",
	["Tu paso de ahora es el %d: %s."] = "Votre étape actuelle est la %d : %s.",
	["Tu personaje"] = "Votre personnage",
	["Tu personaje aparece en el mapa de quienes también se dejan ver. Solo su lugar en el juego y nunca dentro de mazmorras; va por un canal oculto que alguien con otro addon podría leer."] = "Votre personnage apparaît sur la carte de ceux qui se montrent aussi. Seulement sa place dans le jeu et jamais en donjon ; cela passe par un canal caché que quelqu'un avec un autre addon pourrait lire.",
	["Tu personaje deja de decir \"No tengo suficiente maná\", \"Eso todavía no está listo\" y parecidas. El texto rojo sigue."] = "Votre personnage cesse de dire « Pas assez de mana », « Ce n'est pas encore prêt » et autres phrases du genre. Le texte rouge reste.",
	["Tu personaje no aparece en el mapa de nadie de La Jauría. Lo cambias cuando quieras en la página de La Jauría."] = "Votre personnage n'apparaît sur la carte de personne de La Jauría. Changez-le quand vous voulez sur la page La Jauría.",
	["Tu personaje todavía no recolecta. Con Minería o Herboristería, Alfa une las minas o las hierbas de tu zona en una vuelta corta. Te las enseña un instructor de profesión."] = "Votre personnage ne récolte pas encore. Avec le Minage ou l'Herboristerie, Alfa relie les filons ou les herbes de votre zone en une boucle courte. Un maître de métier vous les enseigne.",
	["Tu pesca"] = "Votre pêche",
	["Tu pesca está al máximo"] = "Votre pêche est au maximum",
	["Tu piedra de hogar te regresa a tu posada. Úsala para ahorrar caminata."] = "Ta pierre de foyer te ramène à ton auberge. Utilise-la pour économiser de la marche.",
	["Tu piedra de hogar y el descanso"] = "Votre pierre de foyer et le repos",
	["Tu pieza más gastada: %s al %d %%."] = "Votre pièce la plus usée : %s à %d %%.",
	["Tu plan"] = "Votre plan",
	["Tu plan está en Talentos."] = "Votre plan est dans Talents.",
	["Tu plan no pudo agregarlo."] = "Votre plan n'a pas pu l'ajouter.",
	["Tu plan no tiene metas"] = "Votre plan n'a pas d'objectifs",
	["Tu plan no tiene metas todavía"] = "Votre plan n'a pas encore d'objectifs",
	["Tu plan se quedó sin paso"] = "Ton plan n’a plus d’étape",
	["Tu plan se quedó sin paso. Seguir lo vuelve a armar con las misiones que tienes ahora."] = "Ton plan n’a plus d’étape. Suivre le refait avec les quêtes que tu as maintenant.",
	["Tu posición en la parte de abajo del minimapa."] = "Votre position en bas de la minicarte.",
	["Tu posición y la del cursor bajo el mapa."] = "Votre position et celle du curseur sous la carte.",
	["Tu primer punto, en el nivel 10."] = "Votre premier point, au niveau 10.",
	["Tu primer talento"] = "Votre premier talent",
	["Tu primera guía"] = "Votre premier guide",
	["Tu primera montura (nivel 40)"] = "Votre première monture (niveau 40)",
	["Tu primera sesión entra al diario cuando salgas del juego. La manada te espera: ¡a cazar!"] = "Votre première session entrera dans le journal quand vous quitterez le jeu. La meute vous attend : en chasse !",
	["Tu prioridad"] = "Votre priorité",
	["Tu prioridad: %s"] = "Votre priorité : %s",
	["Tu progreso"] = "Votre progression",
	["Tu propia lista de metas, en el orden que quieras: un objeto, oro, una profesión, un lugar, una misión, un nivel o una nota. Alfa las mide solas y te lleva a cada una."] = "Votre propre liste d'objectifs, dans l'ordre que vous voulez : un objet, de l'or, un métier, un lieu, une quête, un niveau ou une note. Alfa les mesure tout seul et vous mène à chacun.",
	["Tu propio marco aparece aunque no estés en grupo, para curarte con un clic."] = "Votre propre cadre s'affiche même si vous n'êtes pas en groupe, pour vous soigner en un clic.",
	["Tu prueba"] = "Votre test",
	["Tu rama: %s"] = "Votre arbre : %s",
	["Tu rastro"] = "Votre piste",
	["Tu ratón"] = "Votre souris",
	["Tu registro está lleno: cierra algunas misiones primero."] = "Votre journal est plein : terminez d'abord quelques quêtes.",
	["Tu registro está vacío"] = "Votre journal est vide",
	["Tu reporte, listo para pegar"] = "Votre rapport, prêt à coller",
	["Tu ritmo de los últimos 15 minutos"] = "Votre rythme sur les 15 dernières minutes",
	["Tu ritmo de los últimos 15 minutos, con el contador de XP de Alfa."] = "Votre rythme sur les 15 dernières minutes, avec le compteur d'XP d'Alfa.",
	["Tu ruta de %d tramos."] = "Votre itinéraire de %d tronçons.",
	["Tu ruta de %s en %s está lista"] = "Votre itinéraire de %s dans %s est prêt",
	["Tu ruta dibujada en el mapa de Alfa hasta tu destino, que late para que lo encuentres; arriba ves a qué distancia está y cuánto falta, y un clic te muestra todo el camino."] = "Ton itinéraire tracé sur la carte d'Alfa jusqu'à ta destination, qui pulse pour que tu la trouves ; en haut, tu vois à quelle distance elle est et combien de temps il reste, et un clic te montre tout le chemin.",
	["Tu ruta está vacía"] = "Votre itinéraire est vide",
	["Tu ruta no pudo agregarlo."] = "Votre itinéraire n'a pas pu l'ajouter.",
	["Tu ruta no tiene tramos todavía"] = "Votre itinéraire n'a pas encore de tronçons",
	["Tu ruta pasa por ahí."] = "Votre itinéraire passe par là.",
	["Tu ruta personalizada, armada por Alfa con tus tramos."] = "Votre itinéraire personnalisé, construit par Alfa avec vos tronçons.",
	["Tu ruta se actualizó"] = "Votre itinéraire a été mis à jour",
	["Tu ruta, paso a paso"] = "Votre itinéraire, pas à pas",
	["Tu ruta, tus misiones y tus guías (/alfa rutas ayuda)."] = "Votre itinéraire, vos quêtes et vos guides (/alfa rutas ayuda).",
	["Tu semana de caza"] = "Ta semaine de chasse",
	["Tu sesión anterior (%s): %s"] = "Votre session précédente (%s) : %s",
	["Tu sesión anterior, %s"] = "Votre session précédente, %s",
	["Tu sesión de ahora"] = "Votre session en cours",
	["Tu sesión de pesca ya estaba vacía: la nueva empieza con tu primer lanzamiento."] = "Ta session de pêche était déjà vide : la nouvelle commence à ton premier lancer.",
	["Tu sesión, tu diario, recordatorios y tu siguiente paso, con el color de tu clase."] = "Votre session, votre journal, des rappels et votre prochaine étape, aux couleurs de votre classe.",
	["Tu siguiente mazmorra"] = "Votre prochain donjon",
	["Tu siguiente paso"] = "Votre prochaine étape",
	["Tu siguiente paso, lo urgente y lo de tu clase, de un vistazo."] = "Votre prochaine étape, l'urgent et votre classe, d'un coup d'œil.",
	["Tu siguiente talento"] = "Votre prochain talent",
	["Tu tecla del mapa (%s) lo abre."] = "Votre touche de carte (%s) l'ouvre.",
	["Tu tecla primero te pone la mejor caña y lo que tengas con bonificación de pesca (sombrero, guantes, botas, abalorios)."] = "Votre touche équipe d'abord votre meilleure canne et tout ce qui a un bonus de pêche (chapeau, gants, bottes, bijoux).",
	["Tu tecla y tus ajustes del juego quedan como siempre. Enciéndela para pescar con una sola tecla."] = "Votre touche et vos réglages du jeu restent comme toujours. Activez-la pour pêcher avec une seule touche.",
	["Tu ventana de Alfa"] = "Votre fenêtre Alfa",
	["Tu vida baja: Rejuvenecimiento te cura poco a poco."] = "Votre vie baisse : Récupération vous soigne peu à peu.",
	["Tu vida baja: Renovar te cura poco a poco."] = "Votre vie baisse : Rénovation vous soigne peu à peu.",
	["Tu vida baja: el escudo absorbe el daño."] = "Votre vie baisse : le bouclier absorbe les dégâts.",
	["Tu vida está a punto de acabarse: Imposición de manos te cura entero."] = "Votre vie est sur le point de s'épuiser : Imposition des mains vous soigne entièrement.",
	["Tu vida está baja: cúrate rápido."] = "Vos points de vie sont bas : soignez-vous vite.",
	["Tu vida está baja: cúrate."] = "Vos points de vie sont bas : soignez-vous.",
	["Tu vida está baja: róbasela al enemigo."] = "Vos points de vie sont bas : volez-les à l'ennemi.",
	["Tu vida está muy baja: cúrate rápido."] = "Vos points de vie sont très bas : soignez-vous vite.",
	["Tu vuelo en el mapa"] = "Ton vol sur la carte",
	["Tu árbol"] = "Votre arbre",
	["Tu última sesión: %s · %s"] = "Votre dernière session : %s · %s",
	["Tu último escaneo fue %s. Escanea otra vez en la casa de subastas para tener precios al día."] = "Votre dernier scan : %s. Scannez à nouveau à l'hôtel des ventes pour avoir des prix à jour.",
	["Turalyon y Alleria Brisaveloz cruzaron el Portal Oscuro tras la guerra para cerrarles el paso a los orcos, y no regresaron."] = "Turalyon et Alleria Coursevent ont franchi la Porte des Ténèbres après la guerre pour barrer la route aux orcs, et ne sont jamais revenus.",
	["Tus %d puntos están donde tu build los pide. Lo que sigue es el equipo: piezas con las estadísticas que le sirven a tu build."] = "Vos %d points sont là où votre build les veut. La suite, c'est l'équipement : des pièces avec les caractéristiques utiles à votre build.",
	["Tus actitudes son de batalla, defensiva y rabiosa; elige la que pida el momento."] = "Tes postures sont combat, défensive et berserker ; choisis celle que demande le moment.",
	["Tus ajustes pasan una prueba de guardar y recargar en cada versión, para que nunca se pierdan."] = "Vos réglages passent un test d'enregistrement et de rechargement à chaque version, pour ne jamais se perdre.",
	["Tus avisos"] = "Vos alertes",
	["Tus bolsas"] = "Vos sacs",
	["Tus bolsas están casi llenas"] = "Vos sacs sont presque pleins",
	["Tus bolsas están llenas"] = "Vos sacs sont pleins",
	["Tus bolsas están vacías"] = "Vos sacs sont vides",
	["Tus bolsas piden auxilio (%d libres). Vende o tira lo que ya no uses."] = "Tes sacs appellent au secours (%d libres). Vends ou jette ce que tu n'utilises plus.",
	["Tus bolsas se están llenando"] = "Vos sacs se remplissent",
	["Tus bolsas se están llenando: queda 1 casilla."] = "Vos sacs se remplissent : il reste 1 emplacement.",
	["Tus bolsas se están llenando: quedan %d casillas."] = "Vos sacs se remplissent : il reste %d emplacements.",
	["Tus bolsas y tu banco en una sola ventana, y lo que lleva cada uno de tus personajes."] = "Vos sacs et votre banque dans une seule fenêtre, et ce que porte chacun de vos personnages.",
	["Tus builds importados"] = "Vos builds importés",
	["Tus clics"] = "Vos clics",
	["Tus clics de Curación se aplican al salir de combate."] = "Vos clics de Soins s'appliqueront à la sortie du combat.",
	["Tus clics vuelven a los del preajuste. Lo que cambiaste a mano se pierde."] = "Vos clics reviennent à ceux du préréglage. Ce que vous avez changé à la main est perdu.",
	["Tus comodidades están listas"] = "Votre confort de jeu est prêt",
	["Tus compañeros de grupo y de banda en el mapa de Alfa."] = "Les membres de votre groupe et de votre raid sur la carte d'Alfa.",
	["Tus críticos de habilidades pegan todavía más."] = "Les critiques de vos techniques frappent encore plus fort.",
	["Tus críticos hacen muchísimo daño."] = "Vos critiques font énormément de dégâts.",
	["Tus críticos hacen sangrar: matas más rápido y sufres menos."] = "Vos critiques font saigner : vous tuez plus vite et souffrez moins.",
	["Tus críticos sangran."] = "Vos critiques font saigner.",
	["Tus críticos sangran: más daño y amenaza."] = "Vos critiques font saigner : plus de dégâts et de menace.",
	["Tus curas curan más."] = "Vos soins soignent davantage.",
	["Tus datos"] = "Vos données",
	["Tus demonios llegan con misiones: diablillo, abisario, súcubo y manáfago; y más adelante, el infernal y el guardia apocalíptico."] = "Tes démons arrivent par des quêtes : diablotin, marcheur du Vide, succube et chasseur corrompu ; et plus tard, l'infernal et le garde funeste.",
	["Tus estadísticas"] = "Vos statistiques",
	["Tus extras"] = "Tes extras",
	["Tus flechas de mejora no usan tu build"] = "Vos flèches d'amélioration n'utilisent pas votre build",
	["Tus flechas de mejora usan tu build"] = "Vos flèches d'amélioration utilisent votre build",
	["Tus golpes alcanzan a un segundo enemigo: perfecto cuando se te juntan dos."] = "Vos coups touchent un second ennemi : parfait quand deux ennemis s'en prennent à vous.",
	["Tus gritos llegan más lejos y duran más: ayudas a todo el grupo."] = "Vos cris portent plus loin et durent plus longtemps : vous aidez tout le groupe.",
	["Tus habilidades cuestan menos ira."] = "Vos techniques coûtent moins de rage.",
	["Tus habilidades de ira te curan: menos descanso."] = "Vos techniques de rage vous soignent : moins de repos.",
	["Tus habilidades nuevas"] = "Vos nouvelles techniques",
	["Tus hechizos de daño pegan más."] = "Vos sorts de dégâts frappent plus fort.",
	["Tus hechizos de escarcha frenan: el monstruo casi nunca llega a pegarte."] = "Vos sorts de givre ralentissent : le monstre n'arrive presque jamais à vous frapper.",
	["Tus hechizos fallan menos."] = "Vos sorts ratent moins.",
	["Tus hechizos hacen crítico más seguido."] = "Vos sorts font plus souvent des critiques.",
	["Tus herramientas de combate"] = "Vos outils de combat",
	["Tus historias"] = "Vos histoires",
	["Tus llaves junto a tus bolsas."] = "Vos clés à côté de vos sacs.",
	["Tus marcadores"] = "Vos marqueurs",
	["Tus marcadores en el mapa de Alfa y en el del juego."] = "Vos marqueurs sur la carte d'Alfa et sur celle du jeu.",
	["Tus marcadores también en el minimapa, cuando estás cerca."] = "Vos marqueurs aussi sur la minicarte, quand vous êtes proche.",
	["Tus marcos de combate volvieron a su lugar de siempre."] = "Tes cadres de combat sont revenus à leur place habituelle.",
	["Tus marcos de combate vuelven a su lugar de siempre."] = "Vos cadres de combat reviennent à leur place habituelle.",
	["Tus marcos de curación están apagados"] = "Vos cadres de soins sont désactivés",
	["Tus marcos están listos"] = "Vos cadres sont prêts",
	["Tus metas en tu orden: un objeto, oro, una profesión, un lugar..."] = "Vos objectifs dans votre ordre : un objet, de l'or, un métier, un lieu...",
	["Tus misiones"] = "Vos quêtes",
	["Tus misiones abiertas, para terminarlas y entregarlas por el camino más corto."] = "Vos quêtes en cours, à terminer et à rendre par le chemin le plus court.",
	["Tus números"] = "Vos chiffres",
	["Tus personajes"] = "Vos personnages",
	["Tus precios de la subasta son viejos: escanéala otra vez."] = "Vos prix de l'hôtel des ventes sont anciens : scannez-le à nouveau.",
	["Tus profesiones"] = "Vos métiers",
	["Tus próximos golpes también alcanzan a otro enemigo."] = "Vos prochains coups touchent aussi un autre ennemi.",
	["Tus puntos"] = "Vos points",
	["Tus puntos van por otro camino"] = "Vos points ont pris un autre chemin",
	["Tus recetas de pescado, la cola de cocina y la fogata."] = "Vos recettes de poisson, la file de cuisine et le feu de camp.",
	["Tus recetas que dejan ganancia"] = "Vos recettes rentables",
	["Tus talentos"] = "Vos talents",
	["Tus tótems de tierra, fuego, agua y aire se ganan con misiones a lo largo de tu camino."] = "Tes totems de terre, de feu, d'eau et d'air s'obtiennent par des quêtes tout au long de ton chemin.",
	["Tyrande liberó a Illidan para pelear contra la Plaga, y Maiev, su carcelera, nunca se lo perdonó."] = "Tyrande a libéré Illidan pour combattre le Fléau, et Maiev, sa geôlière, ne le lui a jamais pardonné.",
	["Tótem"] = "Totem",
	["Tótems"] = "Totems",
	["Tótems enemigos"] = "Totems ennemis",
	["Tú"] = "Vous",
	["Tú recibes los golpes y proteges al grupo. Necesitas escudo."] = "Vous encaissez les coups et protégez le groupe. Il vous faut un bouclier.",
	["Ubicación de %s"] = "Position de %s",
	["Ultra"] = "Ultra",
	["Un arma en cada mano y mucha ira: el que más daño hace en grupo."] = "Une arme dans chaque main et beaucoup de rage : celui qui fait le plus de dégâts en groupe.",
	["Un arma grande de dos manos y golpes que hacen sangrar. La forma más fácil de subir."] = "Une grande arme à deux mains et des coups qui font saigner. La façon la plus facile de monter.",
	["Un aturdimiento cuando lo necesites."] = "Un étourdissement quand vous en avez besoin.",
	["Un aullido corto cada vez que entregas una misión. Viene apagado."] = "Un court hurlement chaque fois que tu rends une quête. Désactivé par défaut.",
	["Un aullido de lobo, del propio juego, la primera vez que abres Alfa en cada sesión."] = "Un hurlement de loup, tiré du jeu, la première fois que vous ouvrez Alfa à chaque session.",
	["Un aviso con sus jefes y lo que llevas vencido, con un clic a sus consejos."] = "Une alerte avec ses boss et ceux que vous avez vaincus, à un clic de leurs conseils.",
	["Un aviso corto con el lugar, su zona y el tiempo de camino."] = "Un avis court avec le lieu, sa zone et le temps de trajet.",
	["Un aviso corto cuando se activa una habilidad que depende de lo que pasó, como Abrumar después de que el enemigo esquive."] = "Une courte alerte quand une technique qui dépend de ce qui vient de se passer s'active, comme Fulgurance après une esquive de l'ennemi.",
	["Un aviso cuando vences a un jefe nuevo, con un clic a su botín."] = "Une alerte quand vous vainquez un nouveau boss, à un clic de son butin.",
	["Un aviso y una franja en tus bolsas con qué vender, qué conservar y a qué comerciante ir, con un clic para marcar la chatarra."] = "Une alerte et un bandeau dans vos sacs avec quoi vendre, quoi garder et chez quel marchand aller, avec un clic pour marquer la camelote.",
	["Un barrido oscuro y suave sobre los íconos mientras su recarga corre."] = "Un balayage sombre et doux sur les icônes pendant leur recharge.",
	["Un borde del color de la calidad: verde, azul, morado..."] = "Une bordure de la couleur de la qualité : vert, bleu, violet...",
	["Un borde verde que late sobre el botón de tu barra con la habilidad sugerida, para encontrarlo rápido."] = "Une bordure verte qui pulse sur le bouton de votre barre portant la technique suggérée, pour le trouver vite.",
	["Un brujo con dos compañeros puede invocar al resto del grupo a la entrada de una mazmorra."] = "Un démoniste avec deux aides peut invoquer le reste du groupe à l'entrée d'un donjon.",
	["Un buzón"] = "Une boîte aux lettres",
	["Un clic bajito cuando Lya te dice algo."] = "Un petit clic discret quand Lya vous dit quelque chose.",
	["Un clic y queda solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "Un clic et il ne reste que l'essentiel : vous, votre groupe, vos marqueurs et la prochaine étape du guide.",
	["Un cuadro pequeño y movible con tu vida y las estadísticas que más pesan para tu clase. En combate el juego oculta algunos números: se queda el último que se pudo leer."] = "Un petit cadre déplaçable avec votre vie et les caractéristiques qui comptent le plus pour votre classe. En combat, le jeu masque certains chiffres : le dernier lisible reste affiché.",
	["Un enemigo"] = "Un ennemi",
	["Un error, una mejora o un comentario, directo al desarrollador"] = "Un bug, une idée ou un commentaire, directement au développeur",
	["Un fondo del color de tu clase bajo tu nombre."] = "Un fond de la couleur de votre classe sous votre nom.",
	["Un golpe enorme con el escudo y muchísima amenaza."] = "Un énorme coup de bouclier et énormément de menace.",
	["Un golpe más para gastar ira."] = "Un coup de plus pour dépenser la rage.",
	["Un golpe nuevo y fuerte para tu barra."] = "Un nouveau coup puissant pour votre barre.",
	["Un gran aumento de daño para monstruos difíciles; además te libra del miedo."] = "Un gros bonus de dégâts pour les monstres difficiles ; il vous libère aussi de la peur.",
	["Un grano fino de cine sobre el mundo."] = "Un fin grain de cinéma sur le monde.",
	["Un grano fino, como de cine. Casi no cuesta: se mueve unas 14 veces por segundo y solo mientras se ve."] = "Un grain fin, comme au cinéma. Ne coûte presque rien : il bouge environ 14 fois par seconde et seulement quand il est visible.",
	["Un hechizo de tus barras tiene un rango viejo"] = "Un sort de vos barres est d'un ancien rang",
	["Un mapa de una pieza: al acercar ya no se ven pedazos pegados, y el terreno se une sin rayas ni cuadros."] = "Une carte d'un seul tenant : en zoomant, on ne voit plus de morceaux collés, et le terrain se raccorde sans lignes ni carrés.",
	["Un mapa impecable"] = "Une carte impeccable",
	["Un marco dorado en lo que sirve para una misión (con «!» si empieza una)."] = "Un cadre doré sur ce qui sert à une quête (avec « ! » si l'objet en commence une).",
	["Un objeto que quieres: Alfa arma el camino para conseguirlo, con lo que haga falta antes."] = "Un objet que vous voulez : Alfa crée le chemin pour l'obtenir, avec tout ce qu'il faut avant.",
	["Un paisaje más bonito"] = "Un plus beau paysage",
	["Un pescadito asado no me caería nada mal."] = "Un petit poisson grillé ne me ferait pas de mal.",
	["Un pescadito asado para la loba que te acompaña no estaría nada mal, ¿eh?"] = "Un petit poisson grillé pour la louve qui t'accompagne, ce ne serait pas de refus, hein ?",
	["Un pin pequeño con su número donde te llevan los próximos pasos."] = "Un petit repère numéroté là où vous mènent les prochaines étapes.",
	["Un poco de golpe crítico, de esquivar y de armadura."] = "Un peu de coup critique, d'esquive et d'armure.",
	["Un poco de vida de vuelta después de críticos."] = "Un peu de vie récupérée après les critiques.",
	["Un poco más de defensa."] = "Un peu plus de défense.",
	["Un poco más de ira al cargar."] = "Un peu plus de rage en chargeant.",
	["Un punto para abrir la siguiente fila y fallar un poco menos."] = "Un point pour ouvrir la rangée suivante et rater un peu moins.",
	["Un servicio cercano, un marcador de tu mapa, donde estás ahora o la entrada de una mazmorra."] = "Un service proche, un marqueur de votre carte, l'endroit où vous êtes ou l'entrée d'un donjon.",
	["Un signo de exclamación sobre quien te da misiones de tu nivel."] = "Un point d'exclamation au-dessus de ceux qui donnent des quêtes de votre niveau.",
	["Un signo de interrogación sobre quien recibe una misión ya lista."] = "Un point d'interrogation au-dessus de ceux qui attendent une quête terminée.",
	["Un solo addon con todo lo que usas al jugar: guías paso a paso con flecha y ruta, mapa, bolsas, builds, curación con clic, recolección, mazmorras, pesca y comercio. Todo con el mismo estilo."] = "Un seul addon avec tout ce que vous utilisez en jouant : guides pas à pas avec flèche et itinéraire, carte, sacs, builds, soins en un clic, récolte, donjons, pêche et commerce. Le tout dans le même style.",
	["Un tanque que pega fuerte: mucha amenaza para grupos que hacen mucho daño, a cambio de menos defensa extra. Para tanques con algo de experiencia."] = "Un tank qui frappe fort : beaucoup de menace pour les groupes qui font beaucoup de dégâts, en échange de moins de défense en plus. Pour les tanks qui ont un peu d'expérience.",
	["Un tramo más en la ruta que armas en la página Ruta: Alfa elige el camino para conseguirlo."] = "Un tronçon de plus dans l'itinéraire que vous créez sur la page Itinéraire : Alfa choisit le chemin pour l'obtenir.",
	["Un «?» en cada página de Alfa para que Lya te la explique, y su propia tecla."] = "Un « ? » sur chaque page d’Alfa pour que Lya te l’explique, et sa propre touche.",
	["Un ícono con la habilidad que conviene ahora. Solo muestra: nunca aprieta nada por ti."] = "Une icône avec la technique la plus utile maintenant. Elle ne fait que montrer : elle n'appuie jamais à votre place.",
	["Un ícono de misión en la placa de nombre de los enemigos y personajes que todavía necesitas para una misión de tu registro. En mazmorras el juego oculta esos datos y no se marcan."] = "Une icône de quête sur la barre de nom des ennemis et personnages dont vous avez encore besoin pour une quête de votre journal. Dans les donjons, le jeu masque ces données et ils ne sont pas marqués.",
	["Una acción recomendada en grande y tu camino en un par de clics."] = "Une grande action recommandée, et votre chemin en quelques clics.",
	["Una barra con los ataques que el jefe va a hacer y cuánto falta para cada uno. Así sabes cuándo moverte o defenderte."] = "Une barre avec les attaques que le boss va lancer et le temps restant avant chacune. Vous savez ainsi quand bouger ou vous défendre.",
	["Una bienvenida nueva en 9 pasos con la intro del lobo: eliges el idioma de Alfa (hay 10) y cada cosa que hace sola por ti."] = "Un nouvel accueil en 9 étapes avec l'intro du loup : vous choisissez la langue d'Alfa (il y en a 10) et tout ce qu'il fait seul pour vous.",
	["Una cadena de texto lleva un build completo: la copias, la pasas y la pegan."] = "Une ligne de texte contient un build complet : vous la copiez, la transmettez et ils la collent.",
	["Una cantidad de oro; se cumple cuando la llevas encima."] = "Une somme d'or ; c'est rempli quand vous l'avez sur vous.",
	["Una categoría…"] = "Une catégorie…",
	["Una cuenta de prueba no puede compartir"] = "Un compte d'essai ne peut pas partager",
	["Una fila con vuelo, posada, reparar, banco, buzón y tu entrenador, a un clic."] = "Une rangée avec vol, auberge, réparation, banque, boîte aux lettres et votre maître, à un clic.",
	["Una flecha en pantalla que apunta a tu siguiente objetivo, con la distancia. Apagada: tú decides por dónde ir."] = "Une flèche à l'écran qui pointe vers votre prochain objectif, avec la distance. Désactivée : vous choisissez votre chemin.",
	["Una flecha verde en cada objeto de tus bolsas que es una mejora para tu especialización."] = "Une flèche verte sur chaque objet de vos sacs qui est une amélioration pour votre spécialisation.",
	["Una flecha verde en el equipo que es mejor que lo que llevas puesto, según tu clase y nivel."] = "Une flèche verte sur l'équipement meilleur que celui que vous portez, selon votre classe et votre niveau.",
	["Una franja verde clara muestra las curas que ya vienen en camino."] = "Une bande vert clair montre les soins déjà en route.",
	["Una guía para tu nivel y tu zona, o tu propia ruta de misiones."] = "Un guide pour votre niveau et votre zone, ou votre propre itinéraire de quêtes.",
	["Una loba gordita como yo necesita sus tres comidas... y sus botanas."] = "Une louve dodue comme moi a besoin de ses trois repas... et de ses grignotages.",
	["Una loba negra que te da consejos y ánimo en el camino, sin estorbar. En memoria de una gran perrita."] = "Une louve noire qui vous donne conseils et encouragements en route, sans gêner. En mémoire d'une merveilleuse petite chienne.",
	["Una línea con el enlace de la misión cuando completas sus objetivos, otra cuando está lista para entregar y otra al entregarla. En grupo la ve todo el grupo, con o sin Alfa; solo, sale en tu chat. Nunca en banda."] = "Une ligne avec le lien de la quête quand tu remplis ses objectifs, une autre quand elle est prête à rendre et une autre quand tu la rends. En groupe, tout le groupe la voit, avec ou sans Alfa ; seul, elle s’affiche dans ton chat. Jamais en raid.",
	["Una línea corta debajo del ícono, como «Golpe mortal: recarga lista». Cada una sale hasta 4 veces y luego se calla; su × la calla antes."] = "Une courte ligne sous l'icône, comme « Frappe mortelle : recharge prête ». Chacune s'affiche jusqu'à 4 fois puis se tait ; son × la fait taire plus tôt.",
	["Una línea debajo del aviso con lo que pasó."] = "Une ligne sous l'alerte avec ce qui s'est passé.",
	["Una línea roja arriba avisa cuando un enemigo va por ese compañero."] = "Une ligne rouge en haut prévient quand un ennemi s'en prend à ce membre.",
	["Una mano"] = "Une main",
	["Una meta que marcas tú (el botón de hecha del rastreador o de esta lista)."] = "Un objectif que vous cochez vous-même (le bouton fait du suivi ou de cette liste).",
	["Una misión"] = "Une quête",
	["Una moneda sobre lo gris y lo que marcaste como chatarra."] = "Une pièce sur les objets gris et ce que vous avez marqué comme camelote.",
	["Una nota con el instructor más cercano cuando tienes habilidades nuevas."] = "Un avis avec le maître le plus proche quand vous avez de nouvelles techniques.",
	["Una revisión completa de todos los módulos: más de 60 arreglos."] = "Une révision complète de tous les modules : plus de 60 corrections.",
	["Una revisión completa para la versión estable: más de 20 arreglos en mazmorras con grupo, combate, el mapa, Pesca, Talentos y más."] = "Une révision complète pour la version stable : plus de 20 corrections en donjon de groupe, en combat, sur la carte, la pêche, les talents et plus.",
	["Una ruta es tu árbol de tramos: misiones de XP, de oro, de clase, materiales u objetos. Elige una de estas para empezar:"] = "Un itinéraire est votre arbre de tronçons : quêtes d'XP, d'or ou de classe, matériaux ou objets. Choisissez-en un pour commencer :",
	["Una ruta necesita al menos 3 lugares que tu habilidad alcance. Elige otro tipo o recurso abajo, o recolecta aquí: Alfa anota cada nodo que encuentras."] = "Un itinéraire demande au moins 3 lieux à la portée de votre compétence. Choisissez un autre type ou une autre ressource plus bas, ou récoltez ici : Alfa note chaque nœud que vous trouvez.",
	["Una ruta por los mejores lugares para tu habilidad, con unas misiones de XP en medio."] = "Un itinéraire par les meilleurs lieux pour votre compétence, avec quelques quêtes d'XP entre-temps.",
	["Una salchicha al día mantiene a la loba feliz. Es ciencia."] = "Une saucisse par jour rend la louve heureuse. C'est scientifique.",
	["Una sesión termina tras 20 minutos sin lanzar o cuando empiezas otra; entonces aparece aquí con lo que sacaste y dónde."] = "Une session se termine après 20 minutes sans lancer ou quand vous en commencez une autre ; elle apparaît alors ici avec vos prises et l'endroit.",
	["Una sesión tranquila: nada nuevo que contar."] = "Une session tranquille : rien de neuf à signaler.",
	["Una tecla para todo: equipo, cebo, lanzar y recoger. Con diario, guía, cocina, metas y estadísticas."] = "Une touche pour tout : équipement, appât, lancer et remonter. Avec journal, guide, cuisine, objectifs et statistiques.",
	["Une los %d lugares que tu habilidad alcanza en una vuelta corta, la dibuja en el mapa y la flecha te lleva de parada en parada."] = "Relie les %d lieux à la portée de votre compétence en une boucle courte, la trace sur la carte, et la flèche vous mène d'étape en étape.",
	["Unir las capas de sombra"] = "Fondre les couches d'ombre",
	["Unirte al grupo de tus amigos"] = "Rejoindre le groupe de vos amis",
	["Uno de los dragones verdes de la pesadilla aparece en el Bosque del Ocaso, junto a un gran árbol."] = "L'un des dragons verts du cauchemar apparaît dans le bois de la Pénombre, près d'un grand arbre.",
	["Uno menos"] = "Un de moins",
	["Uno más"] = "Un de plus",
	["Unos pocos altos elfos siguen con la Alianza; viven en Quel'Danil, en las Tierras del Interior."] = "Quelques hauts-elfes restent avec l'Alliance ; ils vivent à Quel'Danil, dans les Hinterlands.",
	["Unos prefieren que yo haga lo aburrido y otros quieren hacerlo todo. Tú dime, y si cambias de idea, lo cambias cuando quieras."] = "Certains préfèrent que je fasse le plus ennuyeux, d’autres veulent tout faire. Dis-moi, et si tu changes d’avis, tu le changes quand tu veux.",
	["Usa %s"] = "Utilisez %s",
