	["¡%d misiones hoy! A este paso me debes una salchicha."] = "%d quêtes aujourd’hui ! À ce rythme, tu me dois une saucisse.",
	["¡%d misiones hoy! Estás que no te para nadie."] = "%d quêtes aujourd'hui ! Rien ne t'arrête.",
	["¡%s subió a nivel %d! Auuuu, felicidades."] = "%s a atteint le niveau %d ! Ahouuu, félicitations.",
	["¡%s!"] = "%s !",
	["¡%s! Hace días que no te veía. En Hoy te digo dónde íbamos."] = "%s ! Ça fait des jours que je ne t'avais pas vu. Dans Aujourd'hui, je te dis où on en était.",
	["¡%s! Te extrañé mucho. Vine corriendo en cuanto te vi llegar."] = "%s ! Tu m'as tellement manqué. J'ai accouru dès ton arrivée.",
	["¡%s, volviste! Te extrañé tanto que no paraba de mover la cola."] = "%s, tu es de retour ! Tu m'as tellement manqué que je n'arrêtais pas de remuer la queue.",
	["¡Abrumar!"] = "Fulgurance !",
	["¡Ahí estás, %s! Si quieres un consejo, dame clic."] = "Te voilà, %s ! Si tu veux un conseil, clique sur moi.",
	["¡Ahí estás, %s! Te estaba esperando… te extrañé."] = "Ah, te voilà, %s ! Je t'attendais… tu m'as manqué.",
	["¡Arriba, lobo! Antes de volver a pelear, recupera vida y maná."] = "Debout, loup ! Avant de reprendre le combat, récupère vie et mana.",
	["¡Arriba, lobo! Caer es parte de la cacería. Al revivir, repara tu equipo."] = "Debout, loup ! Tomber fait partie de la chasse. Une fois revenu, répare ton équipement.",
	["¡Arriba, lobo! Libera tu espíritu: la flecha te dice si conviene tu cuerpo o el sanador."] = "Debout, loup ! Libère ton esprit : la flèche te dit s'il vaut mieux rejoindre ton corps ou l'esprit guérisseur.",
	["¡Arriba, lobo! Si eran muchos, la próxima jálalos de uno en uno."] = "Debout, loup ! S'ils étaient trop nombreux, la prochaine fois attire-les un par un.",
	["¡Arriba, nivel %d! Si tienes un punto de talento libre, no lo olvides."] = "Debout, niveau %d ! Si tu as un point de talent libre, ne l'oublie pas.",
	["¡Así se ve un aviso!"] = "Voici à quoi ressemble une alerte !",
	["¡Ataque de la victoria!"] = "Ivresse de la victoire !",
	["¡Bien hecho! %s"] = "Bien joué ! %s",
	["¡Buen día, %s! El sol ya salió en Azeroth. ¿Vamos?"] = "Bonjour, %s ! Le soleil s'est levé sur Azeroth. On y va ?",
	["¡Buenas noches, %s! Las lobas cazamos mejor de noche."] = "Bonsoir, %s ! Nous, les louves, chassons mieux la nuit.",
	["¡Buenas tardes, %s! Buena hora para unas misiones."] = "Bon après-midi, %s ! C'est le bon moment pour quelques quêtes.",
	["¡Buenas, %s! Paso a paso se llega lejos."] = "Salut, %s ! Pas à pas, on va loin.",
	["¡Buenos días, %s! Me estiro, bostezo y estoy lista."] = "Bonjour, %s ! Je m'étire, je bâille et je suis prête.",
	["¡Completaste %s!"] = "Vous avez terminé %s !",
	["¡Contraataque!"] = "Contre-attaque !",
	["¡De vuelta con la manada!"] = "De retour avec la meute !",
	["¡De vuelta en la manada, %s!"] = "De retour dans la meute, %s !",
	["¡Ejecutar!"] = "Exécution !",
	["¡En Thelsamar venden morcilla! La morcilla de Thelsamar es casi una salchicha... ¿me compras una?"] = "On vend du boudin à Thelsamar ! Le boudin de Thelsamar, c'est presque une saucisse... tu m'en achètes un ?",
	["¡Es ahora! Hasta las %s"] = "C'est maintenant ! Jusqu'à %s",
	["¡Felicidades por el nivel %d, %s! Auuuu."] = "Bravo pour le niveau %d, %s ! Ahouuu.",
	["¡Hay algo nuevo en Alfa: %s! ¿Te lo enseño?"] = "Il y a du nouveau dans Alfa : %s ! Je te montre ?",
	["¡Hola!"] = "Bonjour !",
	["¡Hola! Pregúntame lo que quieras de Alfa: te lo explico corto y te llevo."] = "Salut ! Demande-moi ce que tu veux sur Alfa : je t’explique en bref et je t’y emmène.",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Cuido a la manada y voy contigo en el camino."] = "Salut ! Je suis Lya, la louve de confiance de l'Alfa. Je veille sur la meute et je fais la route avec toi.",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Voy a acompañarte en esta configuración y después en tu camino."] = "Salut ! Je suis Lya, la louve de confiance de l’Alpha. Je t’accompagne dans cette configuration, puis sur ton chemin.",
	["¡Hola, %s!"] = "Bonjour, %s !",
	["¡Hola, %s! Hoy huele a buena cacería."] = "Bonjour, %s ! Aujourd'hui, ça sent la bonne chasse.",
	["¡Hola, %s! La tarde pinta tranquila. ¿Qué cazamos hoy?"] = "Salut, %s ! L'après-midi s'annonce calme. On chasse quoi aujourd'hui ?",
	["¡Hola, %s! Noche de luna: perfecta para la manada."] = "Salut, %s ! Une nuit de lune : parfaite pour la meute.",
	["¡Listo! %s precios guardados."] = "Terminé ! %s prix enregistrés.",
	["¡Listo! Alfa ya es tuyo"] = "C'est prêt ! Alfa est à vous",
	["¡Lo tienes! %s ×%d"] = "Attrapé ! %s ×%d",
	["¡Martillo de cólera!"] = "Marteau de courroux !",
	["¡Misión completada: %s!"] = "Quête terminée : %s !",
	["¡Mordedura de mangosta!"] = "Morsure de la mangouste !",
	["¡Nivel %d! Date un momento para presumirlo, te lo ganaste."] = "Niveau %d ! Prends un moment pour t'en vanter, tu l'as mérité.",
	["¡Nivel %d! Paso firme y colmillo afilado."] = "Niveau %d ! Pas assuré et crocs affûtés.",
	["¡Nivel %d! Tu esfuerzo se nota. Sigue así."] = "Niveau %d ! Tes efforts se voient. Continue comme ça.",
	["¡Nivel %d! ¡Auuu! Así se sube en manada."] = "Niveau %d ! Aouuu ! C'est comme ça qu'on monte en meute.",
	["¡Nivel %d, bien hecho! Revisa si tu entrenador tiene algo nuevo."] = "Niveau %d, bien joué ! Vois si ton maître a du nouveau.",
	["¡Nivel 10! Ya tienes talentos: elígelos con calma, Talentos te ayuda."] = "Niveau 10 ! Tu as des talents : choisis-les tranquillement, Talents t'aide.",
	["¡Nivel 20! Ya puedes con mazmorras de verdad. ¿Armamos grupo?"] = "Niveau 20 ! Tu peux faire de vrais donjons. On monte un groupe ?",
	["¡Nivel 30! Ya vas a la mitad del camino. ¡Qué orgullo de manada!"] = "Niveau 30 ! Tu es à mi-chemin. Quelle fierté pour la meute !",
	["¡Nivel 40! Ya puedes aprender a montar. ¡Tu primera montura te espera!"] = "Niveau 40 ! Tu peux apprendre la monte. Ta première monture t'attend !",
	["¡Nivel 50! Ya se huele la cima. Junta oro para lo que viene."] = "Niveau 50 ! On sent déjà le sommet. Réunis de l'or pour la suite.",
	["¡Nivel 60! ¡Lo lograste, alfa! Ahora toca cazar en grande."] = "Niveau 60 ! Tu as réussi, alpha ! Place à la grande chasse.",
	["¡Nuevo récord: %d misiones en un día! Ni la manada te alcanza."] = "Nouveau record : %d quêtes en un jour ! Même la meute ne te suit pas.",
	["¡Plan terminado!"] = "Plan terminé !",
	["¡Primera vez! Nuevo en tu diario"] = "Première fois ! Nouveau dans votre journal",
	["¡Qué buena racha traes! Sigue así."] = "Quelle belle série ! Continue comme ça.",
	["¡Qué bueno tenerte de vuelta, %s! Aquí sigo, cuidándote la espalda."] = "Ça fait plaisir de te revoir, %s ! Je suis toujours là, à surveiller tes arrières.",
	["¡Qué gusto verte de vuelta! Esto es lo que trae esta versión para ti y tu manada."] = "Quel plaisir de vous revoir ! Voici ce que cette version apporte pour vous et votre meute.",
	["¡Qué gusto verte, %s! La manada ya te esperaba."] = "Quel plaisir de te voir, %s ! La meute t'attendait.",
	["¡Repara tu equipo!"] = "Réparez votre équipement !",
	["¡Revancha!"] = "Vengeance !",
	["¡Subiste a nivel %d! Cada nivel te hace más fuerte."] = "Tu es passé niveau %d ! Chaque niveau te rend plus fort.",
	["¡Sí, acompáñame!"] = "Oui, accompagne-moi !",
	["¡Te extrañé, %s! Corrí hasta aquí para verte."] = "Tu m'as manqué, %s ! J'ai couru jusqu'ici pour te voir.",
	["¡Te extrañé, %s! Tu ruta sigue donde la dejaste."] = "Tu m'as manqué, %s ! Ton itinéraire reprend là où tu l'as laissé.",
	["¡Terminaste %s!"] = "Vous avez terminé %s !",
	["¡Terminaste esta guía!"] = "Tu as terminé ce guide !",
	["¡Terminaste esta guía! Elige la siguiente y sigue subiendo con la manada."] = "Vous avez terminé ce guide ! Choisissez le suivant et continuez à monter avec la meute.",
	["¡Terminaste tu guía!"] = "Vous avez terminé votre guide !",
	["¡Tierra a la vista: %s!"] = "Terre en vue : %s !",
	["¡Tú!"] = "Vous !",
	["¡Van %d misiones hoy! La manada está orgullosa."] = "%d quêtes aujourd’hui ! La meute est fière.",
	["¡Volviste, %s! Estira las patas y vámonos."] = "Te revoilà, %s ! Dégourdis-toi les pattes et on y va.",
	["¡Voy!"] = "J’arrive !",
	["¡Ya eres nivel %d! La manada aúlla por ti."] = "Tu es niveau %d ! La meute hurle pour toi.",
	["¡Ya estás en la %s!"] = "Tu es dans la %s !",
	["¡Ya la desbloqueaste!"] = "Tu l’as débloquée !",
	["¡Ya llegaste, %s! Te extrañé. ¿A dónde vamos hoy?"] = "Te voilà, %s ! Tu m'as manqué. On va où aujourd'hui ?",
	["¡Ya llegó! Vamos, manada"] = "On y est ! En avant, la meute",
	["¡Ya terminaste %d misiones! Vamos a cobrar la recompensa."] = "Tu as terminé %d quêtes ! Allons chercher la récompense.",
	["¡Yo te la guardé! En Historias está todo lo que cuentan tus misiones, para leerlo cuando quieras."] = "Je te l’ai gardée ! Dans Histoires, il y a tout ce que racontent tes quêtes, à lire quand tu veux.",
	["«%s» tiene su historia. ¿Te la cuento?"] = "« %s » a son histoire. Je te la raconte ?",
	["«%s» ya quedó. Su final vale la pena, ¿te lo cuento?"] = "« %s » est terminée. Sa fin vaut le détour, je te la raconte ?",
	["«Alejar más la cámara» de Comodidades está encendido y manda sobre este valor al entrar."] = "« Reculer davantage la caméra » de Confort de jeu est activé et prend le dessus sur cette valeur à la connexion.",
	["«Buscar cerca» en la página Hoy"] = "« Chercher à proximité » sur la page Aujourd'hui",
	["«Buscar cerca» te lleva con flecha a lo que necesitas, y «Mis planes» arma tus propias metas, que se marcan solas."] = "« Chercher à proximité » vous mène avec la flèche à ce dont vous avez besoin, et « Mes plans » crée vos propres objectifs, qui se cochent tout seuls.",
	["«Cerrar mis misiones» está al día"] = "« Terminer mes quêtes » est à jour",
	["«Igual que Alfa» sigue el estilo de Ajustes > Apariencia y cambia con él."] = "« Comme Alfa » suit le style de Réglages > Apparence et change avec lui.",
	["«Invitar al clan» en el clic derecho"] = "« Inviter dans la guilde ou la communauté » au clic droit",
	["«Prepárame» recoge solo las que ya puedes tomar y te lleva a la entrada."] = "« Préparez-moi » récupère seulement celles que vous pouvez déjà prendre et vous mène à l'entrée.",
	["«Seguir» en La Jauría ya no se suelta cuando tu guía cambia de paso ni cuando vas por tu cuerpo: al terminar, la flecha vuelve con quien sigues."] = "« Suivre » dans La Jauría ne lâche plus quand votre guide change d'étape ni quand vous retournez à votre corps : ensuite, la flèche revient vers la personne que vous suivez.",
	["«Siempre» sirve si un amigo encantador te ayuda. Las tablas de desencantar son estimadas."] = "« Toujours » sert si un ami enchanteur vous aide. Les tables de désenchantement sont des estimations.",
	["«Ver el siguiente» te deja mirar el paso que viene y lo dice claro; y un solo contador de pasos hechos."] = "« Voir la suivante » vous laisse regarder l'étape qui vient et l'indique clairement ; et un seul compteur d'étapes faites.",
	["«[Misión] está lista para entregar» y «¡Misión completada!» en el chat del grupo, para todos. Apagado, solo te salen a ti."] = "« [Quête] est prête à rendre » et « Quête terminée ! » dans le chat du groupe, pour tous. Désactivé, toi seul les vois.",
	["«[Misión] está lista para entregar» y «¡Misión completada!». En grupo lo ve todo el grupo; solo, sale en tu chat."] = "« [Quête] est prête à rendre » et « Quête terminée ! ». En groupe, tout le groupe le voit ; seul, ça s’affiche dans ton chat.",
