	["¿En qué idioma quieres Alfa?"] = "Dans quelle langue voulez-vous Alfa ?",
	["¿En qué te ayudo?"] = "Je t’aide pour quoi ?",
	["¿En qué te ayudo? Toca una pregunta o una página y te cuento."] = "Je t’aide pour quoi ? Touche une question ou une page et je te raconte.",
	["¿Eso que huele es pan de la posada? Mi nariz nunca se equivoca."] = "Ça sent le pain de l'auberge, là ? Mon nez ne se trompe jamais.",
	["¿La haces con tu manada o la saltas?"] = "Vous la faites avec votre meute ou vous la sautez ?",
