	["¿Oíste eso? Nada… solo el viento. Sigamos."] = "Tu as entendu ? Rien… juste le vent. Continuons.",
	["¿Paramos a comer? Mi panza ya está aullando."] = "On s'arrête manger ? Mon ventre hurle déjà.",
	["¿Por dónde empiezo?"] = "Par où je commence ?",
	["¿Por dónde sigues?"] = "Par où continuez-vous ?",
	["¿Puedo cambiar cómo se ve Alfa?"] = "Je peux changer l’apparence d’Alfa ?",
	["¿Puedo llamarte con una tecla?"] = "Je peux t’appeler avec une touche ?",
	["¿Quieres cazar con nosotros? Pulsa el botón: Alfa busca a un oficial conectado y te abre un susurro con tu mensaje listo para que lo envíes con Intro."] = "Vous voulez chasser avec nous ? Appuyez sur le bouton : Alfa cherche un officier connecté et vous ouvre un chuchotement avec votre message prêt à envoyer avec Entrée.",
	["¿Quieres que la manada te vea en el mapa del juego?"] = "Voulez-vous que la meute vous voie sur la carte du jeu ?",
	["¿Quién eres, Lya?"] = "Qui es-tu, Lya ?",
	["¿Qué buscas?"] = "Que cherchez-vous ?",
	["¿Qué buscas? Escribe una palabra"] = "Tu cherches quoi ? Tape un mot",
	["¿Qué es Alfa?"] = "Qu'est-ce qu'Alfa ?",
	["¿Qué habilidad uso en combate?"] = "Quelle technique j’utilise en combat ?",
	["¿Qué hace Alfa con comerciantes y viajes?"] = "Que fait Alfa avec les marchands et les voyages ?",
