	["¿Qué me puede caer en una mazmorra?"] = "Que peut-il tomber dans un donjon ?",
	["¿Qué nos quieres contar?"] = "Que voulez-vous nous dire ?",
	["¿Qué quieres hacer hoy?"] = "Que voulez-vous faire aujourd'hui ?",
	["¿Qué quieres hacer?"] = "Que voulez-vous faire ?",
	["¿Qué responde Alfa por ti a otros jugadores?"] = "Que répond Alfa aux autres joueurs à votre place ?",
