	["¿Qué talentos pongo?"] = "Quels talents je prends ?",
	["¿Reiniciar los gráficos?"] = "Redémarrer les graphismes ?",
	["¿Sabías que las lobas tenemos el mejor oído de la manada? Bueno, eso digo yo."] = "Tu savais que nous, les louves, avons la meilleure ouïe de la meute ? Enfin, c'est ce que je dis.",
	["¿Sabías que…? Alfa junta tus misiones listas en una sola ruta corta."] = "Le savais-tu… ? Alfa regroupe tes quêtes terminées en un seul itinéraire court.",
	["¿Sabías que…? Alfa tiene tres estilos: Alfa, Clásico WoW y Cristal. Y yo me pongo el que elijas."] = "Le savais-tu… ? Alfa a trois styles : Alfa, WoW classique et Cristal. Et je porte celui que tu choisis.",
	["¿Sabías que…? Alt+clic en un objeto lo abre en la Enciclopedia."] = "Le savais-tu… ? Alt+clic sur un objet l'ouvre dans l'Encyclopédie.",
	["¿Sabías que…? Buscar cerca te lleva al herrero, al banco o al vuelo más cercano."] = "Le savais-tu… ? Chercher à proximité te mène au forgeron, à la banque ou au vol le plus proche.",
	["¿Sabías que…? Comercio te dice si algo conviene venderlo, subastarlo o convertirlo."] = "Le savais-tu… ? Commerce te dit s'il vaut mieux vendre un objet, le mettre aux enchères ou le transformer.",
	["¿Sabías que…? Con /alfa reportar le cuentas a toxic3000 de un error o una idea."] = "Le savais-tu… ? Avec /alfa reportar, tu parles à toxic3000 d'un bug ou d'une idée.",
	["¿Sabías que…? Con Pesca lanzas y recoges con una sola tecla."] = "Le savais-tu… ? Avec Pêche, tu lances et ramènes avec une seule touche.",
	["¿Sabías que…? Con clic derecho sobre mí puedes silenciarme una hora o pedirme menos consejos."] = "Le savais-tu… ? Avec un clic droit sur moi, tu peux me faire taire une heure ou me demander moins de conseils.",
	["¿Sabías que…? Con el botón del minimapa ocultas todo Alfa y lo vuelves a traer."] = "Le savais-tu… ? Le bouton de la minicarte cache tout Alfa et le fait revenir.",
	["¿Sabías que…? El mapa de Alfa muestra el terreno, tus marcadores y lo que hay cerca."] = "Le savais-tu… ? La carte d'Alfa montre le terrain, tes marqueurs et ce qu'il y a autour.",
	["¿Sabías que…? En Bolsas ves tus bolsas, tu banco y lo de todos tus personajes."] = "Le savais-tu… ? Dans Sacs, tu vois tes sacs, ta banque et ce que portent tous tes personnages.",
	["¿Sabías que…? En La Jauría ves a tu grupo y a la manada que usa Alfa."] = "Le savais-tu… ? Dans La Jauría, tu vois ton groupe et la meute qui utilise Alfa.",
	["¿Sabías que…? En Mis planes armas tu propia lista de metas y la flecha te guía."] = "Le savais-tu… ? Dans Mes plans, tu crées ta propre liste d'objectifs et la flèche te guide.",
	["¿Sabías que…? En Talentos ves qué talento poner ahora y por qué."] = "Le savais-tu… ? Dans Talents, tu vois quel talent prendre maintenant et pourquoi.",
